# ===== v24.26 SPLIT-DB BOOTSTRAP (Git files <25 MB) =====
def _bootstrap_split_db_v2426():
    """Rebuild the runtime SQLite DB from Git-safe parts when the DB file is absent.
    Non-destructive: never overwrites an existing runtime DB.
    """
    import os as _os
    base = _os.path.dirname(_os.path.abspath(__file__))
    target = _os.getenv('CIKGULAJU_DB_PATH', _os.path.join(base, 'CikguLaju_Curriculum_Master_v24_95_CORE.db'))
    parts = [_os.path.join(base, 'CikguLaju_DB_v24_24.part00'),
             _os.path.join(base, 'CikguLaju_DB_v24_24.part01')]
    if _os.path.exists(target):
        return target
    if not all(_os.path.isfile(x) for x in parts):
        return target
    tmp = target + '.rebuilding'
    try:
        _os.makedirs(_os.path.dirname(target) or base, exist_ok=True)
        with open(tmp, 'wb') as out:
            for part in parts:
                with open(part, 'rb') as src:
                    while True:
                        chunk = src.read(1024 * 1024)
                        if not chunk:
                            break
                        out.write(chunk)
        _os.replace(tmp, target)
        print('v24.26 split DB rebuilt:', target, flush=True)
    except Exception as e:
        try:
            if _os.path.exists(tmp): _os.remove(tmp)
        except Exception:
            pass
        print('v24.26 split DB rebuild failed:', repr(e), flush=True)
    return target

_bootstrap_split_db_v2426()
# ===== END v24.26 SPLIT-DB BOOTSTRAP =====

