def _feedback_schema():
    con=_db()
    try:
        con.execute("CREATE TABLE IF NOT EXISTS beta_feedback(id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Umum', feedback_text TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'baru')")
        con.commit()
    finally: con.close()

def _feedback_counts():
    _feedback_schema(); con=_db()
    try:
        rows=con.execute("SELECT status,COUNT(*) c FROM beta_feedback GROUP BY status").fetchall()
        d={str(r['status']):int(r['c']) for r in rows}; total=sum(d.values())
        return {'total':total,'baru':d.get('baru',0),'dibaca':d.get('dibaca',0),'selesai':d.get('selesai',0)}
    finally: con.close()

def _feedback_card(cid, feedback_id):
    if not _is_admin(cid): return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
    _feedback_schema(); con=_db()
    try:
        r=con.execute("SELECT f.*,u.first_name,u.last_name,u.username FROM beta_feedback f LEFT JOIN bot_users u ON u.chat_id=f.chat_id WHERE f.id=?",(int(feedback_id),)).fetchone()
    finally: con.close()
    if not r: return send(cid,'⚠️ Komen tidak ditemui.',[[{'text':'💬 Kembali','callback_data':'admin_feedback|0'}]])
    r=dict(r); name=_admin_user_name(r); st=str(r.get('status') or 'baru')
    icon={'baru':'🆕 BARU','dibaca':'👀 DIBACA','selesai':'✅ SELESAI'}.get(st,st.upper())
    text=(f'💬 <b>KOMEN & CADANGAN #{r["id"]}</b>\n\n👤 <b>{html.escape(name)}</b>\nTelegram ID: <code>{r["chat_id"]}</code>\n'
          f'📅 {html.escape(str(r["created_at"])[:19])}\n🏷️ {html.escape(str(r["category"]))}\nStatus: <b>{icon}</b>\n\n{html.escape(str(r["feedback_text"]))}')
    kb=[]
    if st!='dibaca': kb.append([{'text':'👀 TANDA DIBACA','callback_data':f'admin_feedback_status|{r["id"]}|dibaca'}])
    if st!='selesai': kb.append([{'text':'✅ TANDA SELESAI','callback_data':f'admin_feedback_status|{r["id"]}|selesai'}])
    if st!='baru': kb.append([{'text':'🆕 KEMBALIKAN KE BARU','callback_data':f'admin_feedback_status|{r["id"]}|baru'}])
    kb.append([{'text':'👤 LIHAT PENGGUNA','callback_data':f'admin_user|{r["chat_id"]}'},{'text':'💬 SENARAI KOMEN','callback_data':'admin_feedback|0'}])
    return send(cid,text,kb)

def _set_feedback_status(feedback_id,status):
    if status not in ('baru','dibaca','selesai'): return False
    _feedback_schema(); con=_db()
    try:
        con.execute("UPDATE beta_feedback SET status=? WHERE id=?",(status,int(feedback_id))); con.commit(); return True
    finally: con.close()

def _feedback_pdf(cid, scope='all'):
    if not _is_admin(cid): return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
    _feedback_schema(); con=_db()
    try:
        where=''; args=()
        if scope=='open': where="WHERE f.status!='selesai'"
        elif scope=='done': where="WHERE f.status='selesai'"
        rows=con.execute(f"SELECT f.*,u.first_name,u.last_name,u.username FROM beta_feedback f LEFT JOIN bot_users u ON u.chat_id=f.chat_id {where} ORDER BY f.id DESC",args).fetchall()
    finally: con.close()
    label={'all':'Semua Komen & Cadangan','open':'Belum Selesai','done':'Selesai'}.get(scope,'Semua Komen & Cadangan')
    path=f'/tmp/CikguLaju_Laporan_Feedback_{scope}.pdf'
    styles=getSampleStyleSheet()
    title=ParagraphStyle('fbtitle',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=15,leading=18,alignment=TA_CENTER,spaceAfter=8)
    body=ParagraphStyle('fbbody',parent=styles['BodyText'],fontName='Helvetica',fontSize=8.5,leading=11,spaceAfter=3)
    small=ParagraphStyle('fbsmall',parent=body,fontSize=7.5,leading=9)
    doc=SimpleDocTemplate(path,pagesize=A4,rightMargin=14*mm,leftMargin=14*mm,topMargin=14*mm,bottomMargin=14*mm)
    story=[Paragraph('LAPORAN KOMEN &amp; CADANGAN PUBLIC BETA<br/>CIKGULAJU AI',title),Paragraph(f'<b>Skop:</b> {html.escape(label)} &nbsp;&nbsp; <b>Jumlah:</b> {len(rows)} &nbsp;&nbsp; <b>Dijana:</b> {datetime.now().strftime("%d/%m/%Y %H:%M")}',body),Spacer(1,4*mm)]
    if not rows: story.append(Paragraph('Tiada rekod untuk skop ini.',body))
    else:
        for r0 in rows:
            r=dict(r0); name=_admin_user_name(r); st={'baru':'BARU','dibaca':'DIBACA','selesai':'SELESAI'}.get(str(r.get('status')),str(r.get('status')).upper())
            data=[[Paragraph(f'<b>#{r["id"]} • {html.escape(name)}</b>',body),Paragraph(f'<b>{st}</b>',body)],
                  [Paragraph(f'{html.escape(str(r["created_at"])[:19])} • {html.escape(str(r["category"]))} • ID {html.escape(str(r["chat_id"]))}',small),Paragraph('',small)],
                  [Paragraph(html.escape(str(r['feedback_text'])),body),Paragraph('',body)]]
            t=Table(data,colWidths=[155*mm,25*mm],repeatRows=0)
            t.setStyle(TableStyle([('BOX',(0,0),(-1,-1),0.5,colors.black),('INNERGRID',(0,0),(-1,-1),0.25,colors.grey),('VALIGN',(0,0),(-1,-1),'TOP'),('SPAN',(0,2),(1,2)),('BACKGROUND',(0,0),(-1,0),colors.whitesmoke),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
            story += [t,Spacer(1,3*mm)]
    doc.build(story)
    send_document(cid,path,f'📄 Laporan Komen & Cadangan — {label}')
    return send(cid,'✅ PDF laporan sudah dijana dan dihantar.',[[{'text':'💬 Kembali ke Komen','callback_data':'admin_feedback|0'},{'text':'🛠️ Admin Panel','callback_data':'admin_panel'}]])

