def callback(cid, d):
    if d == 'admin_panel':
        return _admin_panel(cid)
    if d.startswith('admin_list|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        parts=d.split('|')
        kind=parts[1] if len(parts)>1 else 'all'
        try: page=int(parts[2]) if len(parts)>2 else 0
        except Exception: page=0
        return _admin_list(cid,kind,page)
    if d.startswith('admin_user|'):
        return _admin_user_card(cid,d.split('|',1)[1])
    if d.startswith('admin_pending|'):
        try: rid=int(d.split('|',1)[1])
        except Exception: return _admin_panel(cid)
        return _admin_pending_card(cid,rid)
    if d.startswith('admin_approve|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        try: rid=int(d.split('|',1)[1])
        except Exception: return _admin_panel(cid)
        req=_payment_request(rid)
        if not req:
            return send(cid,'⚠️ Rekod bayaran tidak ditemui.')
        if req['status']!='pending':
            return _admin_pending_card(cid,rid)
        target=str(req['chat_id'])
        until=_activate_access(target,30,cid,'Payment RM5.00 approved from Admin Panel',payment_reference=f'payment-request:{rid}',amount_rm=5.00)
        _mark_payment_request(rid,'approved',cid,'Approved and activated 30 days')
        send(cid,f'✅ <b>BAYARAN DISAHKAN</b>\\n\\nPengguna <code>{target}</code> telah diaktifkan 30 hari sehingga <b>{until.strftime("%d/%m/%Y")}</b>.',
             [[{'text':'⏳ Pending Seterusnya','callback_data':'admin_list|pending|0'}],
              [{'text':'🛠️ Admin Panel','callback_data':'admin_panel'}]])
        try:
            send(target,f'✅ <b>CIKGULAJU TELAH DIAKTIFKAN</b>\\n\\nBayaran RM5.00 telah disahkan. Akses cikgu aktif selama <b>30 hari</b> sehingga <b>{until.strftime("%d/%m/%Y")}</b>.',
                 [[{'text':'✨ Jana Bahan','callback_data':'quick'}],[{'text':'👤 Akaun Saya','callback_data':'account'}]])
        except Exception:
            pass
        return
    if d.startswith('admin_reject|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        try: rid=int(d.split('|',1)[1])
        except Exception: return _admin_panel(cid)
        req=_payment_request(rid)
        if not req: return send(cid,'⚠️ Rekod bayaran tidak ditemui.')
        _mark_payment_request(rid,'rejected',cid,'Rejected from Admin Panel')
        try:
            send(req['chat_id'],'❌ <b>Bayaran belum dapat disahkan.</b>\\n\\nSila semak bayaran RM5.00 dan hantar semula bukti/resit yang jelas.',
                 [[{'text':'💳 Papar QR Bayaran','callback_data':'subscribe_500'}]])
        except Exception:
            pass
        return _admin_list(cid,'pending',0)
    if d.startswith('admin_deactivate|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
        target=d.split('|',1)[1]
        _deactivate_access(target,cid,'Deactivated from Admin Panel')
        send(cid,f'🔒 Akses pengguna <code>{target}</code> telah dinyahaktifkan.',
             [[{'text':'👤 Lihat Pengguna','callback_data':f'admin_user|{target}'},
               {'text':'🛠️ Admin Panel','callback_data':'admin_panel'}]])
        try: send(target,'🔒 <b>Akses CikguLaju telah dinyahaktifkan.</b>')
        except Exception: pass
        return
    if d.startswith('admin_activate30|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Butang ini hanya boleh digunakan oleh admin CikguLaju.')
        target=d.split('|',1)[1].strip()
        if not re.fullmatch(r'-?\d+',target):
            return send(cid,'⚠️ Telegram ID pengguna tidak sah.')
        until=_activate_access(target,30,cid,'Payment RM5.00 verified by admin button',payment_reference=f'payment-request:{rid}',amount_rm=5.00)
        con=_db()
        try:
            pr=con.execute("SELECT id FROM payment_requests WHERE chat_id=? AND status='pending' ORDER BY id DESC LIMIT 1",(target,)).fetchone()
        finally:
            con.close()
        if pr: _mark_payment_request(pr['id'],'approved',cid,'Approved via quick activate button')
        send(cid,f'✅ <b>AKSES DIAKTIFKAN</b>\n\nPengguna: <code>{target}</code>\nTempoh: <b>30 hari</b>\nAktif sehingga: <b>{until.strftime("%d/%m/%Y")}</b>',
             [[{'text':'🔎 Semak Status','callback_data':f'admin_status|{target}'}]])
        try:
            send(target,f'✅ <b>CIKGULAJU TELAH DIAKTIFKAN</b>\n\nBayaran telah disahkan. Akses cikgu aktif selama <b>30 hari</b> sehingga <b>{until.strftime("%d/%m/%Y")}</b>.\n\nCikgu boleh terus menggunakan CikguLaju.',
                 [[{'text':'✨ Jana Bahan','callback_data':'quick'}],[{'text':'👤 Akaun Saya','callback_data':'account'}]])
        except Exception:
            pass
        return
    elif d.startswith('admin_status|'):
        if not _is_admin(cid):
            return send(cid,'⛔ Butang ini hanya boleh digunakan oleh admin CikguLaju.')
        target=d.split('|',1)[1].strip()
        a=_access_info(target)
        send(cid,f'👤 <b>STATUS PENGGUNA</b>\n\nTelegram ID: <code>{target}</code>\nStatus: <b>{"AKTIF" if a["active"] else a["status"].upper()}</b>\nAktif sehingga: <b>{str(a.get("access_until") or "-")[:19]}</b>',
             [[{'text':'✅ Aktifkan / Tambah 30 Hari','callback_data':f'admin_activate30|{target}'}]])
        return
    if d == 'home':
        state[cid] = {}
        menu(cid)
    elif d == 'quick':
        quick(cid)
    elif d == 'material':
        state.setdefault(cid,{})['waiting'] = 'material'
        send(cid,'📚 <b>GUNA BAHAN CIKGU</b>\n\nHantar 📄 PDF atau 📸 gambar nota.\n\nPembacaan AI akan disambungkan pada langkah seterusnya.')
    elif d == 'donate':
        send_donation_qr(cid)
    elif d == 'pro':
        # Legacy callback: pelan berbayar disembunyikan buat masa sekarang.
        send(cid,'🎁 <b>CikguLaju AI kini percuma.</b>\n\nJika cikgu ingin membantu kos operasi dan pembangunan, sumbangan ikhlas boleh dibuat melalui menu utama.',
             [[{'text':'💛 Sumbangan Ikhlas','callback_data':'donate'}],
              [{'text':'🏠 Menu Utama','callback_data':'home'}]])
    elif d == 'account':
        send(cid,'👤 <b>AKAUN SAYA</b>\n\nPelan: 🎁 Percuma\nStatus: Aktif')
    elif d == 'quickmat_rph':
        ss=state.setdefault(cid,{})
        ss['task']='rph'; ss['rph_mode']='quick_material'; ss['quick_material_flow']=True
        return _rph_session_question(cid)
    elif d == 'quickmat_bbm':
        ss=state.setdefault(cid,{})
        ss['task']='bbm'; ss['quick_material_flow']=True
        return after_curriculum_selected(cid)
    elif d == 'quickmat_worksheet':
        ss=state.setdefault(cid,{})
        ss['task']='worksheet'; ss['quick_material_flow']=True
        return worksheet_options_after_sp(cid)
    elif d == 'quickmat_both':
        ss=state.setdefault(cid,{})
        ss['task']='both'; ss['rph_mode']='quick_material'; ss['quick_material_flow']=True
        return _rph_session_question(cid)
    elif d == 'rph_mode':
        choose_rph_mode(cid)
    elif d == 'rph_fast':
        state[cid]={'task':'rph','rph_mode':'fast','_cid':cid}
        choose_grade(cid)
    elif d == 'rph_custom':
        state[cid]={'task':'rph','rph_mode':'custom'}
        choose_grade(cid)
    elif d.startswith('task_'):
        level(cid,d[5:])
    elif d == 'choose_grade':
        choose_grade(cid)
    elif d == 'level_primary':
        year(cid,'primary')
    elif d == 'level_secondary':
        year(cid,'secondary')
    elif d.startswith('year_'):
        subjects(cid,'Tahun '+d[5:])
    elif d.startswith('form_'):
        subjects(cid,'Tingkatan '+d[5:])
    elif d.startswith('sub_'):
        state.setdefault(cid,{})['subject'] = d[4:]
        show_topics(cid,0)
    elif d.startswith('tpage_'):
        show_topics(cid,int(d[6:]))
    elif d.startswith('topic_'):
        if d == 'topic_custom':
            send(cid,'📚 Sila pilih tajuk daripada senarai yang disediakan.',
                 [[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        else:
            choose_topic(cid,int(d[6:]))

    elif d.startswith('st3|'):
        _, sti, ti = d.split('|')
        s0 = state.setdefault(cid,{})
        tc = TASK_TO_CODE.get(s0.get('task',''))
        yc = compact_year(s0.get('year',''))
        si = subject_index(s0.get('subject',''))
        if not tc or not yc or si < 0:
            return menu(cid)
        s = rebuild_state(tc, yc, si, ti, sti)
        if not s:
            return menu(cid)
        if s['task'] in ('questions','kbat'):
            show_qtype_v3(cid, s, int(sti))
        elif s['task'] in ('worksheet','rph','both'):
            state[cid] = s
            show_curriculum_sk(cid, s)
        else:
            state[cid] = s
            show_curriculum_sk(cid, s)

    elif d.startswith('cskm_'):
        try:
            idx=int(d.split('_',1)[1]); ss=state.setdefault(cid,{})
            opts=ss.get('related_sk_options') or ss.get('curr_sk_options') or []
            if idx<0 or idx>=len(opts): return menu(cid)
            code=str(opts[idx].get('sk_code') or '')
            chosen=list(ss.get('selected_sk_codes') or [])
            if code in chosen: chosen.remove(code)
            else: chosen.append(code)
            ss['selected_sk_codes']=chosen
            _render_rph_sk_multiselect(cid)
        except Exception: menu(cid)

    elif d == 'cskback':
        _render_rph_sp_multiselect(cid)

    elif d == 'cskdone':
        ss=state.setdefault(cid,{})
        required=set(ss.get('required_parent_sk_codes') or [])
        chosen=set(ss.get('selected_sk_codes') or [])
        missing=required-chosen
        if missing:
            ss['selected_sk_codes']=list(required)
            return send(cid,'⚠️ SK ini diperlukan kerana masih ada SP terpilih di bawahnya: <b>'+', '.join(sorted(missing))+'</b>. Pilihan SK berkaitan telah dipulihkan.',[[{'text':'↩️ Semak SK','callback_data':'cskback_to_sk'}]])
        if not chosen: return _render_rph_sk_multiselect(cid)
        _rph_session_question(cid)

    elif d.startswith('cspm_'):
        try:
            idx=int(d.split('_',1)[1]); ss=state.setdefault(cid,{})
            opts=ss.get('multi_sp_options') or []
            if idx<0 or idx>=len(opts): return menu(cid)
            code=str(opts[idx].get('sp_code') or '')
            chosen=list(ss.get('selected_sp_codes') or [])
            if code in chosen: chosen.remove(code)
            else: chosen.append(code)
            ss['selected_sp_codes']=chosen
            _render_rph_sp_multiselect(cid)
        except Exception: menu(cid)

    elif d == 'cspdone':
        ss=state.setdefault(cid,{})
        chosen=list(ss.get('selected_sp_codes') or [])
        opts=ss.get('multi_sp_options') or []
        selected=[o for o in opts if str(o.get('sp_code') or '') in chosen]
        if not selected: return _render_rph_sp_multiselect(cid)
        dur=int(ss.get('rph_duration_minutes') or 60)
        recommended=1 if dur<40 else (2 if dur<75 else (3 if dur<105 else 4))
        if len(selected)>recommended and not ss.get('sp_overload_confirmed'):
            ss['pending_sp_selection']=selected
            return send(cid,f'⚠️ Cikgu memilih <b>{len(selected)} SP</b> untuk <b>{dur} minit</b>. Cadangan biasa untuk tempoh ini ialah sekitar <b>{recommended} SP</b> yang berkaitan.\n\nCikgu masih boleh teruskan jika memang sesuai dengan kelas.',[[{'text':'✅ Teruskan Pilihan Ini','callback_data':'cspforce'},{'text':'✏️ Ubah Pilihan SP','callback_data':'cspedit'}]])
        _commit_multi_sp(ss,selected)
        required=set(ss.get('selected_sk_codes') or [])
        ss['required_parent_sk_codes']=list(required)
        ss['related_sk_options']=[o for o in (ss.get('curr_sk_options') or []) if str(o.get('sk_code') or '') in required]
        _render_rph_sk_multiselect(cid)

    elif d == 'cspedit':
        ss=state.setdefault(cid,{}); ss.pop('sp_overload_confirmed',None); ss.pop('pending_sp_selection',None)
        _render_rph_sp_multiselect(cid)

    elif d == 'cspforce':
        ss=state.setdefault(cid,{})
        selected=ss.pop('pending_sp_selection',None) or [o for o in (ss.get('multi_sp_options') or []) if str(o.get('sp_code') or '') in set(ss.get('selected_sp_codes') or [])]
        ss['sp_overload_confirmed']=True
        _commit_multi_sp(ss,selected)
        required=set(ss.get('selected_sk_codes') or [])
        ss['required_parent_sk_codes']=list(required)
        ss['related_sk_options']=[o for o in (ss.get('curr_sk_options') or []) if str(o.get('sk_code') or '') in required]
        _render_rph_sk_multiselect(cid)

    elif d == 'cskback_to_sk':
        _render_rph_sk_multiselect(cid)

    elif d.startswith('csk_'):
        try: show_curriculum_sp(cid, int(d.split('_',1)[1]))
        except Exception: menu(cid)

    elif d.startswith('csp_'):
        try:
            idx=int(d.split('_',1)[1]); ss=state.setdefault(cid,{})
            opts=ss.get('curr_sp_options') or []
            if idx<0 or idx>=len(opts): return menu(cid)
            sp=opts[idx]
            ss['sp_code'],ss['sp_text']=sp['sp_code'],sp['sp_text']
            ss['sk_code'],ss['sk_text']=sp['sk_code'],sp['sk_text']
            if ss.get('task') == 'quick_material':
                return _temporary_auto_pack_v2386(cid)
            after_curriculum_selected(cid)
        except Exception: menu(cid)

    # v21: selepas pilih jumlah soalan, TERUS preview 4 aras; TIADA menu kesukaran.
    elif d.startswith('wq_'):
        ss=state.setdefault(cid,{})
        try: ss['worksheet_questions']=int(d.split('_',1)[1])
        except Exception: ss['worksheet_questions']=8
        ss['worksheet_pack_4levels']=True
        ss['difficulty']='all4'
        ss['variation_seed']=secrets.token_hex(4)
        preview_v3(cid,ss,'generate_selected_material')

    elif d.startswith('wdiff_'):
        ss=state.setdefault(cid,{})
        ss['worksheet_pack_4levels']=True
        ss['difficulty']='all4'
        ss['variation_seed']=secrets.token_hex(4)
        preview_v3(cid,ss,'generate_selected_material')

    elif d == 'generate_selected_material':
        ss=state.setdefault(cid,{})
        if ss.get('assessment_mode')=='summative':
            if ss.get('task')=='both':
                generate_summative_both(cid,ss)
            elif ss.get('task')=='worksheet':
                generate_summative_paper(cid,ss,'generate_selected_material')
            elif ss.get('task')=='rph':
                ss['last_result']=_summative_rph_text(ss)
                ss['last_result_context']=dict(ss)
                send(cid,'✅ <b>RPH pentaksiran sumatif siap!</b>',[
                    [{'text':'📘 Dapatkan RPH','callback_data':'file_pdf'}],
                    [{'text':'🔄 Jana Semula','callback_data':'generate_selected_material'}],
                    [{'text':'🏠 Menu Utama','callback_data':'home'}]
                ])
            else:
                generate_summative_paper(cid,ss,'generate_selected_material')
        elif ss.get('task')=='both':
            generate_both_materials(cid,ss)
        elif ss.get('task')=='worksheet':
            generate_worksheet_pack(cid,ss,'generate_selected_material')
        else:
            generate_v3(cid,ss,'generate_selected_material')

    elif d.startswith('rphdatepage|'):
        try: _rph_date_picker(cid,int(d.split('|',1)[1]))
        except Exception: _rph_date_picker(cid,0)

    elif d.startswith('rphdate|'):
        try:
            raw=d.split('|',1)[1]
            dt=datetime.strptime(raw,'%Y%m%d')
            ss=state.setdefault(cid,{})
            date_text=dt.strftime('%d/%m/%Y')
            parsed_date, day=_parse_rph_date(date_text)
            ss['rph_date']=parsed_date or date_text; ss['rph_day']=(dt.strftime('%A') if _is_english_subject(ss) else (day or dt.strftime('%A')))
            _rph_time_picker(cid,'start',2)  # starts around 06:00, practical school hours
        except Exception:
            _rph_date_picker(cid,0)

    elif d.startswith('rphtimepage|'):
        try:
            _,mode,pg=d.split('|'); _rph_time_picker(cid,mode,int(pg))
        except Exception:
            _rph_time_picker(cid,'start',2)

    elif d.startswith('rphtime|'):
        try:
            _,mode,val=d.split('|'); mins=int(val); ss=state.setdefault(cid,{})
            if mode=='start':
                ss['rph_start_minutes']=mins
                _rph_time_picker(cid,'end',max(0,mins//180))
            else:
                start=int(ss.get('rph_start_minutes') if ss.get('rph_start_minutes') is not None else -1)
                if start < 0 or mins <= start:
                    return send(cid,'⚠️ Masa tamat mesti selepas masa mula.',[[{'text':'⏰ Pilih Semula Masa Tamat','callback_data':f'rphtimepage|end|{max(0,start//180)}'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
                duration=mins-start
                if duration < 20 or duration > 180:
                    return send(cid,f'⚠️ Tempoh <b>{duration} minit</b> kurang sesuai. Pilih masa tamat yang menghasilkan tempoh antara 20 hingga 180 minit.',[[{'text':'⏰ Pilih Semula','callback_data':f'rphtimepage|end|{max(0,start//180)}'}]])
                ss['rph_end_minutes']=mins; ss['rph_duration_minutes']=duration
                sh,sm=divmod(start,60); eh,em=divmod(mins,60)
                ss['rph_time']=f'{sh:02d}:{sm:02d} - {eh:02d}:{em:02d}'
                ss['rph_periods']=1 if duration < 45 else (2 if duration < 75 else max(2,round(duration/30)))
                if duration > 100 and not ss.get('rph_long_duration_confirmed'):
                    return send(cid,f'⚠️ <b>Semak tempoh PdP</b>\n\nMasa yang dipilih ialah <b>{html.escape(ss["rph_time"])}</b> — <b>{duration} minit</b>.\n\nTempoh ini agak panjang. Pastikan masa mula dan tamat betul sebelum diteruskan.',[[{'text':'✏️ Ubah Masa','callback_data':'rph_long_change'}],[{'text':'✅ Ya, Teruskan','callback_data':'rph_long_ok'}]])
                _continue_after_rph_time(cid,ss)
        except Exception:
            return send(cid,'⚠️ Pilihan masa tidak dapat diproses. Sila pilih semula.',[[{'text':'⏰ Pilih Masa','callback_data':'rphtimepage|start|2'}]])

    elif d.startswith('rsk_'):
        ss=state.setdefault(cid,{})
        if str(ss.get('rph_mode') or '').startswith('fast_textbook'):
            return _continue_after_rph_time(cid,ss)
        try: show_rph_sp(cid, int(d.split('_',1)[1]))
        except Exception: menu(cid)

    elif d.startswith('rsp_'):
        try:
            idx=int(d.split('_',1)[1]); ss=state.setdefault(cid,{})
            if str(ss.get('rph_mode') or '').startswith('fast_textbook'):
                return _continue_after_rph_time(cid,ss)
            opts=ss.get('rph_sp_options') or []
            if idx<0 or idx>=len(opts): return menu(cid)
            sp=opts[idx]; ss['sp_code'],ss['sp_text']=sp['sp_code'],sp['sp_text']; ss['sk_code'],ss['sk_text']=sp['sk_code'],sp['sk_text']
            start_rph_session(cid)
        except Exception: menu(cid)

    elif d in ('rphsession_fill','rphsession_blank'):
        ss=state.setdefault(cid,{})
        if not ss.get('sp_code') and ss.get('assessment_mode')!='summative' and not ss.get('textbook_no_explicit_skill_ls'):
            return send(cid,'⚠️ Sila pilih SK dan SP dahulu.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        ss['rph_gen_cb']='generate_selected_material'
        if d=='rphsession_blank':
            ss.update({'rph_date':'','rph_day':'','rph_time':'','rph_class':'','rph_students':''}); preview_v3(cid,ss,'generate_selected_material')
        else:
            ss['waiting']='rph_date'; send(cid,'📅 <b>Masukkan tarikh RPH</b>\n\nContoh: <code>10/09/2026</code>\nHari akan diisi secara automatik.')

    elif d == 'rph_generate_local':
        ss=state.setdefault(cid,{})
        if not ss.get('sp_code'): return send(cid,'⚠️ Data SK/SP tidak lengkap. Sila pilih semula RPH.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        generate_v3(cid,ss,'rph_generate_local')

    elif d.startswith('rphi|'):
        parts = d.split('|')
        if len(parts) == 8:
            _, mode, tc, yc, si, ti, sti = parts
            s = rebuild_state(tc, yc, si, ti, sti)
            if s:
                state[cid] = s
                gen_cb = f"gn3|{tc}|{yc}|{si}|{ti}|{sti}|-|-"
                s['rph_gen_cb'] = gen_cb
                if mode == 'blank':
                    s.update({'rph_date':'','rph_day':'','rph_time':'','rph_class':'','rph_students':''})
                    preview_v3(cid, s, gen_cb)
                else:
                    s['waiting'] = 'rph_date'
                    send(cid,'📅 <b>Masukkan tarikh RPH</b>\n\nContoh: <code>10/09/2026</code>\nHari akan diisi secara automatik.')

    elif d.startswith('wp3|'):
        # Legacy callback compatibility: no difficulty selection anymore.
        parts = d.split('|')
        if len(parts) == 7:
            _, pages_n, tc, yc, si, ti, sti = parts
            s = rebuild_state(tc, yc, si, ti, sti)
            if s:
                s['worksheet_questions'] = int(pages_n)
                s['worksheet_pack_4levels'] = True
                s['difficulty'] = 'all4'
                s['variation_seed'] = secrets.token_hex(4)
                state[cid] = s
                preview_v3(cid, s, 'generate_selected_material')

    elif d.startswith('lv3|'):
        # Butang aras versi lama: abaikan aras dan teruskan sebagai 4 aras.
        parts=d.split('|')
        if len(parts) >= 3:
            try:
                pages_n=int(parts[2])
            except Exception:
                pages_n=8
            ss=state.setdefault(cid,{})
            ss['worksheet_questions']=pages_n
            ss['worksheet_pack_4levels']=True
            ss['difficulty']='all4'
            ss['variation_seed']=secrets.token_hex(4)
            preview_v3(cid,ss,'generate_selected_material')

    elif d.startswith('gw3|'):
        ss=state.setdefault(cid,{})
        ss['worksheet_pack_4levels']=True
        ss['difficulty']='all4'
        ss['variation_seed']=secrets.token_hex(4)
        generate_worksheet_pack(cid,ss,'generate_selected_material')

    elif d.startswith('qt3|'):
        parts = d.split('|')
        if len(parts) == 7:
            _, qc, tc, yc, si, ti, sti = parts
            send(cid,'🔢 <b>Berapa soalan cikgu perlukan?</b>',
                 [[{'text':str(n),'callback_data':f'am3|{n}|{qc}|{tc}|{yc}|{si}|{ti}|{sti}'} for n in (5,10,20,30)]])

    elif d.startswith('am3|'):
        parts = d.split('|')
        if len(parts) == 8:
            _, amount_n, qc, tc, yc, si, ti, sti = parts
            s = rebuild_state(tc, yc, si, ti, sti, qc, amount_n)
            if s:
                gen_cb = f'gn3|{tc}|{yc}|{si}|{ti}|{sti}|{qc}|{amount_n}'
                preview_v3(cid, s, gen_cb)

    elif d.startswith('gn3|'):
        parts = d.split('|')
        if len(parts) == 8:
            _, tc, yc, si, ti, sti, qc, amount_n = parts
            s = rebuild_state(tc, yc, si, ti, sti, qc, amount_n)
            if s:
                if s.get('task') == 'rph':
                    prev = state.get(cid,{})
                    for k in ('rph_date','rph_day','rph_time','rph_class','rph_students'):
                        if k in prev: s[k] = prev.get(k,'')
                    state[cid] = s
                generate_v3(cid, s, d)

    elif d == 'file_summative':
        ss=state.setdefault(cid,{})
        result=ss.get('summative_result'); ctx=ss.get('summative_context')
        if not result or not ctx:
            return send(cid,'⚠️ Kertas sumatif belum tersedia.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        pth=create_pdf_file(ctx,result,cid)
        send_document(cid,pth,'📝 Kertas Pentaksiran Sumatif')

    elif d == 'file_summative_both':
        ss=state.setdefault(cid,{})
        rr=ss.get('summative_both_results') or {}
        cc=ss.get('summative_both_contexts') or {}
        if not rr or not cc:
            return send(cid,'⚠️ Pakej sumatif belum tersedia.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        rph_path=create_pdf_file(cc['rph'],rr['rph'],str(cid)+'_sum_rph')
        paper_path=create_pdf_file(cc['paper'],rr['paper'],str(cid)+'_sum_paper')
        out=os.path.join(tempfile.gettempdir(),f'{cid}_CikguLaju_RPH_dan_Sumatif.pdf')
        _merge_pdf_paths([rph_path,paper_path],out)
        send_document(cid,out,'📚 RPH + Kertas Pentaksiran Sumatif')

    elif d == 'file_both_materials':
        st=state.setdefault(cid,{})
        results=st.get('both_results') or {}; contexts=st.get('both_contexts') or {}
        if not results or not contexts:
            saved=_material_load(cid,'both_materials') or {}
            results=saved.get('results') or {}; contexts=saved.get('contexts') or {}
        if not results or not contexts:
            return send(cid,'⚠️ Bahan tidak ditemui dalam simpanan. Sila jana bahan sekali lagi.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        send(cid,'📦 <b>Sedang menyediakan pakej...</b>')
        paths=[]
        try:
            rph_path=create_pdf_file(contexts['rph'],results['rph'],cid); paths.append(rph_path); send_document(cid,rph_path,'📘 RPH')
            ws_path=create_four_level_worksheet_pdf(contexts['worksheet'],results['worksheet_pack'],cid); paths.append(ws_path); send_document(cid,ws_path,'📝 Worksheet 4 Aras')
            send(cid,'✅ RPH dan worksheet 4 aras siap.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        except Exception as e:
            print('Both file error:',repr(e),flush=True); send(cid,'⚠️ Fail belum berjaya disediakan. Cuba semula.')
        finally:
            for pth in paths:
                try:
                    if os.path.exists(pth): os.remove(pth)
                except Exception:
                    pass

    elif d == 'file_worksheet_pack':
        st=state.setdefault(cid,{})
        results=st.get('worksheet_pack_results') or {}; ctx=st.get('worksheet_pack_context')
        if len(results)!=4 or not ctx:
            saved=_material_load(cid,'worksheet_pack') or {}
            results=saved.get('results') or {}; ctx=saved.get('context')
        if len(results)!=4 or not ctx:
            return send(cid,'⚠️ Worksheet tidak ditemui dalam simpanan. Sila jana sekali lagi.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        send(cid,'📦 <b>Sedang menyediakan PDF 4 aras...</b>')
        pupil_pth=scheme_pth=None
        try:
            pupil_pth,scheme_pth=create_four_level_worksheet_files(ctx,results,cid)
            send_document(cid,pupil_pth,'📝 Worksheet 4 Aras — Murid (tanpa jawapan)')
            send_document(cid,scheme_pth,'🔐 Skema Jawapan Guru — dengan contoh pengiraan')
            send(cid,'✅ Worksheet murid dan skema guru telah diasingkan kepada dua fail.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        except Exception as e:
            print('Worksheet pack file error:',repr(e),flush=True); _generation_progress_fail(cid,_pmid,'Worksheet belum berjaya disediakan.'); send(cid,'⚠️ Fail belum berjaya disediakan. Cuba semula.')
        finally:
            for pth in (pupil_pth,scheme_pth):
                try:
                    if pth and os.path.exists(pth): os.remove(pth)
                except Exception:
                    pass

    elif d in ('file_pdf','file_word','file_both'):
        # Word/Kedua-dua disembunyikan daripada UI. Callback lama tetap selamat: hantar PDF sahaja.
        if d in ('file_word','file_both'):
            d = 'file_pdf'
        st = state.setdefault(cid,{})
        result = st.get('last_result')
        ctx = st.get('last_result_context')
        if not result or not ctx:
            return send(cid,'⚠️ Fail sementara sudah tiada. Sila jana bahan sekali lagi.',
                        [[{'text':'🏠 Menu Utama','callback_data':'home'}]])

        _pmid=_generation_progress_start(cid,'Sedang menjana PDF')
        try:
            paths = []
            _generation_progress_update(cid,_pmid,25,'Mengambil kandungan daripada database...','Sedang menjana PDF')
            _generation_progress_update(cid,_pmid,45,'Menyusun kandungan dan aktiviti...','Sedang menjana PDF')
            if d in ('file_pdf','file_both'):
                _generation_progress_update(cid,_pmid,70,'Membina susun atur PDF...','Sedang menjana PDF')
                p = create_pdf_file(ctx, result, cid)
                paths.append(p)
                _generation_progress_update(cid,_pmid,90,'Menyemak fail akhir...','Sedang menjana PDF')
                send_document(cid, p, '📄 PDF - sedia untuk cetak')
                _generation_progress_update(cid,_pmid,100,'Siap. Fail telah dihantar.','Sedang menjana PDF')
            if d in ('file_word','file_both'):
                p = create_word_file(ctx, result, cid)
                paths.append(p)
                send_document(cid, p, '📝 Word - boleh diedit')
            for p in paths:
                if os.path.exists(p):
                    os.remove(p)
            send(cid,'✅ Fail siap.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        except Exception as e:
            print('File error:', repr(e), flush=True)
            _generation_progress_fail(cid,_pmid,'Fail belum berjaya disediakan. Cuba semula.')
            send(cid,'⚠️ Fail belum berjaya disediakan. Cuba semula.',
                 [[{'text':'🏠 Menu Utama','callback_data':'home'}]])


