# v23.80 — discover production visual shards without merging DB files.
def _visual_db_paths_v2380():
    paths=[VISUAL_DB_PATH]
    # Preferred v23.82+ path: manifest-driven universal discovery.
    for m in _discover_db_shards('visuals', VISUAL_DB_PATH):
        if m['path'] not in paths: paths.append(m['path'])
    # Backward compatibility for previously generated Visuals_XX files that lack a manifest.
    base=os.path.dirname(__file__)
    for name in sorted(os.listdir(base)):
        if re.match(r'^CikguLaju_Visuals_\d+\.db$', name, re.I):
            p=os.path.join(base,name)
            if p not in paths: paths.append(p)
    return paths

def _production_visual_asset_v2380(concept_key, surface='bbm', variant_no=1, color_required=False):
    palette=_shared_visual_palette_v2379(surface,color_required)
    for path in _visual_db_paths_v2380()[1:]:
        try:
            con=sqlite3.connect(path,timeout=10); con.row_factory=sqlite3.Row
            row=con.execute("SELECT asset_key,mime_type,image_blob,palette FROM visual_assets WHERE concept_key=? AND palette=? AND approved=1 ORDER BY ABS(variant_no-?) LIMIT 1",(str(concept_key),palette,int(variant_no))).fetchone()
            con.close()
            if row: return dict(row)
        except Exception:
            try: con.close()
            except Exception: pass
    return None


