def _sp_action_quality_pack(s):
    subject=str(s.get('subject') or '').strip()
    sp_text=' '.join(str(x or '') for x in (s.get('sp_text'),s.get('learning_standard'),s.get('sp'))).lower()
    if not subject or not sp_text: return None
    try:
        conn=_db()
        rows=conn.execute("""SELECT action_keyword,activity_pattern,objective_pattern,success_pattern,
                            assessment_pattern,bbm_pattern,priority FROM rph_sp_action_patterns
                            WHERE subject=? AND verified=1 ORDER BY priority DESC""",(subject,)).fetchall()
        conn.close()
    except Exception as e:
        print('sp action quality:',repr(e),flush=True); return None
    hits=[r for r in rows if str(r[0] or '').lower() in sp_text]
    return hits[:3] if hits else None

def _clean_page_range_text(v):
    raw=str(v or '').strip()
    nums=re.findall(r'\d+',raw)
    vals=[]
    for n in nums:
        try:
            x=int(n)
            if x not in vals: vals.append(x)
        except: pass
    if not vals: return raw
    if len(vals)>=2:
        vals=sorted(vals)
        if vals[-1]-vals[0] == len(vals)-1: return f"{vals[0]}–{vals[-1]}"
        return ", ".join(map(str,vals))
    return str(vals[0])

def _local_rph_text(s):
    if str(s.get('subject') or '').strip()=='Bahasa Inggeris':
        return _local_rph_text_english(s)
    sk=(str(s.get('sk_code') or '').strip()+' '+str(s.get('sk_text') or '').strip()).strip()
    sp=(str(s.get('sp_code') or '').strip()+' '+str(s.get('sp_text') or '').strip()).strip()
    topic=str(s.get('topic') or '').strip(); sub=str(s.get('subtopic') or '').strip()
    subject=str(s.get('subject') or '').strip(); year=str(s.get('year') or '').strip()
    focus = sub if sub and sub!='Semua Subtopik' else topic
    ped = curriculum_pedagogy_for(s)
    if ped:
        objective=ped['objective']; criteria=ped['success_criteria']; prior=ped['prior_knowledge']
        bbm=ped['bbm']; emk=ped['emk_values']; pak=ped['pak21']; assessment=ped['assessment']
        # Standard v7: BBM mesti menamakan bahan sebenar, bukan istilah umum.
        if any(x in (bbm or '').lower() for x in ('bahan konkrit','bahan manipulatif','visual yang sesuai','bahan sedia ada','atau blok')):
            bbm='Buku teks, '+_specific_material_pack(subject, topic, focus, s.get('variation_seed',''))
        remedial=ped['remediation']; enrichment=ped['enrichment']
        # Variation Engine: satu SP mempunyai beberapa reka bentuk PdP. Pilihan berubah pada setiap janaan.
        import random as _r
        _rng=_r.Random(str(s.get('variation_seed') or secrets.token_hex(4)))
        base_ind=ped['induction']; base_act=ped['activities']
        focus_label=(sub if sub and sub!='Semua Subtopik' else topic) or sp
        # Untuk SP yang mempunyai bank aktiviti terperinci, gunakan variasi pedagogi khusus
        # berasaskan kehendak DSKP/MOBIM, bukan variasi generik.
        if year=='Tahun 1' and subject=='Matematik' and str(s.get('sp_code'))=='2.3.1':
            variants=[
              ('''5 minit\n1. Guru meletakkan 9 blok asas 10 di atas meja dan meminta seorang murid mengambil keluar 4.\n2. Murid mengira baki dan menyebut ayat “9 tolak 4 sama dengan 5”.\n3. Guru menulis 9 − 4 = 5 dan mengaitkan tindakan mengambil keluar dengan operasi tolak.''',
               '''Aktiviti 1 – Ambil Keluar (15 minit)\nSetiap pasangan menerima 10–18 blok asas 10 dan kad fakta tolak. Murid membina bilangan pertama, mengambil keluar bilangan kedua, mengira baki dan menyebut ayat matematik. Pasangan menyemak dengan mengira semula.\n\nAktiviti 2 – Pangkah Gambar (15 minit)\nGuru mengedarkan kad bergambar, contohnya 10 belon dengan 4 belon perlu dipangkah. Murid memangkah, mengira baki dan menulis 10 − 4 = 6. Guru menukar daripada objek konkrit kepada gambar supaya murid melihat hubungan antara tindakan dan simbol.\n\nAktiviti 3 – Lompat Ke Belakang (15 minit)\nMurid menggunakan garis nombor 0–18. Bagi 13 − 5, murid bermula pada 13 dan membuat lima lompatan ke belakang. Murid membandingkan jawapan dengan kaedah objek/gambar.\n\nAktiviti 4 – Fakta Pantas (10 minit)\nGuru menunjukkan 5 kad fakta asas secara rawak. Murid menjawab pada papan mini. Selepas setiap item, seorang murid menerangkan strategi yang digunakan. Guru merekod murid yang masih perlu bahan konkrit.'''),
              ('''5 minit\n1. Guru menunjukkan gambar 8 epal dan menutup 3 daripadanya dengan kad.\n2. Murid meneka bilangan yang masih kelihatan, kemudian menerangkan bagaimana mereka tahu.\n3. Guru memperkenalkan fokus “baki selepas sesuatu diambil”.''',
               '''Aktiviti 1 – Cerita Tolak (15 minit)\nGuru menceritakan situasi ringkas: “Ada 7 ikan. 2 berenang pergi.” Murid melakonkan situasi menggunakan kad ikan, menyatakan bilangan asal, bilangan yang berkurang dan baki, kemudian menulis 7 − 2 = 5.\n\nAktiviti 2 – Padankan Tiga Kad (15 minit)\nDalam kumpulan, murid memadankan tiga jenis kad: kad situasi/gambar, kad ayat matematik dan kad jawapan. Contohnya gambar 9 bola dengan 5 dikeluarkan dipadankan dengan 9 − 5 dan 4. Setiap kumpulan perlu menerangkan satu padanan.\n\nAktiviti 3 – Cari Pasangan Saya (15 minit)\nSeparuh murid menerima kad soalan fakta tolak dan separuh lagi menerima kad jawapan. Murid bergerak mencari pasangan yang betul. Selepas berpasangan, mereka membuktikan jawapan menggunakan objek atau garis nombor.\n\nAktiviti 4 – Semakan Individu (10 minit)\nMurid menyelesaikan 5 item: dua bergambar, dua ayat matematik dan satu situasi harian. Sasaran penguasaan ialah sekurang-kurangnya 4 daripada 5 betul.'''),
              ('''5 minit\n1. Guru memaparkan dua kumpulan: 9 sudu dan 5 garfu.\n2. Murid memadankan satu sudu dengan satu garfu dan memerhati objek yang tidak mempunyai pasangan.\n3. Guru mengaitkan baki yang tidak berpasangan dengan maksud “beza”.''',
               '''Aktiviti 1 – Berapa Beza? (15 minit)\nPasangan murid menerima dua kumpulan objek yang berbeza bilangannya. Mereka membuat padanan satu-dengan-satu, mengira objek yang tidak berpasangan dan menulis ayat tolak, contohnya 9 − 5 = 4.\n\nAktiviti 2 – Keluarga Fakta (15 minit)\nGuru memberikan tiga nombor seperti 5, 8 dan 13. Dengan bimbingan, murid membina hubungan tambah dan tolak: 5 + 8 = 13, 8 + 5 = 13, 13 − 5 = 8 dan 13 − 8 = 5. Fokus diberikan pada tolak sebagai songsangan tambah.\n\nAktiviti 3 – Stesen Strategi (20 minit)\nStesen A menggunakan objek; Stesen B menggunakan gambar dipangkah; Stesen C menggunakan garis nombor; Stesen D menggunakan pengiraan mental bagi fakta yang telah dikuasai. Murid menyelesaikan fakta tolak yang sama dengan strategi berlainan dan menanda strategi yang paling membantu mereka.\n\nAktiviti 4 – Terangkan Cara Saya (10 minit)\nBeberapa murid memilih satu fakta tolak dan menerangkan strategi kepada kelas. Guru menilai ketepatan jawapan serta penggunaan bahasa matematik.'''),
              ('''5 minit\n1. Guru menunjukkan 10 kad bintang. Seorang murid diminta menyembunyikan beberapa kad sehingga tinggal 6.\n2. Kelas menentukan berapa kad yang disembunyikan dan menerangkan cara mendapatkan jawapan.\n3. Guru mengaitkan aktiviti dengan mencari bahagian yang hilang melalui operasi tolak.''',
               '''Aktiviti 1 – Kotak Misteri (15 minit)\nGuru menyediakan situasi seperti “10 objek, tinggal 6”. Murid menggunakan objek untuk menentukan berapa yang telah diambil. Mereka merekod 10 − 4 = 6 dan menyemak dengan menambah semula 6 + 4 = 10.\n\nAktiviti 2 – Bingo Tolak (15 minit)\nMurid mempunyai grid jawapan. Guru membacakan fakta tolak dalam lingkungan 18; murid mengira menggunakan strategi pilihan dan menanda jawapan. Untuk mendapat Bingo, murid perlu menerangkan sekurang-kurangnya satu pengiraan.\n\nAktiviti 3 – Bina Soalan Rakan (15 minit)\nSetiap pasangan memilih satu fakta tolak dan membina cerita ringkas menggunakan objek kelas, makanan atau permainan. Pasangan lain menulis ayat matematik dan menyelesaikannya.\n\nAktiviti 4 – Exit Ticket (10 minit)\nMurid menjawab 5 fakta asas tolak secara individu tanpa bantuan rakan. Murid yang belum mencapai 4/5 dibimbing semula menggunakan objek dalam lingkungan 10; murid yang menguasai membina satu cerita tolak sendiri.''')
            ]
        else:
            # Semua SP lain juga mesti menggunakan bahan bernama secara terus.
            named_materials=_specific_material_pack(subject, topic, focus_label, s.get('variation_seed',''))
            bbm='Buku teks, '+named_materials
            spec_ind,spec_act=_make_specific_local_activity(subject, topic, focus_label, s.get('sp_code',''), named_materials)
            topic_variants=_specific_activity_variant_bank(subject, topic, focus_label, s.get('sp_code',''), s.get('sp_text',''), named_materials, s.get('variation_seed',''), s.get('year',''))
            variants=topic_variants or [
              (spec_ind, spec_act),
          (f'''5 minit
1. Guru memaparkan satu situasi harian ringkas berkaitan {focus_label} tanpa terus memberi jawapan.
2. Murid berbincang dengan pasangan, menunjukkan idea menggunakan bahan yang tersedia dan berkongsi satu jawapan.
3. Guru menghubungkan respons murid dengan fokus SP {s.get("sp_code","")}.''',
           f'''Aktiviti 1 – Teroka (15 minit)
Murid bekerja dalam kumpulan kecil menggunakan {ped['bbm'].split(',')[1].strip() if ',' in ped['bbm'] else 'bahan manipulatif'} untuk membina atau menunjukkan contoh {focus_label}. Guru menyoal “bagaimana kamu tahu?” dan membetulkan miskonsepsi semasa aktiviti.

Aktiviti 2 – Bimbingan Buku Teks/Visual (20 minit)
Guru memilih contoh yang sepadan dengan SP {s.get("sp_code","")} daripada buku teks atau visual setara. Murid menerangkan langkah, melengkapkan contoh secara berpasangan dan membandingkan jawapan.

Aktiviti 3 – Cabaran Pasangan (15 minit)
Setiap pasangan menerima kad tugasan berlainan. Murid A menyelesaikan/menunjukkan tugasan dan Murid B menyemak berdasarkan kriteria kejayaan; kemudian bertukar peranan.

Aktiviti 4 – Individu (15 minit)
Murid menjawab latihan pendek berperingkat daripada mudah kepada aplikasi. Guru mengumpulkan bukti pentaksiran dan terus memberi pemulihan kepada murid yang belum menguasai.'''),
          (f'''5 minit
1. Guru menjalankan aktiviti “Betul atau Salah” menggunakan satu contoh {focus_label}.
2. Murid mengangkat kad respons dan memberi sebab. Guru menggunakan jawapan murid untuk mengenal pasti pengetahuan sedia ada.''',
           f'''Aktiviti 1 – Demonstrasi Murid (15 minit)
Beberapa murid menunjukkan cara menyelesaikan tugasan {focus_label} menggunakan bahan/visual. Rakan lain menyatakan apa yang dilakukan pada setiap langkah.

Aktiviti 2 – Stesen Pembelajaran (30 minit)
Stesen A: manipulatif/objek; Stesen B: gambar atau kad; Stesen C: simbol/latihan bertulis. Kumpulan bergerak mengikut stesen dan merekod jawapan. Tugasan setiap stesen kekal dalam skop SP {s.get("sp_code","")}.

Aktiviti 3 – Semak Rakan (10 minit)
Murid bertukar hasil kerja, menyemak satu jawapan dan menerangkan pembetulan jika perlu.

Aktiviti 4 – Exit Ticket (10 minit)
Murid menyelesaikan tugasan individu ringkas. Guru mengasingkan murid kepada kumpulan pengayaan atau pemulihan berdasarkan respons.'''),
          (f'''5 minit
1. Guru menggunakan objek/gambar misteri berkaitan {focus_label} dan meminta murid membuat jangkaan.
2. Murid menerangkan jangkaan dengan ayat sendiri sebelum guru memperkenalkan fokus pembelajaran.''',
           f'''Aktiviti 1 – Saya Buat, Kita Buat (20 minit)
Guru memodelkan satu contoh sambil menyebut proses berfikir. Seterusnya kelas menyelesaikan dua contoh bersama dengan murid menentukan langkah seterusnya.

Aktiviti 2 – Permainan Kad (20 minit)
Dalam kumpulan 3–4 orang, murid mengambil kad tugasan {focus_label}, menyelesaikannya menggunakan bahan atau lakaran dan memperoleh mata apabila dapat menerangkan jawapan.

Aktiviti 3 – Aplikasi Konteks Harian (15 minit)
Murid menyelesaikan situasi mudah yang dekat dengan kehidupan mereka dan menerangkan bagaimana SP {s.get("sp_code","")} digunakan.

Aktiviti 4 – Latihan Kendiri (10 minit)
Murid menjawab beberapa item individu. Guru menyemak berdasarkan kriteria kejayaan.''')]
        induction,activities=_rng.choice(variants)
        # Variasikan juga penutup supaya keseluruhan RPH tidak kelihatan sebagai salinan template.
        closings=[
          '5 minit\n1. Murid menyebut satu perkara yang dipelajari dan menunjukkan satu contoh.\n2. Guru membuat semakan cepat berdasarkan kriteria kejayaan.',
          '5 minit\n1. Guru menjalankan kuiz lisan 3 soalan.\n2. Murid menunjukkan isyarat ibu jari faham/perlu bantuan; guru merekod murid untuk tindakan susulan.',
          '5 minit\n1. Secara Think-Pair-Share, murid menerangkan cara menyelesaikan satu tugasan.\n2. Guru merumuskan pembelajaran dan mengaitkannya dengan pelajaran seterusnya.'
        ]
        s['_local_closing']=_rng.choice(closings)
    else:
        objective=f'Pada akhir pembelajaran, murid dapat menunjukkan penguasaan berkaitan {focus} berdasarkan Standard Pembelajaran yang dipilih.'
        criteria='Murid menunjukkan bukti pencapaian melalui tugasan yang selaras dengan Standard Pembelajaran.'
        prior=f'Guru mengaktifkan pengetahuan sedia ada murid berkaitan {focus}.'
        bbm='Buku teks, '+_specific_material_pack(subject, topic, focus, s.get('variation_seed',''))
        emk='Nilai murni, komunikasi dan pembelajaran kendiri mengikut kesesuaian.'
        pak='Soal jawab, perbincangan dan penerangan idea mengikut tahap murid.'
        assessment='Pemerhatian, soal jawab dan semakan hasil kerja berdasarkan Standard Pembelajaran.'
        induction=f'5 minit\n1. Guru mencetuskan pengetahuan sedia ada murid berkaitan {focus} menggunakan situasi atau bahan yang dekat dengan murid.\n2. Guru menghubungkan respons murid dengan fokus pembelajaran.'
        _named=_specific_material_pack(subject, topic, focus, s.get('variation_seed',''))
        _topic_variants=_specific_activity_variant_bank(subject, topic, focus, s.get('sp_code',''), s.get('sp_text',''), _named, s.get('variation_seed',''), s.get('year',''))
        if _topic_variants:
            import random as _r
            induction,activities=_r.Random(str(s.get('variation_seed') or secrets.token_hex(4))).choice(_topic_variants)
        else:
            induction,activities=_make_specific_local_activity(subject, topic, focus, s.get('sp_code',''), _named)
        remedial='Gunakan bahan konkrit atau visual dan pecahkan tugasan kepada langkah lebih kecil.'
        enrichment='Berikan tugasan aplikasi atau penyelesaian masalah yang masih dalam skop SP yang sama.'
    lines=[
        f'MATA PELAJARAN: {subject}', f'TAHUN/TINGKATAN: {year}', f'TAJUK: {topic}', f'TEMPOH: {int(s.get("rph_duration_minutes") or 60)} minit',
        f'STANDARD KANDUNGAN: {sk}', f'STANDARD PEMBELAJARAN: {_rph_sp_display(s)}',
        f'OBJEKTIF PEMBELAJARAN: {objective}', f'KRITERIA KEJAYAAN: {criteria}',
        f'PENGETAHUAN SEDIA ADA: {prior}', f'BAHAN BANTU MENGAJAR: {bbm}',
        f'EMK / NILAI: {emk}', f'KBAT / PAK21: {pak}', f'PENTAKSIRAN: {assessment}',
        f'SET INDUKSI: {induction}', f'AKTIVITI UTAMA: {activities}',
        f'PENUTUP: {s.get("_local_closing") or "5 minit\n1. Murid menyatakan semula perkara utama yang dipelajari.\n2. Guru menjalankan semakan cepat berdasarkan kriteria kejayaan."}',
        f'PEMULIHAN / PENGAYAAN: Pemulihan: {remedial}\nPengayaan: {enrichment}',
        'REFLEKSI: ________ / ________ murid mencapai objektif. ________ murid belum mencapai objektif dan akan diberi tindakan susulan/pemulihan.'
    ]
    text='\n'.join(lines)
    if int(s.get('rph_duration_minutes') or 60)==30:
        # A 30-minute RPH is intentionally compact; it is not a 60-minute plan squeezed into half the time.
        sec=_parse_rph_sections(text)
        sec['SET INDUKSI']='3 minit\n1. Guru menggunakan bahan utama untuk mencetuskan pengetahuan sedia ada.\n2. Murid memberi respons ringkas dan guru menyatakan fokus pembelajaran.'
        act=sec.get('AKTIVITI UTAMA','')
        blocks=[b.strip() for b in act.split('\n\n') if b.strip()]
        chosen=blocks[:2] if blocks else [act]
        compact=[]
        for i,b in enumerate(chosen,1):
            b=re.sub(r'\(\d+ minit\)', '(10 minit)' if i==1 else '(12 minit)', b)
            compact.append(b)
        sec['AKTIVITI UTAMA']='\n\n'.join(compact)
        sec['PENUTUP']='5 minit\n1. Murid menjawab satu exit ticket atau menerangkan satu dapatan.\n2. Guru menyemak kriteria kejayaan dan menetapkan tindakan susulan.'
        order=['MATA PELAJARAN','TAHUN/TINGKATAN','TAJUK','TEMPOH','STANDARD KANDUNGAN','STANDARD PEMBELAJARAN','OBJEKTIF PEMBELAJARAN','KRITERIA KEJAYAAN','PENGETAHUAN SEDIA ADA','BAHAN BANTU MENGAJAR','EMK / NILAI','KBAT / PAK21','PENTAKSIRAN','SET INDUKSI','AKTIVITI UTAMA','PENUTUP','PEMULIHAN / PENGAYAAN','REFLEKSI']
        text='\n'.join(f'{k}: {sec[k]}' for k in order if sec.get(k))
    return text


def _rph_selected_sk_rows(s):
    opts=s.get('curr_sk_options') or []
    chosen=set(s.get('selected_sk_codes') or [])
    return [o for o in opts if str(o.get('sk_code')) in chosen]

def _render_rph_sk_multiselect(cid):
    s=state.setdefault(cid,{})
    opts=s.get('curr_sk_options') or []
    chosen=set(s.get('selected_sk_codes') or [])
    kb=[]
    for i,o in enumerate(opts[:40]):
        code=str(o.get('sk_code') or '')
        mark='✅' if code in chosen else '☐'
        kb.append([{'text':f"{mark} {code} — {o.get('sk_text','')}"[:60],'callback_data':f'cskm_{i}'}])
    if chosen:
        kb.append([{'text':f'➡️ Seterusnya: Pilih SP ({len(chosen)} SK)','callback_data':'cskdone'}])
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    _edit_or_send_inline(cid,'📘 <b>Pilih Standard Kandungan (SK)</b>\n\nPilih satu atau beberapa SK dalam menu ini. Tekan semula pilihan untuk membuang tanda. Selepas selesai, tekan <b>Seterusnya: Pilih SP</b>.',kb)

def _render_rph_sp_multiselect(cid):
    s=state.setdefault(cid,{})
    opts=s.get('multi_sp_options') or []
    chosen=set(s.get('selected_sp_codes') or [])
    kb=[]
    for i,o in enumerate(opts[:60]):
        code=str(o.get('sp_code') or '')
        mark='✅' if code in chosen else '☐'
        kb.append([{'text':f"{mark} {code} — {o.get('sp_text','')}"[:60],'callback_data':f'cspm_{i}'}])
    if chosen:
        kb.append([{'text':f'✅ Selesai Pilihan ({len(chosen)} SP)','callback_data':'cspdone'}])
    kb.append([{'text':'⬅️ Kembali Pilih SK','callback_data':'cskback_to_sk'}])
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    dur=int(s.get('rph_duration_minutes') or 0)
    _edit_or_send_inline(cid,('📗 <b>Pilih Standard Pembelajaran (SP)</b>\n\n'+((f'⏱️ Tempoh kelas: <b>{dur} minit</b>\n') if dur else '')+'Hanya SP di bawah SK yang cikgu pilih dipaparkan. Pilih satu atau beberapa SP dalam menu ini, kemudian tekan <b>Selesai Pilihan</b>.'),kb)

def _is_english_subject(s):
    return str((s or {}).get('subject') or '').strip().lower() in ('bahasa inggeris','english')

def _bi_skill_name(code):
    c=str(code or '').strip()
    return {'1':'Listening','2':'Speaking','3':'Reading','4':'Writing','5':'Language Arts'}.get(c.split('.')[0],'English')

def _render_bi_main_skill(cid):
    ss=state.setdefault(cid,{})
    opts=ss.get('bi_ls_options') or []
    kb=[]
    for i,o in enumerate(opts[:60]):
        code=str(o.get('sp_code') or '')
        kb.append([{'text':f"{_bi_skill_name(code)} • {code} — {o.get('sp_text','')}"[:60],'callback_data':f'bimain_{i}'}])
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,'🇬🇧 <b>Main Skill</b>\n\nPilih Learning Standard utama untuk lesson ini.',kb)

def _render_bi_complementary(cid):
    ss=state.setdefault(cid,{})
    opts=ss.get('bi_ls_options') or []
    main=str(ss.get('bi_main_sp_code') or '')
    kb=[]
    for i,o in enumerate(opts[:60]):
        code=str(o.get('sp_code') or '')
        if code==main: continue
        kb.append([{'text':f"{_bi_skill_name(code)} • {code} — {o.get('sp_text','')}"[:60],'callback_data':f'bicomp_{i}'}])
    kb.append([{'text':'⬅️ Ubah Main Skill','callback_data':'bimain_back'}])
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,'🇬🇧 <b>Complementary Skill</b>\n\nPilih Learning Standard yang menyokong Main Skill.',kb)

def _commit_bi_standards(ss, comp):
    main=ss.get('bi_main_row') or {}
    ss['bi_comp_row']=comp
    ss['bi_comp_sp_code']=str(comp.get('sp_code') or '')
    ss['bi_comp_sp_text']=str(comp.get('sp_text') or '')
    # Preserve both standards for PDF/content engine while retaining legacy primary fields.
    ss['sp_code']=str(main.get('sp_code') or '')
    ss['sp_text']=str(main.get('sp_text') or '')
    ss['sk_code']=str(main.get('sk_code') or '')
    ss['sk_text']=str(main.get('sk_text') or '')
    ss['grouped_sp_codes']=[str(main.get('sp_code') or ''),str(comp.get('sp_code') or '')]
    ss['grouped_sp_texts']=[str(main.get('sp_text') or ''),str(comp.get('sp_text') or '')]
    sks=[]; sktexts=[]
    for o in (main,comp):
        c=str(o.get('sk_code') or '')
        if c and c not in sks: sks.append(c); sktexts.append(str(o.get('sk_text') or ''))
    ss['grouped_sk_codes']=sks; ss['grouped_sk_texts']=sktexts
    ss['selected_sk_codes']=sks

def show_curriculum_sk(cid, s):
    opts=curriculum_sk_options(s); state[cid]=s
    if not opts:
        return send(cid,'📘 <b>Topik tersedia, tetapi SK/SP disahkan untuk pilihan ini masih belum dimasukkan ke database.</b>\n\nIni bukan ralat aplikasi. Sila cuba topik/subjek lain untuk ujian sementara.',[[{'text':'⬅️ Pilih Topik Lain','callback_data':'sub_'+str(s.get('subject',''))}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    state[cid]['curr_sk_options']=opts
    if s.get('task') in ('rph','both') and _is_english_subject(s):
        allsp=[]; seen=set()
        for sk in opts:
            for o in curriculum_sp_options(s,sk['sk_code']):
                code=str(o.get('sp_code') or '')
                if code and code not in seen:
                    seen.add(code); allsp.append(o)
        s['bi_ls_options']=allsp
        s.pop('bi_main_row',None); s.pop('bi_comp_row',None)
        return _render_bi_main_skill(cid)
    if s.get('task') in ('rph','both'):
        # v22.48: DSKP hierarchy must be SK -> SP.
        # Do not flatten all SP from every SK before the teacher chooses its parent SK.
        return show_rph_sk(cid, s)
    kb=[[{'text':f"{o['sk_code']} — {o['sk_text']}"[:60],'callback_data':f'csk_{i}'}] for i,o in enumerate(opts[:40])]
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,'📘 <b>Pilih Standard Kandungan (SK)</b>',kb)

def show_curriculum_sp(cid, sk_index):
    s=state.setdefault(cid,{}); opts=s.get('curr_sk_options') or []
    if sk_index<0 or sk_index>=len(opts): return menu(cid)
    sk=opts[sk_index]; s['sk_code'],s['sk_text']=sk['sk_code'],sk['sk_text']
    sps=curriculum_sp_options(s, sk['sk_code'])
    if not sps: return send(cid,'⚠️ Standard Pembelajaran untuk SK ini belum tersedia.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    s['curr_sp_options']=sps
    kb=[[{'text':f"{o['sp_code']} — {o['sp_text']}"[:60],'callback_data':f'csp_{i}'}] for i,o in enumerate(sps[:50])]
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,f"📗 <b>{sk['sk_code']} {html.escape(sk['sk_text'])}</b>\n\nPilih Standard Pembelajaran (SP):",kb)

def _commit_multi_sp(s, selected):
    if not selected: return
    first=selected[0]
    s['sp_code'],s['sp_text']=first.get('sp_code',''),first.get('sp_text','')
    s['sk_code'],s['sk_text']=first.get('sk_code',''),first.get('sk_text','')
    s['grouped_sp_codes']=[str(o.get('sp_code') or '') for o in selected]
    s['grouped_sp_texts']=[str(o.get('sp_text') or '') for o in selected]
    sk_seen=[]; sk_text=[]
    for o in selected:
        c=str(o.get('sk_code') or '')
        if c and c not in sk_seen:
            sk_seen.append(c); sk_text.append(str(o.get('sk_text') or ''))
    s['selected_sk_codes']=sk_seen
    s['grouped_sk_codes']=sk_seen; s['grouped_sk_texts']=sk_text
    s['sk_code']='; '.join(sk_seen)
    s['sk_text']='; '.join(f'{c} {t}'.strip() for c,t in zip(sk_seen,sk_text))

def after_curriculum_selected(cid):
    s=state.setdefault(cid,{})
    if s.get('task') in ('rph','both'):
        _apply_smart_sp_grouping(s)
        _rph_session_question(cid)
    elif s.get('task')=='worksheet':
        worksheet_options_after_sp(cid)
    elif s.get('task')=='bbm':
        pth=None
        try:
            s['bbm_variation_seed']=secrets.token_hex(6)
            pth=create_bbm_flashcards_pdf(s,cid)
            send_document(cid,pth,'🎨 BBM CikguLaju - sedia untuk print & potong')
            kb=_integrated_material_buttons('bbm') + [[{'text':'🎨 Jana BBM Lain','callback_data':'continue_bbm'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]]
            return send(cid,'✅ <b>BBM siap.</b>\n\nBBM dijana daripada tajuk + SK/SP yang cikgu pilih. Pilihan kurikulum ini dikekalkan untuk sambung jana RPH atau worksheet.',kb)
        except Exception as e:
            print('Standalone BBM error:',repr(e),flush=True)
            return send(cid,'⚠️ BBM untuk pilihan SK/SP ini belum tersedia dalam bank tempatan.',[[{'text':'⬅️ Pilih Topik Lain','callback_data':'mode_formative'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        finally:
            try:
                if pth and os.path.exists(pth): os.remove(pth)
            except Exception: pass

def worksheet_options_after_sp(cid):
    """Worksheet: no manual question-count menu; collect lesson session then preview."""
    s=state.setdefault(cid,{})
    s.pop('waiting_worksheet_config',None)
    s['worksheet_pack_4levels']=True
    s['difficulty']='all4'
    s['worksheet_questions_auto']=True
    s['variation_seed']=secrets.token_hex(4)
    return start_rph_session(cid)

def show_rph_sk(cid, s):
    # HARD GUARD: textbook-page RPH must never enter a manual SK/SP selector.
    state[cid]=s
    if _textbook_auto_standards_ready(s):
        return _rph_session_question(cid)
    if str(s.get('rph_mode') or '').startswith('fast_textbook'):
        return send(cid,'⚠️ Muka surat ini belum mempunyai mapping SK/SP verified. Sila pilih muka surat lain.',[[{'text':'📖 Masukkan Muka Surat Lain','callback_data':'fast_use_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    opts=curriculum_sk_options(s)
    if not opts:
        return send(cid,'📘 <b>SK/SP untuk topik ini belum tersedia.</b>\n\nSila pilih topik lain yang tersedia sementara kandungan diperluaskan.',[[{'text':'⬅️ Pilih Topik Lain','callback_data':'sub_'+str(s.get('subject',''))}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    s['curr_sk_options']=opts
    s['rph_sk_options']=opts
    s['selected_sk_codes']=[]
    s['selected_sp_codes']=[]
    s.pop('multi_sp_options',None)
    _render_rph_sk_multiselect(cid)


def show_rph_sp(cid, sk_index):
    s=state.setdefault(cid,{}); opts=s.get('rph_sk_options') or []
    if sk_index<0 or sk_index>=len(opts): return menu(cid)
    sk=opts[sk_index]; s['sk_code'],s['sk_text']=sk['sk_code'],sk['sk_text']
    sps=curriculum_sp_options(s, sk['sk_code'])
    if not sps: return send(cid,'⚠️ Standard Pembelajaran untuk SK ini belum tersedia.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    s['rph_sp_options']=sps
    kb=[[{'text':f"{o['sp_code']} — {o['sp_text']}"[:60],'callback_data':f'rsp_{i}'}] for i,o in enumerate(sps[:50])]
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,f"📗 <b>{sk['sk_code']} {html.escape(sk['sk_text'])}</b>\n\nPilih Standard Pembelajaran (SP):",kb)


def _apply_smart_sp_grouping(s):
    """Group related SPs according to the actual lesson duration."""
    primary_code=str(s.get('sp_code') or '').strip()
    primary_text=str(s.get('sp_text') or '').strip()
    s['grouped_sp_codes']=[primary_code] if primary_code else []
    s['grouped_sp_texts']=[primary_text] if primary_text else []
    minutes=int(s.get('rph_duration_minutes') or 30)
    # Short lessons stay focused. Medium lessons may carry 2 SPs; longer lessons up to 3.
    max_sp = 1 if minutes < 40 else (2 if minutes < 55 else 3)
    if max_sp <= 1 or not primary_code:
        return s
    opts=s.get('rph_sp_options') or []
    pos=next((i for i,o in enumerate(opts) if str(o.get('sp_code'))==primary_code), -1)
    if pos >= 0:
        for o in opts[pos+1:]:
            if len(s['grouped_sp_codes']) >= max_sp: break
            if str(o.get('sk_code') or '') != str(s.get('sk_code') or ''): continue
            code=str(o.get('sp_code') or '').strip(); text=str(o.get('sp_text') or '').strip()
            if code and code not in s['grouped_sp_codes']:
                s['grouped_sp_codes'].append(code); s['grouped_sp_texts'].append(text)
    return s

def _rph_sk_display(s):
    codes=s.get('grouped_sk_codes') or s.get('selected_sk_codes') or []
    texts=s.get('grouped_sk_texts') or []
    if codes:
        return '\n'.join(f'{c} {texts[i] if i < len(texts) else ""}'.strip() for i,c in enumerate(codes))
    return f"{s.get('sk_code','')} {s.get('sk_text','')}".strip()

def _rph_sp_display(s):
    if _is_english_subject(s) and s.get('bi_main_row'):
        m=s.get('bi_main_row') or {}; c=s.get('bi_comp_row') or {}
        return (f"Main Skill — {_bi_skill_name(m.get('sp_code'))}: {m.get('sp_code','')} {m.get('sp_text','')} | "
                f"Complementary Skill — {_bi_skill_name(c.get('sp_code'))}: {c.get('sp_code','')} {c.get('sp_text','')}")
    codes=s.get('grouped_sp_codes') or [s.get('sp_code','')]
    texts=s.get('grouped_sp_texts') or [s.get('sp_text','')]
    return '\n'.join(f'{c} {t}'.strip() for c,t in zip(codes,texts) if c or t)

def _class_level_number(s):
    """Extract selected Year/Form number for class-example and soft validation."""
    y=str(s.get('year') or '').strip()
    m=re.search(r'\b([1-6])\b', y)
    return int(m.group(1)) if m else None

def _dynamic_class_example(s):
    n=_class_level_number(s)
    names=['Bestari','Mutiara','Cemerlang','Amanah','Intan','Gemilang']
    # Stable per session so prompt does not unexpectedly change while teacher is entering data.
    seed=str(s.get('year') or '')+'|'+str(s.get('subject') or '')+'|'+str(s.get('rph_date') or '')
    name=names[sum(ord(c) for c in seed) % len(names)]
    return f'{n} {name}' if n else name

def _class_number_mismatch(s, value):
    expected=_class_level_number(s)
    if not expected: return False
    m=re.match(r'^\s*([1-6])(?:\s|$)', str(value or ''))
    return bool(m and int(m.group(1)) != expected)

def _prompt_rph_class(cid, s, prefix=''):
    ex=_dynamic_class_example(s)
    class_rows=_profile_class_records(cid)
    classes=[r['name'] for r in class_rows]
    msg=(prefix+'\n\n' if prefix else '')+'🏫 <b>Pilih atau masukkan kelas</b>'
    kb=[]
    for i,row in enumerate(class_rows[:12]):
        label='🏫 '+row['name']
        if row.get('students'):
            label+=f" • {row['students']} murid"
        kb.append([{'text':label,'callback_data':f'rphclass_profile_{i}'}])
    kb.append([{'text':'✍️ Tulis Nama Kelas Manual','callback_data':'rphclass_manual'}])
    if not classes:
        msg+=f'\nTiada kelas disimpan dalam profil. Cikgu boleh taip manual.\nContoh: <code>{html.escape(ex)}</code>'
    else:
        msg+='\nPilih kelas daripada profil, atau tulis nama kelas manual jika kelas yang diperlukan belum disimpan.'
    send(cid,msg,kb)

def _rph_session_question(cid):
    # Tarikh dan masa sudah dipilih melalui picker; hanya maklumat kelas/murid perlu dilengkapkan.
    s=state.setdefault(cid,{})
    dur=int(s.get('rph_duration_minutes') or 0)
    send(cid,f'🗓️ <b>Maklumat sesi PdP</b>\n\n📅 {html.escape(str(s.get("rph_date") or "-"))} ({html.escape(str(s.get("rph_day") or "-"))})\n⏰ {html.escape(str(s.get("rph_time") or "-"))}\n⏱️ Tempoh dikesan: <b>{dur} minit</b>\n\nLengkapkan kelas dan bilangan murid?',[[{'text':'✍️ Isi Kelas & Murid','callback_data':'rphsession_fill'},{'text':'⏭️ Biarkan Kosong','callback_data':'rphsession_blank'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])

def _rph_date_picker(cid, offset=0):
    from datetime import date, timedelta
    s=state.setdefault(cid,{})
    base=date.today()+timedelta(days=offset)
    kb=[]
    for r in range(0,7,2):
        row=[]
        for j in range(2):
            i=r+j
            if i>=7: break
            d=base+timedelta(days=i)
            
            if _is_english_subject(s): label=d.strftime('%a %d/%m')
            else:
                _ms=['Isn','Sel','Rab','Kha','Jum','Sab','Ahd']; label=f'{_ms[d.weekday()]} {d.strftime("%d/%m")}'
            row.append({'text':label,'callback_data':'rphdate|'+d.strftime('%Y%m%d')})
        kb.append(row)
    kb.append([{'text':'⬅️ 7 hari','callback_data':f'rphdatepage|{offset-7}'},{'text':'7 hari ➡️','callback_data':f'rphdatepage|{offset+7}'}])
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    send(cid,'📅 <b>Pilih tarikh RPH</b>\n\nTekan tarikh — tidak perlu menaip.',kb)

def _rph_time_picker(cid, mode='start', page=0):
    # 5-minute increments; 3-hour pages keep the Telegram keyboard compact.
    start_min=max(0,min(23*60+55,int(page)*180))
    end_min=min(24*60,start_min+180)
    kb=[]; row=[]
    for m in range(start_min,end_min,10):
        hh=m//60; mm=m%60
        label=f'{hh:02d}:{mm:02d}'
        row.append({'text':label,'callback_data':f'rphtime|{mode}|{m}'})
        if len(row)==3: kb.append(row); row=[]
    if row: kb.append(row)
    nav=[]
    if start_min>0: nav.append({'text':'⬅️ Awal','callback_data':f'rphtimepage|{mode}|{max(0,page-1)}'})
    if end_min<24*60: nav.append({'text':'Lewat ➡️','callback_data':f'rphtimepage|{mode}|{page+1}'})
    if nav: kb.append(nav)
    kb.append([{'text':'🏠 Menu Utama','callback_data':'home'}])
    title='masa mula' if mode=='start' else 'masa tamat'
    send(cid,f'⏰ <b>Pilih {title} PdP</b>\n\nPilih terus daripada butang masa.',kb)

def start_rph_session(cid):
    # v23.62: personal timetable first when available; manual date/time remains fallback.
    s=state.setdefault(cid,{})
    for k in ('rph_date','rph_day','rph_start_minutes','rph_end_minutes','rph_time','rph_duration_minutes','rph_periods'):
        s.pop(k,None)
    if globals().get('_timetable_entries') and _timetable_entries(cid):
        return _timetable_pick_for_rph(cid)
    _rph_date_picker(cid,0)

