def send(cid, text, kb=None, parse_html=True, reply_keyboard=None):
    p = {'chat_id': cid, 'text': text}
    if parse_html:
        p['parse_mode'] = 'HTML'
    if kb:
        p['reply_markup'] = {'inline_keyboard': kb}
    elif reply_keyboard:
        p['reply_markup'] = {
            'keyboard': reply_keyboard,
            'resize_keyboard': True,
            'is_persistent': True
        }
    r = requests.post(f'{API}/sendMessage', json=p, timeout=20)
    return r

def _generation_progress_start(cid, title='Sedang menjana fail'):
    """Create one Telegram progress message and return its message_id.

    Percentages represent completed local generation stages; no timer/fake animation.
    """
    text=(f'⚙️ <b>{html.escape(str(title))}</b>\n\n'
          '█░░░░░░░░░ <b>10%</b>\n'
          'Menyemak pilihan dan data...')
    try:
        r=send(cid,text)
        data=r.json() if r is not None else {}
        return (data.get('result') or {}).get('message_id')
    except Exception as e:
        print('progress start warning:',repr(e),flush=True)
        return None


def _generation_progress_update(cid, message_id, percent, detail, title='Sedang menjana fail'):
    """Update a single progress message. Failure never blocks file generation."""
    if not message_id:
        return
    try:
        pct=max(0,min(100,int(percent)))
        filled=max(1,min(10,(pct+9)//10)) if pct else 0
        bar='█'*filled+'░'*(10-filled)
        text=(f'⚙️ <b>{html.escape(str(title))}</b>\n\n'
              f'{bar} <b>{pct}%</b>\n{html.escape(str(detail))}')
        requests.post(f'{API}/editMessageText',json={
            'chat_id':cid,'message_id':message_id,'text':text,'parse_mode':'HTML'
        },timeout=20)
    except Exception as e:
        print('progress update warning:',repr(e),flush=True)


def _generation_progress_fail(cid, message_id, detail='Fail belum berjaya disediakan.'):
    if not message_id:
        return
    try:
        requests.post(f'{API}/editMessageText',json={
            'chat_id':cid,'message_id':message_id,
            'text':'❌ <b>Janaan tidak berjaya</b>\n\n'+html.escape(str(detail)),
            'parse_mode':'HTML'
        },timeout=20)
    except Exception:
        pass


def _edit_or_send_inline(cid, text, kb=None, parse_html=True):
    """Edit the current inline-keyboard message during callbacks; otherwise send once.

    This keeps SK/SP multi-select inside one Telegram menu instead of stacking a new
    message every time the teacher toggles an option.
    """
    ss = state.setdefault(cid,{})
    mid = ss.get('_callback_message_id')
    if mid:
        payload={'chat_id':cid,'message_id':mid,'text':text}
        if parse_html:
            payload['parse_mode']='HTML'
        if kb is not None:
            payload['reply_markup']={'inline_keyboard':kb}
        try:
            r=requests.post(f'{API}/editMessageText',json=payload,timeout=20)
            if getattr(r,'ok',False):
                return r
            # "message is not modified" is harmless; keep the existing menu.
            try:
                desc=(r.json() or {}).get('description','')
                if 'message is not modified' in str(desc).lower():
                    return r
            except Exception:
                pass
        except Exception as e:
            print('editMessageText warning:',repr(e),flush=True)
    return send(cid,text,kb,parse_html=parse_html)


