def _new_donation_receipt(chat_id, message_id=None):
    """Rekod lokal + audit persistent Supabase. Resit fizikal kekal di Telegram; audit tidak hilang bila DB deploy."""
    _ensure_access_schema()
    import uuid
    token='donation:'+uuid.uuid4().hex
    con=_db()
    try:
        cur=con.execute("""INSERT INTO donation_receipts(chat_id,telegram_message_id,status,receipt_token)
                           VALUES(?,?,'received',?)""",(str(chat_id),message_id,token))
        con.commit(); rid=int(cur.lastrowid)
    finally: con.close()
    # Gunakan ledger Supabase sedia ada sebagai audit trail persistent; tidak perlu schema Supabase baharu.
    try:
        bal=_ensure_user_credit(chat_id)
        _sb_request('POST','credit_ledger',json={
            'telegram_user_id':int(chat_id),'amount':0,'transaction_type':'donation_receipt',
            'description':'Resit sumbangan diterima dan direkod oleh admin',
            'reference_id':token,'balance_after':int(bal)
        },prefer='return=minimal')
    except Exception as e:
        print('Persistent donation receipt audit warning:',repr(e),flush=True)
    return rid

