def _admin_user_name(row):
    name=' '.join(x for x in [str(row.get('first_name') or ''),str(row.get('last_name') or '')] if x).strip()
    if not name:
        name='@'+str(row.get('username') or '') if row.get('username') else 'Pengguna'
    return name

def _admin_list(cid, kind='all', page=0):
    if not _is_admin(cid):
        return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
    kind=str(kind or 'all'); page=max(0,int(page or 0)); per=8; off=page*per
    con=_db()
    try:
        if kind=='pending':
            rows=con.execute("""SELECT p.id request_id,p.chat_id,p.amount,p.submitted_at,
                                      u.username,u.first_name,u.last_name
                               FROM payment_requests p
                               LEFT JOIN bot_users u ON u.chat_id=p.chat_id
                               WHERE p.status='pending'
                               ORDER BY p.id DESC LIMIT ? OFFSET ?""",(per+1,off)).fetchall()
            title='⏳ <b>PENDING PENGESAHAN</b>'
        elif kind=='active':
            rows=con.execute("""SELECT u.chat_id,u.username,u.first_name,u.last_name,a.access_until
                               FROM user_access a LEFT JOIN bot_users u ON u.chat_id=a.chat_id
                               WHERE a.status='active' AND a.access_until>CURRENT_TIMESTAMP
                               ORDER BY a.access_until ASC LIMIT ? OFFSET ?""",(per+1,off)).fetchall()
            title='✅ <b>PENGGUNA AKTIF</b>'
        elif kind=='inactive':
            rows=con.execute("""SELECT u.chat_id,u.username,u.first_name,u.last_name,a.status,a.access_until
                               FROM bot_users u LEFT JOIN user_access a ON a.chat_id=u.chat_id
                               WHERE a.chat_id IS NULL OR a.status!='active' OR a.access_until<=CURRENT_TIMESTAMP
                               ORDER BY u.last_seen DESC LIMIT ? OFFSET ?""",(per+1,off)).fetchall()
            title='🔒 <b>TAMAT / TIDAK AKTIF</b>'
        elif kind=='payments':
            rows=con.execute("""SELECT p.id request_id,p.chat_id,p.amount,p.status,p.submitted_at,
                                      u.username,u.first_name,u.last_name
                               FROM payment_requests p LEFT JOIN bot_users u ON u.chat_id=p.chat_id
                               ORDER BY p.id DESC LIMIT ? OFFSET ?""",(per+1,off)).fetchall()
            title='💳 <b>SEJARAH BAYARAN</b>'
        else:
            all_users=_admin_persistent_users()
            all_users.sort(key=lambda x: str(x.get('last_seen') or x.get('created_at') or ''), reverse=True)
            rows=all_users[off:off+per+1]
            title='👥 <b>SEMUA PENGGUNA</b>'
    finally:
        con.close()

    more=len(rows)>per
    rows=rows[:per]
    kb=[]
    if not rows:
        text=title+'\n\nTiada rekod buat masa ini.'
    else:
        text=title+f'\n\nHalaman <b>{page+1}</b>\nTekan nama pengguna untuk lihat tindakan.'
        for r0 in rows:
            r=dict(r0); uid=str(r.get('chat_id') or '')
            name=_admin_user_name(r)[:22]
            if kind=='pending':
                label=f'⏳ {name} • RM{float(r.get("amount") or 5):.2f}'
                cb=f'admin_pending|{r.get("request_id")}'
            elif kind=='payments':
                icon={'approved':'✅','pending':'⏳','rejected':'❌'}.get(str(r.get('status')),'•')
                label=f'{icon} {name} • RM{float(r.get("amount") or 5):.2f}'
                cb=f'admin_user|{uid}'
            else:
                a=_access_info(uid) if not _is_beta_tester(uid) else {'active':True}
                icon='🧪' if _is_beta_tester(uid) else ('✅' if a['active'] else '🔒')
                # Nama boleh sama; suffix ID menjadikan setiap akaun jelas berbeza di Admin Panel.
                id_tail=uid[-6:] if len(uid)>6 else uid
                label=f'{icon} {name} • ID {id_tail}'
                cb=f'admin_user|{uid}'
            kb.append([{'text':label,'callback_data':cb}])
    nav=[]
    if page>0: nav.append({'text':'⬅️','callback_data':f'admin_list|{kind}|{page-1}'})
    nav.append({'text':'🛠️ PANEL','callback_data':'admin_panel'})
    if more: nav.append({'text':'➡️','callback_data':f'admin_list|{kind}|{page+1}'})
    kb.append(nav)
    send(cid,text,kb)

def _admin_user_card(cid, target):
    if not _is_admin(cid): return send(cid,'⛔ Panel ini hanya untuk admin CikguLaju.')
    con=_db()
    try:
        row=con.execute("SELECT * FROM bot_users WHERE chat_id=?",(str(target),)).fetchone()
    finally: con.close()
    if row:
        r=dict(row)
    else:
        r=next((x for x in _admin_persistent_users() if str(x.get('chat_id'))==str(target)), {})
    name=_admin_user_name(r) if r else 'Pengguna'; uname='@'+r.get('username','') if r.get('username') else '-'
    if _is_beta_tester(target):
        status='🧪 PUBLIC BETA TESTER'; access='♾️ TANPA HAD'; until='14 Oktober 2026'
    else:
        a=_access_info(target); status='AKTIF' if a['active'] else str(a['status']).upper(); access='Langganan'; until=str(a.get('access_until') or '-')[:19]
    text=(f'👤 <b>{html.escape(name)}</b>\n\nTelegram ID: <code>{target}</code>\nUsername: <code>{html.escape(uname)}</code>\n'
          f'Status: <b>{status}</b>\nAkses: <b>{access}</b>\nTamat: <b>{until}</b>')
    try:
        sub=_subscription_row(target) or {}
        subexp=str(sub.get('expires_at') or '')[:10]
        if subexp: text += f'\nLangganan selepas beta direkod hingga: <b>{html.escape(subexp)}</b>'
    except Exception: pass
    kb=[]
    if not _is_beta_tester(target):
        kb.append([{'text':'🎁 +1 PERCUBAAN','callback_data':f'admin_trial1|{target}'},{'text':'🎁 +3 PERCUBAAN','callback_data':f'admin_trial3|{target}'}])
        kb.append([{'text':'✅ AKTIF / TAMBAH 30 HARI','callback_data':f'admin_activate30|{target}'},{'text':'🔒 NYAHAKTIF','callback_data':f'admin_deactivate|{target}'}])
    kb.append([{'text':'👥 KEMBALI KE PENGGUNA','callback_data':'admin_list|all|0'}])
    kb.append([{'text':'🛠️ KEMBALI KE PANEL','callback_data':'admin_panel'}])
    return send(cid,text,kb)

