def _teacher_profile(cid):
    try:
        rows=_sb_request('GET',f'teacher_profiles?telegram_user_id=eq.{int(cid)}&select=*') or []
        return rows[0] if rows else None
    except Exception as e:
        print('teacher profile read:',repr(e),flush=True); return None

def _save_teacher_profile(cid, **fields):
    # Simpan hanya maklumat minimum yang diperlukan oleh fungsi produk.
    allowed={'display_name','state_name','class_names','class_profiles'}
    payload={'telegram_user_id':int(cid)}
    payload.update({k:v for k,v in fields.items() if k in allowed and v is not None})
    payload['updated_at']=datetime.now(timezone.utc).isoformat()
    rows=_sb_request('GET',f'teacher_profiles?telegram_user_id=eq.{int(cid)}&select=telegram_user_id') or []
    if rows:
        _sb_request('PATCH',f'teacher_profiles?telegram_user_id=eq.{int(cid)}',json=payload,prefer='return=minimal')
    else:
        _sb_request('POST','teacher_profiles',json=payload,prefer='return=minimal')
    return _teacher_profile(cid)

