def _save_beta_feedback(cid, text, category='Umum'):
    text=' '.join(str(text or '').strip().split())[:2000]
    if not text: return False
    try:
        con=sqlite3.connect(DB_PATH, timeout=15)
        con.execute("CREATE TABLE IF NOT EXISTS beta_feedback(id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'Umum', feedback_text TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'baru')")
        cur=con.execute('INSERT INTO beta_feedback(chat_id,category,feedback_text) VALUES(?,?,?)',(str(cid),str(category),text))
        feedback_id=int(cur.lastrowid)
        con.commit(); con.close()
    except Exception as e:
        print('beta feedback DB error:',repr(e),flush=True); return False
    if ADMIN_CHAT_ID:
        try:
            send(ADMIN_CHAT_ID, f'🔔 <b>KOMEN / CADANGAN BARU #{feedback_id}</b>\nPengguna: <code>{cid}</code>\nKategori: <b>{html.escape(str(category))}</b>\n\n{html.escape(text)}', [[{'text':'📖 BACA KOMEN','callback_data':f'admin_feedback_view|{feedback_id}'},{'text':'💬 SEMUA KOMEN','callback_data':'admin_feedback|0'}]])
        except Exception as e: print('beta feedback admin forward error:',repr(e),flush=True)
    return True

