def _ensure_subject_structure_profiles_v2384():
    """Subject-aware curriculum navigation for every available year/form.

    Labels describe the source structure; they do not invent curriculum content.
    Actual choices still come only from verified RPT/textbook/DSKP rows in DB.
    """
    profiles = {
        'Bahasa Melayu': ('theme_unit', 'Tema / Unit / Tajuk', 'Muka surat / Fokus', 'RPT + buku teks + DSKP', 'Utamakan tema dan unit/tajuk sebenar; SK/SP kekal daripada mapping verified.'),
        'Bahasa Inggeris': ('unit_lesson', 'Unit / Topic', 'Lesson / Page / Skill focus', 'SOW/RPT + textbook + DSKP', 'Ikut organisasi unit/topic/lesson sebenar; jangan paksa medan Tema jika sumber tidak menggunakannya.'),
        'Matematik': ('field_topic', 'Bidang / Tajuk', 'Topik / Kemahiran', 'RPT + DSKP + buku teks', 'Navigasi berasaskan bidang/tajuk dan kemahiran matematik sebenar.'),
        'Sains': ('theme_topic', 'Tema / Bidang', 'Tajuk / Fokus', 'RPT + DSKP + buku teks', 'Navigasi berasaskan tema/bidang dan tajuk sebenar.'),
        'Sejarah': ('theme_topic', 'Tajuk / Tema', 'Unit / Fokus', 'RPT + DSKP + buku teks', 'Ikut tajuk/unit kronologi yang disahkan dalam sumber.'),
        'Pendidikan Islam': ('field_topic', 'Bidang', 'Tajuk / Fokus', 'RPT + DSKP + buku teks', 'Ikut bidang sebenar seperti al-Quran, Hadis, Akidah, Ibadah, Sirah, Adab dan Jawi apabila disahkan.'),
        'Pendidikan Moral': ('field_topic', 'Bidang / Tema', 'Tajuk / Nilai', 'RPT + DSKP + buku teks', 'Ikut organisasi sebenar sumber kurikulum.'),
        'Reka Bentuk dan Teknologi': ('field_topic', 'Bidang / Tajuk', 'Topik / Projek', 'RPT + DSKP + buku teks', 'Ikut organisasi sebenar sumber kurikulum.'),
        'Geografi': ('theme_topic', 'Tema / Tajuk', 'Topik / Kemahiran', 'RPT + DSKP + buku teks', 'Ikut organisasi sebenar sumber kurikulum.'),
    }
    con=_db()
    try:
        # Also cover any subject already present in verified RPT without hard-coding a fake curriculum hierarchy.
        existing=[str(r[0]) for r in con.execute("SELECT DISTINCT subject FROM rpt_entries WHERE verified=1 ORDER BY subject").fetchall() if r[0]]
        for subject in existing:
            mode,primary,secondary,basis,notes=profiles.get(subject,('topic','Unit / Tajuk','Fokus','RPT + DSKP + buku teks','Gunakan organisasi yang datang daripada rekod verified; jangan cipta label kandungan baharu.'))
            con.execute("""INSERT INTO rpt_subject_profiles(subject,organization_mode,primary_label,secondary_label,sequence_basis,notes,updated_at)
                         VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP)
                         ON CONFLICT(subject) DO UPDATE SET organization_mode=excluded.organization_mode,primary_label=excluded.primary_label,
                         secondary_label=excluded.secondary_label,sequence_basis=excluded.sequence_basis,notes=excluded.notes,updated_at=CURRENT_TIMESTAMP""",
                        (subject,mode,primary,secondary,basis,notes))
        con.commit()
    finally:
        con.close()


def _apply_rpt_structure_context_v2384(s, row):
    """Preserve source hierarchy in one state shared by RPH/Worksheet/BBM."""
    profile=_rpt_subject_profile(str(s.get('subject') or ''))
    theme=str(row.get('theme') or '').strip()
    unit=str(row.get('unit_title') or '').strip()
    topic=str(row.get('topic') or '').strip()
    subtopic=str(row.get('subtopic') or '').strip()
    skill=str(row.get('skill_focus') or '').strip()
    s['curriculum_org_mode']=profile.get('organization_mode') or 'topic'
    s['curriculum_primary_label']=profile.get('primary_label') or 'Unit / Tajuk'
    s['curriculum_secondary_label']=profile.get('secondary_label') or 'Fokus'
    s['rpt_entry_id']=row.get('id')
    s['rpt_theme']=theme; s['rpt_unit_title']=unit; s['rpt_topic']=topic; s['rpt_subtopic']=subtopic; s['rpt_skill_focus']=skill
    # Human-facing title follows the subject profile while retaining all original fields.
    subject=str(s.get('subject') or '')
    if subject=='Bahasa Melayu':
        primary=unit or topic or theme
        secondary=subtopic or skill
    elif subject=='Bahasa Inggeris':
        primary=unit or topic
        secondary=skill or subtopic
    elif subject=='Matematik':
        primary=topic or unit or theme
        secondary=subtopic or skill
    elif subject=='Sains':
        primary=theme or unit or topic
        secondary=topic if primary!=topic else (subtopic or skill)
    else:
        primary=unit or topic or theme
        secondary=subtopic or skill
    s['topic']=primary or 'Fokus RPT'
    s['subtopic']=secondary or ''
    return s

try:
    init_local_db()
    seed_bbm_database()
    _ensure_subject_structure_profiles_v2384()
    _ensure_access_schema()
    # Database kurikulum production sudah diaudit; jangan seed/overwrite data kurikulum pada startup.
except Exception as e:
    print('Local DB/access init warning:', repr(e), flush=True)



