LOCAL_FIRST_MODE = True

def _cl_int_pair(level, op="sub"):
    if level == 1:
        a = random.randint(5, 10); b = random.randint(1, a if op == "sub" else 5)
    elif level == 2:
        a = random.randint(8, 18); b = random.randint(1, a if op == "sub" else 9)
    elif level == 3:
        a = random.randint(10, 50); b = random.randint(1, a if op == "sub" else 25)
    else:
        a = random.randint(15, 100); b = random.randint(1, a if op == "sub" else 50)
    return a, b

def _cl_math_subtraction_questions(level, n=8):
    items, objects = [], ["epal","pensel","guli","belon","buku","ikan","bunga","bola"]
    for i in range(n):
        a, b = _cl_int_pair(level, "sub")
        if level == 1:
            obj = random.choice(objects)
            q = f"{i+1}. Ada {a} {obj}. Pangkah/keluarkan {b}. Berapa yang tinggal?  {a} − {b} = ____"
        elif level == 2:
            q = f"{i+1}. {a} − {b} = ____"
        elif level == 3:
            obj = random.choice(objects)
            q = f"{i+1}. Dalam sebuah bekas ada {a} {obj}. {b} telah diambil. Berapa yang masih tinggal? ______"
        elif i % 2 == 0:
            q = f"{i+1}. Isi nombor yang hilang: {a} − ____ = {a-b}"
        else:
            q = f"{i+1}. Cipta satu cerita matematik yang sesuai dengan {a} − {b}, kemudian selesaikan."
        items.append(q)
    return items

def _cl_math_addition_questions(level, n=8):
    items, objects = [], ["epal","pensel","guli","belon","buku","ikan","bunga","bola"]
    for i in range(n):
        a, b = _cl_int_pair(level, "add")
        if level == 1:
            obj = random.choice(objects)
            q = f"{i+1}. Kumpulan pertama ada {a} {obj} dan kumpulan kedua ada {b}. Kira semuanya. {a} + {b} = ____"
        elif level == 2:
            q = f"{i+1}. {a} + {b} = ____"
        elif level == 3:
            obj = random.choice(objects)
            q = f"{i+1}. Aina ada {a} {obj} dan mendapat {b} lagi. Berapakah jumlahnya? ______"
        else:
            q = f"{i+1}. Lengkapkan dan terangkan cara: ____ + {b} = {a+b}"
        items.append(q)
    return items

def _cl_english_mixed_questions(state, level, n=8):
    """Zero-AI mixed-format English worksheet bank with real visual tokens and writing space."""
    seed=str(state.get('variation_seed') or '')+str(level)+str(state.get('topic') or '')
    rng=random.Random(seed)
    topic=(str(state.get('topic') or '')+' '+str(state.get('subtopic') or '')).lower()
    unit1=('where are you from' in topic or 'unit 1' in topic)
    countries=[('Malaysia','Malaysian'),('Japan','Japanese'),('China','Chinese'),('India','Indian'),('Australia','Australian')]
    rng.shuffle(countries)
    qs=[]
    if unit1:
        c1,n1=countries[0]; c2,n2=countries[1]
        qs=[
          f"Look and match. [VISUAL: flag {c1}, 1]\n{c1}    {n1}",
          f"Complete the word. I am from {c2}. I am ________. [ANSWERSPACE: 2]",
          f"Listen to your teacher and circle the country you hear.\nA. {c1}\nB. {c2}\nC. {countries[2][0]}\nD. {countries[3][0]}",
          "Complete the dialogue.\nA: Where are you from?\nB: I am from ____________. [ANSWERSPACE: 2]",
          f"Read the profile.\nName: Sara\nCountry: {c1}\nNationality: {n1}\nWrite one sentence about Sara. [WORKLINES: 3]",
          f"[VISUAL: child holding flag of {c2}, 1]\nWrite a suitable question for the answer: ‘I am from {c2}.’ [WORKLINES: 3]",
          "Put the words in the correct order.\nfrom / are / Where / you / ? [WORKLINES: 2]",
          "Write 2–3 sentences to introduce yourself. Include your name and where you are from. [WORKLINES: 5]"
        ]
    else:
        qs=[
          "Look at the picture and write one word. [VISUAL: school object, 1] [ANSWERSPACE: 2]",
          "Match the word to the picture. [VISUAL: everyday objects, 4]",
          "Complete the sentence with a suitable word. [ANSWERSPACE: 2]",
          "Choose the best answer.\nA. Yes\nB. No\nC. Maybe\nD. Thank you",
          "Put the words in the correct order to make a sentence. [WORKLINES: 2]",
          "Read the short sentence and answer in one or two words. [ANSWERSPACE: 2]",
          "Write a suitable question for the answer given. [WORKLINES: 3]",
          "Write 2–3 sentences about the picture. [VISUAL: children in a classroom, 1] [WORKLINES: 5]"
        ]
    # difficulty changes response demand, not just choices
    if level==1:
        qs=qs[:4]+["Circle the word that matches the picture. [VISUAL: familiar object, 1]\nA. book\nB. run\nC. happy\nD. blue"]+qs[1:4]
    elif level==2:
        qs=qs[:6]+qs[6:]
    elif level==3:
        qs=qs[2:]+qs[:2]
    else:
        qs=qs[4:]+["Explain your answer in one sentence. [WORKLINES: 3]", "Create a short dialogue of 4 lines using the language from this unit. [WORKLINES: 6]"]
    return qs[:max(1,n)]

def local_first_generate_worksheet(state, n_each=8):
    subject = str(state.get("subject") or state.get("subject_name") or "").lower()
    if 'bahasa inggeris' in subject or 'english' in subject:
        labels=['','ARAS 1 — PEMULIHAN / ASAS','ARAS 2 — SEDERHANA','ARAS 3 — PENGUASAAN','ARAS 4 — PENGAYAAN / KBAT']
        return [{'level':lv,'title':labels[lv],'questions':_cl_english_mixed_questions(state,lv,n_each),'source':'local_english_mixed_bank'} for lv in range(1,5)]

    if "matematik" not in subject and "math" not in subject:
        return None

    # Strict whitelist: only SP whose required skill is directly represented
    # by the local numeric rule. This prevents e.g. money, symbol-recognition,
    # repeated-addition or mixed-operation SP from receiving generic questions.
    year = str(state.get("year") or "")
    sp = str(state.get("sp_code") or "")
    safe = {
        ("Tahun 1","2.2.1"):_cl_math_addition_questions,
        ("Tahun 1","2.2.2"):_cl_math_addition_questions,
        ("Tahun 1","2.3.1"):_cl_math_subtraction_questions,
        ("Tahun 1","2.3.2"):_cl_math_subtraction_questions,
        ("Tahun 2","2.1.1"):_cl_math_addition_questions,
        ("Tahun 2","2.2.1"):_cl_math_subtraction_questions,
        ("Tahun 2","2.4.1"):_cl_math_division_questions,
        ("Tahun 2","2.4.2"):_cl_math_division_questions,
    }
    maker=safe.get((year,sp))
    if not maker:
        return None
    labels = ["","ARAS 1 — PEMULIHAN / ASAS","ARAS 2 — SEDERHANA",
              "ARAS 3 — PENGUASAAN","ARAS 4 — PENGAYAAN / KBAT"]
    return [{"level": lv, "title": labels[lv],
             "questions": maker(lv, n_each), "source": "local_rule_engine"}
            for lv in range(1,5)]


