# ============================================================
# v22.85 Worksheet Format Engine
# Format-first generation: SP -> format -> item -> answer space -> scheme
# ============================================================

def _worksheet_format_profiles_from_db(state, limit=6):
    subject=str(state.get('subject') or state.get('subject_name') or '').strip()
    topic=str(state.get('topic') or '').strip()
    sub=str(state.get('subtopic') or '').strip()
    sp=str(state.get('sp_text') or state.get('learning_standard') or '').strip()
    key=f"{topic} {sub} {sp}".lower()
    if not subject:
        return []
    try:
        conn=_db()
        rows=conn.execute("""SELECT family,format_key,match_keywords,item_structure,renderer_tokens,
                            answer_space_rule,level_rule,source_basis,priority
                            FROM worksheet_format_bank
                            WHERE subject=? AND verified=1
                            ORDER BY priority DESC,id""",(subject,)).fetchall()
        conn.close()
    except Exception as e:
        print('worksheet format bank:',repr(e),flush=True)
        return []
    scored=[]
    for r in rows:
        kws=[x.strip().lower() for x in re.split(r'[,|;/]+',str(r[2] or '')) if x.strip()]
        def _kw_hit(kw):
            # Whole word/phrase matching prevents false hits such as unit "m"
            # matching "masalah", or "masa" matching the start of "masalah".
            pat=r'(?<!\w)'+re.escape(kw)+r'(?!\w)'
            return bool(re.search(pat,key,re.I))
        score=sum(4 if _kw_hit(kw) else 0 for kw in kws)
        # General formats remain available but matched formats lead.
        if score==0:
            if subject=='Matematik' and str(r[1]) in ('word_problem','vertical_form'):
                score=1
            elif subject in ('Bahasa Melayu','Bahasa Inggeris') and str(r[1]) in ('single_passage','reading_text','guided_writing','guided_writing_en'):
                score=1
            elif subject=='Sains' and str(r[1]) in ('experiment_table','science_data','diagram_label'):
                score=1
            elif subject=='Sejarah' and str(r[1]) in ('history_source','timeline'):
                score=1
            elif subject=='Pendidikan Islam' and str(r[1]) in ('adab_scenario','ibadah_sequence'):
                score=1
        if score:
            scored.append((score,int(r[8] or 0),r))
    scored.sort(key=lambda x:(-x[0],-x[1],str(x[2][1])))
    out=[]
    seen=set()
    for _,__,r in scored:
        if r[1] in seen: continue
        seen.add(r[1]); out.append(r)
        if len(out)>=limit: break
    return out

def _worksheet_format_instruction(state):
    profiles=_worksheet_format_profiles_from_db(state,6)
    subject=str(state.get('subject') or '').strip()
    year=str(state.get('year') or '').strip()
    if not profiles:
        return ''
    lines=[
      "\nFORMAT-FIRST WORKSHEET ENGINE — WAJIB:",
      "Pilih format soalan SEBELUM menulis isi soalan. Setiap item mesti kelihatan seperti latihan sekolah yang boleh terus dicetak, bukan senarai soalan AI generik.",
      "Jangan menyalin soalan sumber. Gunakan hanya struktur pedagogi/format; semua nombor, ayat, petikan, stimulus dan situasi mesti baharu.",
      "Campurkan sekurang-kurangnya 3 bentuk item yang benar-benar sesuai dengan SP pada setiap aras apabila kemahiran membenarkan. Jangan paksa visual/jadual jika tidak membantu menjawab.",
      "Ruang jawapan mesti sepadan dengan kerja yang dijangka: jawapan nombor/1 perkataan = pendek; pengiraan = ruang kerja; penulisan = garisan; rajah = kotak/grid."
    ]
    for i,r in enumerate(profiles,1):
        family,key,kw,structure,tokens,space,level_rule,basis,priority=r
        lines.append(f"{i}. FORMAT {key}: {structure} Renderer yang sesuai: {tokens or 'tiada token khas'}. Ruang: {space}. Progres aras: {level_rule}.")
    if subject=='Matematik' and any(x in year for x in ('Tahun 4','Tahun 5','Tahun 6')):
        lines += [
          "MATEMATIK TAHAP II: ambil DNA instrumen UASA KPM 2025 — respons subjektif terhad/terbuka, bukan MCQ generik; worksheet bukan kertas UASA penuh.",
          "Aras 1-2 boleh menggunakan pengiraan/representasi ringkas; Aras 3 mesti ada aplikasi; Aras 4 mesti ada penaakulan/keputusan atau analisis kesilapan.",
          "Untuk masalah berayat, skema guru WAJIB menunjukkan penukaran unit (jika ada), operasi, pengiraan dan jawapan akhir dengan unit."
        ]
    if subject=='Sains' and any(x in year for x in ('Tahun 4','Tahun 5','Tahun 6')):
        lines.append("SAINS TAHAP II: gunakan stimulus sebenar seperti rajah, jadual data, pemerhatian atau penyiasatan; item perlu mengukur Kemahiran Proses Sains apabila SP berkaitan.")
    if subject in ('Bahasa Melayu','Bahasa Inggeris'):
        lines.append("BAHASA: jika soalan pemahaman, PETIKAN/TEKS MESTI DISERTAKAN sepenuhnya. Jangan buat 8 soalan bahasa dalam bentuk ayat satu baris yang sama.")
    return '\n'.join(lines)

# Override template profile so the visible prompt receives database-grounded formats.
worksheet_template_profile_v2284=worksheet_template_profile
def worksheet_template_profile(state):
    base=worksheet_template_profile_v2284(state)
    p=_worksheet_format_profiles_from_db(state,8)
    if p:
        base=dict(base)
        base['formats']=[str(r[1]) for r in p]
        base['format_details']=[{
            'family':r[0],'key':r[1],'structure':r[3],'tokens':r[4],
            'space':r[5],'levels':r[6]
        } for r in p]
    return base

_four_level_worksheet_prompt_v2284=_four_level_worksheet_prompt
def _four_level_worksheet_prompt(s):
    prompt=_four_level_worksheet_prompt_v2284(s)
    extra=_worksheet_format_instruction(s)
    return prompt + ("\n\n"+extra if extra else "") + """

QUALITY RULES FOR ALL FOUR LEVELS:
- Each numbered item must be complete, answerable and have the exact stimulus it refers to.
- Do not repeat one template eight times with changed numbers/nouns.
- Do not write a literal word such as 'visual', 'rajah di bawah', 'gambar di bawah', 'the diagram below' unless the supported visual/token is actually included.
- The pupil section must NOT contain answers.
- After EACH level, include a teacher scheme headed exactly 'SKEMA JAWAPAN:' / 'ANSWER SCHEME:' inside that level block.
- For Mathematics, every multi-step answer in the scheme must show working; verify arithmetic independently before finalising.
- For language open responses, give acceptable-answer criteria/sample points rather than pretending there is only one exact sentence.
- For Science/History/Islamic Education structured items, the scheme must state the expected fact/evidence/reason for each sub-part.
"""

# English local bank in v22.84 was intentionally broad; quality mode sends English through
# the format-first prompt instead. Keep safe local Mathematics rules for low-cost basic operations.
local_first_generate_worksheet_v2284=local_first_generate_worksheet
def local_first_generate_worksheet(state, n_each=8):
    subject=str(state.get('subject') or state.get('subject_name') or '').lower()
    if 'bahasa inggeris' in subject or 'english' in subject:
        return None
    return local_first_generate_worksheet_v2284(state,n_each)

def _worksheet_format_quality_issues(text,state):
    """Non-destructive final QA. Detect severe format failures before PDF creation."""
    raw=str(text or '')
    pupil,scheme=_worksheet_split(raw)
    joined='\n'.join(pupil)
    low=joined.lower()
    issues=[]
    q_expected=_worksheet_question_count(state)
    q_lines=[x for x in pupil if re.match(r'^\s*\d+[\.\)]\s+',x)]
    if len(q_lines)<max(4,q_expected-1):
        issues.append(f"bilangan item terlalu sedikit ({len(q_lines)}/{q_expected})")
    # Missing or thin marking scheme is a serious reliability issue.
    scheme_rows=[x for x in _extract_scheme_rows(scheme) if x[0] not in ('__SECTION__','__SHEET__','')]
    if len(scheme_rows)<max(3,int(len(q_lines)*0.70)):
        issues.append("skema jawapan tidak meliputi kebanyakan soalan")
    banned=[
      'berdasarkan gambar yang diberikan','berdasarkan rajah yang diberikan',
      'berdasarkan maklumat yang diberikan','situasi yang diberikan',
      'gambar di bawah' if not re.search(r'\[(?:VISUAL|DIAGRAM|FRACTION_BAR|FRACTION_SET)',raw,re.I) else '__ok__',
      'rajah di bawah' if not re.search(r'\[(?:VISUAL|DIAGRAM|FRACTION_BAR|FRACTION_SET)',raw,re.I) else '__ok__'
    ]
    for b in banned:
        if b!='__ok__' and b in low:
            issues.append("rujukan stimulus/visual tanpa bahan sebenar"); break
    subject=str(state.get('subject') or '')
    if subject=='Matematik':
        # A worksheet made entirely of plain text + "Jawapan:" is not workbook-quality.
        token_types=set(re.findall(r'\[(FORM_LAZIM|GRID|TABLE|DIAGRAM|FRACTION_BAR|FRACTION_SET|ANSWERSPACE|ANSWERBOX)\s*:',raw,re.I))
        topic=(str(state.get('topic') or '')+' '+str(state.get('sp_text') or '')).lower()
        visual_topics=('pecahan','data','graf','geometri','ruang','ukuran','sukatan','masa','waktu','wang','koordinat')
        if any(x in topic for x in visual_topics) and len(token_types)<1:
            issues.append("topik memerlukan representasi/ruang berstruktur tetapi tiada token layout/visual")
        # Scheme for calculation-heavy maths should visibly contain working signs.
        calc_words=('hitung','kirakan','operasi','tambah','tolak','darab','bahagi','ukuran','sukatan','wang')
        if any(x in topic for x in calc_words):
            scheme_text='\n'.join(scheme)
            if scheme_text and scheme_text.count('=')<max(2,len(q_lines)//3):
                issues.append("skema Matematik terlalu ringkas; jalan kerja tidak mencukupi")
    return list(dict.fromkeys(issues))

def _worksheet_pack_quality_summary(results,state):
    out=[]
    for key,val in (results or {}).items():
        for issue in _worksheet_format_quality_issues(val,state):
            out.append(f"{key}: {issue}")
    return out

_generate_four_level_worksheets_v2284=_generate_four_level_worksheets
def _generate_four_level_worksheets(s):
    results=_generate_four_level_worksheets_v2284(s)
    quality=_worksheet_pack_quality_summary(results,s)
    if quality:
        # Existing repair path already handles incomplete stimuli. For format failures,
        # perform one controlled rewrite only; no endless API retry loop.
        severe=[x for x in quality if ('skema' in x or 'stimulus' in x or 'terlalu sedikit' in x)]
        if severe:
            try:
                joined=[]
                for idx,(key,label,diff) in enumerate(WORKSHEET_LEVELS,1):
                    joined += [f"===ARAS_{idx}===",str(results.get(key,''))]
                draft='\n'.join(joined)
                prompt=_four_level_worksheet_prompt(s)+(
                    "\n\nDRAF INI GAGAL QA FORMAT. Tulis semula KESELURUHAN empat aras sekali sahaja. "
                    "Betulkan isu berikut: "+'; '.join(quality[:12])+
                    "\nDRAF:\n"+draft
                )
                fixed=gemini_generate(prompt,max_output_tokens=max(8192,_worksheet_output_token_budget(s)*3))
                parsed=_split_four_level_worksheet(fixed)
                if len(parsed)==4 and not _worksheet_pack_quality_summary(parsed,s):
                    results=parsed
            except Exception as e:
                print('worksheet format QA rewrite:',repr(e),flush=True)
        # Store issues for server logs; do not silently claim perfect QA.
        remaining=_worksheet_pack_quality_summary(results,s)
        if remaining:
            print('worksheet QA remaining:',remaining[:12],flush=True)
    return results



# ============================================================
# v22.86 WORKSHEET DB-FIRST
# Every verified curriculum standard has 4 recipe mappings in SQLite.
# Worksheet generation below is local/database driven and does NOT call Gemini.
# ============================================================

def _db_ws_recipe(state, level):
    year=str(state.get('year') or '').strip()
    subject=str(state.get('subject') or '').strip()
    sp_code=str(state.get('sp_code') or '').strip()
    sk_code=str(state.get('sk_code') or '').strip()
    try:
        con=_db()
        row=con.execute("""
            SELECT cs.id,cs.topic,cs.subtopic,cs.sk_code,cs.sk_text,cs.sp_code,cs.sp_text,
                   m.recipe_key,m.format_key
            FROM curriculum_standards cs
            JOIN worksheet_recipe_map m ON m.curriculum_standard_id=cs.id
            WHERE cs.verified=1 AND m.verified=1
              AND cs.year_label=? AND cs.subject=? AND cs.sp_code=? AND m.level=?
            ORDER BY CASE WHEN cs.sk_code=? THEN 0 ELSE 1 END, cs.id
            LIMIT 1
        """,(year,subject,sp_code,int(level),sk_code)).fetchone()
        con.close()
        return row
    except Exception as e:
        print('db worksheet recipe lookup:',repr(e),flush=True)
        return None

def _db_ws_pack_header(state, level):
    subj=str(state.get('subject') or '')
    labels={1:'ARAS 1 — PEMULIHAN / ASAS',2:'ARAS 2 — SEDERHANA',
            3:'ARAS 3 — PENGUASAAN',4:'ARAS 4 — PENGAYAAN / KBAT'}
    instruction='Jawab semua soalan dan tunjukkan jalan kerja apabila perlu.'
    if subj=='Bahasa Inggeris':
        instruction='Answer all questions. Show your working or evidence where needed.'
    return [labels[int(level)], 'Arahan: '+instruction if subj!='Bahasa Inggeris' else 'Instruction: '+instruction]

def _db_ws_math_scale(state, level, qcount, rng):
    """Local deterministic scale-drawing worksheet. Covers meaning/relationship first, then reasoning."""
    student=_db_ws_pack_header(state,level)
    ans=[]
    # Generate proportional actual/drawing dimensions.
    items=[]
    for i in range(max(qcount,8)):
        a=rng.choice([6,8,10,12,15,18,20,24,30])
        b=rng.choice([3,4,5,6,8,10,12])
        factor=rng.choice([2,3,4])
        if level==1:
            # Mostly reduction/enlargement recognition.
            if i%2==0:
                dw=max(1,a//factor); dh=max(1,b//factor)
                # Ensure exact proportional dimensions.
                a=dw*factor; b=dh*factor
                items.append(('reduce',a,b,dw,dh,factor))
            else:
                dw=a*factor; dh=b*factor
                items.append(('enlarge',a,b,dw,dh,factor))
        else:
            dw=max(1,a//factor); dh=max(1,b//factor)
            a=dw*factor; b=dh*factor
            items.append(('reduce',a,b,dw,dh,factor))
    student += ['BAHAGIAN A','Kaji hubungan ukuran sebenar dengan ukuran pada lukisan.']
    for i,(kind,aw,ah,dw,dh,f) in enumerate(items[:qcount],1):
        if level==1:
            if i<=4:
                student.append(
                    f"{i}. Objek sebenar berukuran {aw} cm × {ah} cm. Lukisan berukuran {dw} cm × {dh} cm. "
                    f"Adakah lukisan itu pengecilan, pembesaran atau saiz sebenar? [ANSWERSPACE: 2]"
                )
                answer='pengecilan' if kind=='reduce' else 'pembesaran'
                ans.append(f"{i}. {answer}; kedua-dua ukuran berubah dengan faktor yang sama ({f}).")
            else:
                student.append(
                    f"{i}. Bandingkan nisbah panjang dan lebar bagi objek sebenar {aw}:{ah} dengan lukisan {dw}:{dh}. "
                    f"Adakah bentuk dikekalkan secara berkadar? [ANSWERSPACE: 3]"
                )
                ans.append(f"{i}. Ya. {dw}/{aw} = {dh}/{ah} = {1/f if kind=='reduce' else f:g}; nisbah sepadan sama.")
        elif level==2:
            if i<=3:
                student.append(
                    f"{i}. Objek sebenar: {aw} cm × {ah} cm. Lukisan: {dw} cm × {dh} cm. "
                    "Tentukan nisbah ukuran lukisan : ukuran sebenar bagi kedua-dua sisi. [ANSWERSPACE: 3]"
                )
                ans.append(f"{i}. {dw}:{aw} = {dh}:{ah} = 1:{f}.")
            elif i<=6:
                student.append(
                    f"{i}. Sebuah lukisan berukuran {dw} cm × {dh} cm mewakili objek {aw} cm × {ah} cm. "
                    "Terangkan dengan satu ayat mengapa lukisan itu ialah lukisan berskala. [ANSWERSPACE: 3]"
                )
                ans.append(f"{i}. Kedua-dua ukuran lukisan berubah daripada ukuran sebenar dengan faktor yang sama, iaitu 1:{f}.")
            else:
                # deliberately break one side to test understanding
                wrong=dh+1
                student.append(
                    f"{i}. Objek sebenar berukuran {aw} cm × {ah} cm. Seorang murid melukis {dw} cm × {wrong} cm. "
                    "Adakah ini lukisan berskala? Jelaskan. [ANSWERSPACE: 4]"
                )
                ans.append(f"{i}. Tidak. Nisbah sisi pertama ialah {dw}:{aw}=1:{f}, tetapi nisbah sisi kedua {wrong}:{ah} tidak sama.")
        elif level==3:
            if i<=4:
                student.append(
                    f"{i}. Lengkapkan perbandingan berikut: objek sebenar {aw} cm × {ah} cm dan lukisan {dw} cm × {dh} cm. "
                    "Tuliskan faktor perubahan bagi panjang dan lebar, kemudian buat kesimpulan. [TABLE: 3, 3] [ANSWERSPACE: 3]"
                )
                ans.append(f"{i}. Panjang ÷{f}; lebar ÷{f}; kedua-duanya sama, maka lukisan berkadar/lukisan berskala.")
            else:
                wrong=dh+rng.choice([1,2])
                student.append(
                    f"{i}. Dua cadangan lukisan untuk objek {aw} cm × {ah} cm ialah A: {dw} cm × {dh} cm dan "
                    f"B: {dw} cm × {wrong} cm. Pilih lukisan yang mengekalkan bentuk asal dan buktikan dengan nisbah. [ANSWERSPACE: 5]"
                )
                ans.append(f"{i}. A. {dw}/{aw} = {dh}/{ah} = 1/{f}; B tidak mempunyai nisbah sepadan yang sama.")
        else:
            wrong=dh+rng.choice([1,2])
            if i<=4:
                student.append(
                    f"{i}. Faris berkata, “Asalkan lukisan lebih kecil daripada objek sebenar, lukisan itu ialah lukisan berskala.” "
                    f"Uji kenyataan itu menggunakan objek {aw} cm × {ah} cm dan lukisan {dw} cm × {wrong} cm. [ANSWERSPACE: 5]"
                )
                ans.append(f"{i}. Kenyataan Faris salah. Kedua-dua sisi mesti berubah dengan faktor yang sama; {dw}/{aw} tidak sama dengan {wrong}/{ah}.")
            else:
                student.append(
                    f"{i}. Objek sebenar {aw} cm × {ah} cm diwakili oleh lukisan {dw} cm × {dh} cm. "
                    "Terangkan maksud 'lukisan berskala' berdasarkan contoh ini tanpa hanya menyebut 'lebih kecil'. [ANSWERSPACE: 5]"
                )
                ans.append(f"{i}. Lukisan berskala ialah lukisan yang semua ukuran sepadannya berubah secara berkadar dengan faktor tetap; di sini faktor lukisan:sebenar ialah 1:{f}.")
    student += ['SKEMA JAWAPAN:'] + ans[:qcount]
    return '\n'.join(student)

def _db_ws_math_generic(state, level, qcount, rng, recipe):
    student=_db_ws_pack_header(state,level)
    ans=[]
    topic=str(state.get('topic') or '')
    # Local deterministic arithmetic/application fallback; no API.
    for i in range(1,qcount+1):
        if recipe=='math_fraction':
            den=rng.choice([4,5,6,8,10,12]); n1=rng.randint(1,den-1); n2=rng.randint(1,den-1)
            if level<=2:
                student.append(f"{i}. Bandingkan {n1}/{den} dan {n2}/{den}. Tulis >, < atau =. [ANSWERSPACE: 2]")
                sym='>' if n1>n2 else '<' if n1<n2 else '='
                ans.append(f"{i}. {sym}")
            else:
                total=n1+n2
                student.append(f"{i}. Hitung {n1}/{den} + {n2}/{den}. Ringkaskan jika boleh. [ANSWERSPACE: 4]")
                g=math.gcd(total,den); ans.append(f"{i}. {total}/{den} = {total//g}/{den//g}.")
        elif recipe=='math_percent':
            base=rng.choice([40,50,80,100,120,200]); pct=rng.choice([10,20,25,50,75])
            val=base*pct//100
            student.append(f"{i}. Cari {pct}% daripada {base}. [ANSWERSPACE: 3]")
            ans.append(f"{i}. {pct}/100 × {base} = {val}.")
        elif recipe=='math_ratio':
            a=rng.randint(2,9); b=rng.randint(2,9); k=rng.randint(2,5)
            student.append(f"{i}. Nisbah A:B ialah {a}:{b}. Jika kedua-duanya didarab {k}, tulis nisbah baharu dan jelaskan hubungannya. [ANSWERSPACE: 3]")
            ans.append(f"{i}. {a*k}:{b*k}; nisbah setara dengan {a}:{b}.")
        elif recipe=='math_time':
            h=rng.randint(1,10); m=rng.choice([0,15,30,45]); add=rng.choice([30,45,60,90])
            total=(h*60+m+add); hh=(total//60)%24; mm=total%60
            student.append(f"{i}. Aktiviti bermula pada {h:02d}:{m:02d} dan berlangsung {add} minit. Pukul berapakah aktiviti tamat? [ANSWERSPACE: 3]")
            ans.append(f"{i}. {hh:02d}:{mm:02d}.")
        elif recipe=='math_money':
            p=rng.randint(12,80); pay=((p+9)//10)*10
            student.append(f"{i}. Harga sebuah barang ialah RM{p}.00. Bayaran RM{pay}.00. Hitung baki. [ANSWERSPACE: 3]")
            ans.append(f"{i}. RM{pay}.00 − RM{p}.00 = RM{pay-p}.00.")
        elif recipe=='math_measure':
            cm=rng.randint(120,950)
            student.append(f"{i}. Tukarkan {cm} cm kepada m dan cm. [ANSWERSPACE: 3]")
            ans.append(f"{i}. {cm//100} m {cm%100} cm.")
        elif recipe=='math_data':
            vals=[rng.randint(2,12) for _ in range(4)]
            student.append(f"{i}. Data: {', '.join(map(str,vals))}. Hitung jumlah dan julat data. [ANSWERSPACE: 4]")
            ans.append(f"{i}. Jumlah = {sum(vals)}; julat = {max(vals)-min(vals)}.")
        elif recipe=='math_geometry':
            l=rng.randint(4,15); w=rng.randint(3,12)
            student.append(f"{i}. Sebuah segi empat tepat mempunyai panjang {l} cm dan lebar {w} cm. Hitung perimeter. [ANSWERSPACE: 3]")
            ans.append(f"{i}. 2({l}+{w}) = {2*(l+w)} cm.")
        elif recipe=='math_algebra':
            x=rng.randint(2,20); a=rng.randint(2,9); total=x+a
            student.append(f"{i}. Selesaikan x + {a} = {total}. [ANSWERSPACE: 3]")
            ans.append(f"{i}. x = {total} − {a} = {x}.")
        elif recipe=='math_number':
            n=rng.randint(100,9999)
            student.append(f"{i}. Nyatakan nilai digit {str(n)[0]} dalam nombor {n}. [ANSWERSPACE: 2]")
            val=int(str(n)[0])*(10**(len(str(n))-1)); ans.append(f"{i}. {val}.")
        else:
            a=rng.randint(20,300); b=rng.randint(2,20)
            if level<=2:
                student.append(f"{i}. Hitung {a} + {b}. [FORM_LAZIM: 3, 4]")
                ans.append(f"{i}. {a} + {b} = {a+b}.")
            else:
                c=rng.randint(5,40)
                student.append(f"{i}. Sebuah situasi melibatkan {a} unit, ditambah {b} unit kemudian digunakan {c} unit. Berapakah baki? [ANSWERSPACE: 4]")
                ans.append(f"{i}. {a}+{b}−{c} = {a+b-c}.")
    student += ['SKEMA JAWAPAN:'] + ans
    return '\n'.join(student)

def _db_ws_language_generic(state, level, qcount, rng, recipe):
    subject=str(state.get('subject') or '')
    topic=str(state.get('topic') or 'topik pembelajaran')
    sp=str(state.get('sp_text') or '')
    student=_db_ws_pack_header(state,level); ans=[]
    if subject=='Bahasa Inggeris':
        if recipe=='en_speaking':
            student += ['TASK CARDS','Work with a partner. Use the prompts orally, then record a short outcome.']
            prompts=[
                "Give three clear instructions for a simple classroom task.",
                "Ask your partner to repeat or clarify one step.",
                "Describe the order of four actions using first, next, then and finally.",
                "Check whether your partner has understood the instructions.",
                "Change one detail and give the instructions again.",
                "Respond politely when one step is unclear.",
                "Give directions from one classroom place to another.",
                "Explain one reason why the order of steps matters."
            ]
            for i in range(qcount):
                student.append(f"{i+1}. {prompts[i%len(prompts)]} [ANSWERBOX: 2]")
                ans.append(f"{i+1}. Accept an accurate oral response that fulfils the Learning Standard; check clarity, sequence and appropriate language.")
        elif recipe=='en_listening':
            script=f"Teacher script: Today the class is learning about {topic}. First, pupils listen for the main idea. Next, they identify two important details. Finally, they check the order of the information."
            student += ['TEACHER SCRIPT',script]
            qs=["What is the class learning about?","What should pupils listen for first?","How many important details should they identify?","What should pupils do finally?"]
            for i in range(qcount):
                q=qs[i%4]; student.append(f"{i+1}. {q} [ANSWERSPACE: 2]")
                answers=[topic,"the main idea","two","check the order of the information"]; ans.append(f"{i+1}. {answers[i%4]}")
        else:
            passage=(f"During a lesson about {topic}, Maya reads the instructions carefully. "
                     "She underlines key words, checks the order of the steps and asks for clarification when a detail is not clear. "
                     "After completing the task, she reviews her work before sharing it with a partner.")
            student += ['TEXT',passage]
            qs=[
                ("What does Maya do first?","She reads the instructions carefully."),
                ("What does she underline?","Key words."),
                ("What does she do when a detail is unclear?","She asks for clarification."),
                ("What does she do before sharing her work?","She reviews her work."),
                ("Find a word that means 'make sure'.","checks/reviews (accept contextually suitable answer)."),
                ("Why is checking the order useful?","It helps complete the task in the correct sequence."),
                ("State one good learning habit shown by Maya.","Any supported habit, e.g. reviewing work."),
                ("Write one sentence explaining how you would check your own work.","Accept a relevant grammatical sentence.")
            ]
            for i in range(qcount):
                q,a=qs[i%len(qs)]; student.append(f"{i+1}. {q} [ANSWERBOX: 2]"); ans.append(f"{i+1}. {a}")
        student += ['ANSWER SCHEME:']+ans
        return '\n'.join(student)
    # Bahasa Melayu
    if recipe=='bm_literature':
        text=("Rajin belajar setiap hari,\nIlmu dicari penuh tekun,\nBahasa santun menghias diri,\nBudi terpuji hidup tersusun.")
        student += ['TEKS',text]
        qs=[
            ("Nyatakan satu nilai yang terdapat dalam teks.","rajin / santun / berbudi"),
            ("Apakah idea keseluruhan teks?","Kepentingan rajin belajar dan berbahasa santun."),
            ("Cari satu perkataan yang berkaitan dengan kesantunan.","santun / budi"),
            ("Terangkan maksud 'ilmu dicari penuh tekun'.","Belajar bersungguh-sungguh untuk memperoleh ilmu."),
            ("Bina satu ayat menggunakan perkataan 'santun'.","Terima ayat gramatis."),
            ("Nyatakan satu tindakan yang menunjukkan budi bahasa.","Terima tindakan munasabah."),
            ("Apakah kesan bahasa santun dalam pergaulan?","Hubungan lebih baik/harmoni; terima jawapan munasabah."),
            ("Tulis dua baris sambungan yang mengekalkan tema.","Terima sambungan sesuai dan sopan.")
        ]
    else:
        passage=(f"Pada minggu ini, murid kelas 5 Bestari menjalankan aktiviti berkaitan {topic}. "
                 "Mereka membaca arahan, berbincang secara sopan dan mencatat idea penting. "
                 "Selepas itu, setiap kumpulan menyemak hasil kerja sebelum membuat pembentangan ringkas.")
        student += ['PETIKAN',passage]
        qs=[
            ("Apakah aktiviti yang dijalankan oleh murid?","Aktiviti berkaitan "+topic+"."),
            ("Bagaimanakah murid berbincang?","Secara sopan."),
            ("Apakah yang dicatat oleh murid?","Idea penting."),
            ("Bilakah mereka menyemak hasil kerja?","Sebelum pembentangan ringkas."),
            ("Nyatakan satu nilai murni dalam petikan.","Kerjasama/kesopanan/bertanggungjawab."),
            ("Mengapakah semakan hasil kerja penting?","Untuk membaiki kesalahan/meningkatkan kualiti."),
            ("Bina satu ayat menggunakan perkataan 'berbincang'.","Terima ayat gramatis."),
            ("Tulis satu cadangan untuk menjadikan aktiviti lebih berkesan.","Terima cadangan munasabah.")
        ]
    for i in range(qcount):
        q,a=qs[i%len(qs)]; student.append(f"{i+1}. {q} [ANSWERBOX: 2]"); ans.append(f"{i+1}. {a}")
    student += ['SKEMA JAWAPAN:']+ans
    return '\n'.join(student)

def _db_ws_other_generic(state, level, qcount, rng, recipe):
    subject=str(state.get('subject') or '')
    topic=str(state.get('topic') or '')
    sp=str(state.get('sp_text') or '')
    student=_db_ws_pack_header(state,level); ans=[]
    if subject=='Sains':
        # Self-contained data task avoids waiting for AI or missing diagrams.
        values=[rng.randint(2,6)]
        for _ in range(3): values.append(values[-1]+rng.randint(1,4))
        student += ['STIMULUS',f"Sekumpulan murid mengkaji {topic}. Mereka merekod empat bacaan berturutan: {values[0]}, {values[1]}, {values[2]} dan {values[3]}. Semua keadaan lain dikekalkan sama."]
        qs=[
            ("Nyatakan bacaan paling tinggi.",str(max(values))),
            ("Nyatakan bacaan paling rendah.",str(min(values))),
            ("Apakah pola perubahan data?","Meningkat."),
            ("Hitung beza bacaan tertinggi dengan terendah.",str(max(values)-min(values))),
            ("Nyatakan satu perkara yang perlu dikekalkan sama dalam penyiasatan.","Terima pemboleh ubah dimalarkan yang munasabah."),
            ("Buat satu inferens berdasarkan pola data.","Terima inferens yang konsisten dengan data."),
            ("Ramalkan bacaan seterusnya dan beri sebab.","Terima ramalan munasabah berdasarkan pola."),
            ("Cadangkan satu cara meningkatkan kebolehpercayaan data.","Ulang penyiasatan / ambil purata / kawal pemboleh ubah.")
        ]
    elif subject=='Sejarah':
        student += ['SUMBER A',f"Topik: {topic}. Standard pembelajaran: {sp}"]
        qs=[
            ("Nyatakan topik yang dinyatakan dalam Sumber A.",topic),
            ("Nyatakan fokus utama standard pembelajaran.",sp),
            ("Senaraikan satu kata kunci penting daripada sumber.","Terima kata kunci tepat daripada sumber."),
            ("Apakah jenis maklumat yang perlu dicari untuk memahami topik ini?","Fakta/peristiwa/tokoh/sebab/kesan yang relevan."),
            ("Bina satu soalan sejarah berdasarkan sumber.","Terima soalan relevan."),
            ("Nyatakan satu bukti yang perlu digunakan untuk menyokong jawapan sejarah.","Sumber/dokumen/fakta yang sah."),
            ("Terangkan mengapa kronologi membantu memahami sejarah.","Menunjukkan urutan dan hubungan peristiwa."),
            ("Tulis satu kesimpulan ringkas berdasarkan fokus standard.","Terima kesimpulan yang menepati SP.")
        ]
    else:  # Pendidikan Islam
        student += ['FOKUS PEMBELAJARAN',f"{topic}: {sp}"]
        qs=[
            ("Nyatakan tajuk pembelajaran.",topic),
            ("Nyatakan satu fokus yang disebut dalam standard pembelajaran.",sp),
            ("Senaraikan satu istilah penting daripada fokus di atas.","Terima istilah tepat daripada fokus."),
            ("Nyatakan satu contoh amalan yang sesuai dengan fokus pembelajaran.","Terima contoh yang tepat dan sesuai."),
            ("Mengapakah amalan yang betul penting dalam kehidupan harian?","Terima sebab yang sesuai dengan nilai/ibadah/adab."),
            ("Bina satu situasi harian yang berkaitan dengan fokus.","Terima situasi relevan."),
            ("Apakah tindakan yang wajar dalam situasi tersebut?","Terima tindakan selaras dengan fokus."),
            ("Tulis satu pengajaran yang boleh diamalkan.","Terima pengajaran sesuai.")
        ]
    for i in range(qcount):
        q,a=qs[i%len(qs)]; student.append(f"{i+1}. {q} [ANSWERBOX: 2]"); ans.append(f"{i+1}. {a}")
    student += ['SKEMA JAWAPAN:']+ans
    return '\n'.join(student)

def _db_first_generate_one_level(state, level, qcount):
    row=_db_ws_recipe(state,level)
    if not row:
        raise RuntimeError(f"Tiada recipe DB untuk {state.get('year')} {state.get('subject')} SP {state.get('sp_code')} aras {level}")
    recipe=str(row['recipe_key'])
    seed=f"{state.get('variation_seed','')}-{state.get('year','')}-{state.get('subject','')}-{state.get('sp_code','')}-{level}"
    rng=random.Random(seed)
    if recipe=='math_scale':
        return _db_ws_math_scale(state,level,qcount,rng)
    if recipe.startswith('math_'):
        return _db_ws_math_generic(state,level,qcount,rng,recipe)
    if recipe.startswith('bm_') or recipe.startswith('en_'):
        return _db_ws_language_generic(state,level,qcount,rng,recipe)
    return _db_ws_other_generic(state,level,qcount,rng,recipe)

def _db_first_generate_worksheet_pack(state):
    qcount=_worksheet_question_count(state)
    out={}
    for idx,(key,label,diff) in enumerate(WORKSHEET_LEVELS,1):
        out[key]=_db_first_generate_one_level(state,idx,qcount)
    return out

# Final worksheet override: DB/local only. No Gemini call in worksheet generation.
_generate_four_level_worksheets_ai_legacy=_generate_four_level_worksheets
def _worksheet_auto_qcount(s):
    # Internal density only; never shown as a teacher choice.
    year=str(s.get('year') or '')
    base=6 if year in ('Tahun 1','Tahun 2','Tahun 3') else 8
    skill=str(s.get('worksheet_skill_family') or s.get('skill_family') or '').lower()
    if any(x in skill for x in ('writing','diagram','calculation','reasoning','essay')): base=max(4,base-2)
    elif any(x in skill for x in ('matching','sequence','vocabulary','phonics','number')): base=min(10,base+1)
    s['worksheet_questions']=base
    s['worksheet_questions_auto']=True
    return base

def _generate_four_level_worksheets(s):
    _worksheet_auto_qcount(s)
    results=_db_first_generate_worksheet_pack(s)
    # v23.16: local/database QA is now fail-safe. Never send a known-bad worksheet.
    # Runtime still NEVER falls back to Gemini/AI.
    issues=_worksheet_pack_quality_summary(results,s)
    if issues:
        raise RuntimeError('Worksheet DB QA failed: ' + '; '.join(issues[:12]))
    return results



