def _runtime_generation_mode():
    try:
        con=_db()
        row=con.execute("SELECT config_value FROM system_runtime_config WHERE config_key='generation_mode'").fetchone()
        con.close()
        return str(row[0] if row else 'database_only')
    except Exception:
        return 'database_only'

def _runtime_ai_allowed():
    # Runtime bot generation NEVER uses AI. This is intentionally hard-coded.
    return False

def _db_build_ai_allowed():
    # Optional offline/admin database-building script can explicitly enable AI.
    # Normal Telegram runtime must not set this flag.
    return str(os.getenv('CIKGULAJU_DB_BUILD_MODE','0')).strip() == '1'

# Keep the original API wrapper available only for controlled database-building use.
_gemini_generate_database_builder=gemini_generate
def gemini_generate(prompt, max_output_tokens=4096):
    if not _db_build_ai_allowed():
        raise RuntimeError(
            "Runtime AI disabled: CikguLaju is configured for DATABASE-ONLY generation. "
            "AI is allowed only with CIKGULAJU_DB_BUILD_MODE=1 for offline database completion."
        )
    return _gemini_generate_database_builder(prompt,max_output_tokens=max_output_tokens)

def _db_only_single_worksheet(s):
    """Return one local worksheet level for legacy single-worksheet routes."""
    diff=str(s.get('difficulty') or 'medium').lower()
    level={'easy':1,'medium':2,'mixed':2,'hard':3,'kbat':4,'all4':2}.get(diff,2)
    q=_worksheet_question_count(s)
    return _db_first_generate_one_level(s,level,q)

# Override legacy generic generation route so it can never call Gemini.
def generate_ai(cid):
    s=state.setdefault(cid,{})
    if not s.get('topic'):
        return send(cid,'⚠️ Pilihan belum lengkap. Sila pilih tajuk dahulu.',
                    [[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    try:
        s['variation_seed']=secrets.token_hex(4)
        task=str(s.get('task') or 'worksheet')
        if task=='rph':
            result=_duration_fit_rph_text(_local_rph_text(s),s)
        elif task=='worksheet':
            result=_db_only_single_worksheet(s)
        elif task=='bbm':
            return _continue_same_selection(cid,'bbm')
        else:
            return send(cid,'⚠️ Bahan ini belum mempunyai bank database tempatan yang lengkap.',
                        [[{'text':'🏠 Menu Utama','callback_data':'home'}]])
        result=_hybrid_postprocess_worksheet(result,s) if task=='worksheet' else result
        state[cid]['last_result']=result
        state[cid]['last_result_context']=dict(s)
        send_long_plain(cid,result)
        return send(cid,'✅ <b>Siap — dijana daripada database tempatan.</b>',
                    [[{'text':'🔄 Jana Semula','callback_data':'generate'}],
                     [{'text':'🏠 Menu Utama','callback_data':'home'}]])
    except Exception as e:
        print('DB-only generate error:',repr(e),flush=True)
        return send(cid,'⚠️ Bahan ini belum lengkap dalam database tempatan. Tiada fallback AI digunakan.',
                    [[{'text':'🏠 Menu Utama','callback_data':'home'}]])

# Override current RPH/single-worksheet path: database/local only.
def generate_v3(cid,s,regen_cb):
    with _runtime_lock:
        if cid in _processing_chats:
            return send(cid,'⏳ <b>Proses sedang berjalan.</b>')
        _processing_chats.add(cid)
    try:
        s['variation_seed']=secrets.token_hex(4)
        task=str(s.get('task') or '')
        if task=='rph':
            send(cid,'⚡ <b>Menyediakan RPH daripada database...</b>')
            result=_duration_fit_rph_text(_local_rph_text(s),s)
            _rph_cache_put(s,result)
            state.setdefault(cid,{})['last_result']=result
            state[cid]['last_result_context']=dict(s)
            kb=[[{'text':'📄 Dapatkan PDF','callback_data':'file_pdf'}]] + _integrated_material_buttons('rph') + [
                [{'text':'🔄 Jana Semula RPH','callback_data':regen_cb}],
                [{'text':'🏠 Menu Utama','callback_data':'home'}]]
            return send(cid,'✅ <b>RPH siap daripada database.</b>',kb)
        if task=='worksheet':
            send(cid,'⚡ <b>Menyediakan worksheet daripada database...</b>')
            result=_db_only_single_worksheet(s)
            result=_hybrid_postprocess_worksheet(result,s)
            state.setdefault(cid,{})['last_result']=result
            state[cid]['last_result_context']=dict(s)
            kb=[[{'text':'📄 Dapatkan PDF','callback_data':'file_pdf'}]] + _integrated_material_buttons('worksheet') + [
                [{'text':'🔄 Jana Semula','callback_data':regen_cb}],
                [{'text':'🏠 Menu Utama','callback_data':'home'}]]
            return send(cid,'✅ <b>Worksheet siap daripada database.</b>',kb)
        if task=='bbm':
            return _continue_same_selection(cid,'bbm')
        return send(cid,'⚠️ Jenis bahan ini belum mempunyai laluan database tempatan.',
                    [[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    except Exception as e:
        print('DB-only generate_v3 error:',repr(e),flush=True)
        return send(cid,'⚠️ Data untuk pilihan ini belum lengkap dalam database tempatan. Tiada panggilan AI dibuat.',
                    [[{'text':'🔄 Cuba Lagi','callback_data':regen_cb}],
                     [{'text':'🏠 Menu Utama','callback_data':'home'}]])
    finally:
        with _runtime_lock:
            _processing_chats.discard(cid)

# Safety assertion helper used by diagnostics/admin tests.
def _assert_database_only_runtime():
    if _runtime_generation_mode()!='database_only':
        raise RuntimeError('generation_mode bukan database_only')
    if _runtime_ai_allowed():
        raise RuntimeError('Runtime AI unexpectedly enabled')
    return True



