# v22.88 WORKSHEET CONTEXT BANK
# Malaysian-context vocabulary is stored in DB and sampled
# deterministically. No runtime AI.
# ============================================================

def _ws_context_values(category, subcategory='', limit=200):
    try:
        con=_db()
        if subcategory:
            rows=con.execute("""SELECT value FROM worksheet_context_bank
                WHERE verified=1 AND category=? AND subcategory=?
                ORDER BY id LIMIT ?""",(category,subcategory,int(limit))).fetchall()
        else:
            rows=con.execute("""SELECT value FROM worksheet_context_bank
                WHERE verified=1 AND category=?
                ORDER BY id LIMIT ?""",(category,int(limit))).fetchall()
        con.close()
        return [str(r[0]) for r in rows]
    except Exception:
        return []

def _ws_context_pick(category, seed='', subcategory=''):
    vals=_ws_context_values(category,subcategory,500)
    if not vals:
        return ''
    rng=random.Random(str(seed)+'|'+category+'|'+subcategory)
    return vals[rng.randrange(len(vals))]

def _ws_person(seed=''):
    # Rotate broad Malaysian naming styles without tying any task/ability to ethnicity.
    groups=['Malay-style','Chinese-Malaysian-style','Indian-Malaysian-style','East-Malaysian-style']
    rng=random.Random(str(seed)+'|person-group')
    group=groups[rng.randrange(len(groups))]
    return _ws_context_pick('person_name',str(seed)+'|person',group)

def _ws_context_bundle(seed=''):
    return {
        'person':_ws_person(seed),
        'object':_ws_context_pick('object',seed),
        'place':_ws_context_pick('place',seed),
        'animal':_ws_context_pick('animal',seed),
        'food':_ws_context_pick('food',seed),
        'occupation':_ws_context_pick('occupation',seed),
        'action':_ws_context_pick('action',seed),
        'unit':_ws_context_pick('unit_context',seed),
    }

# Public diagnostic for DB-only worksheet context coverage.
def _worksheet_context_bank_audit():
    con=_db()
    rows=con.execute("""SELECT category,COUNT(*) FROM worksheet_context_bank
        WHERE verified=1 GROUP BY category ORDER BY category""").fetchall()
    con.close()
    return {str(r[0]):int(r[1]) for r in rows}



