def _db_ws_other_generic(state, level, qcount, rng, recipe):
    subject=str(state.get('subject') or '')
    topic=str(state.get('topic') or '')
    sp=str(state.get('sp_text') or '')
    seed=f"{state.get('variation_seed','')}|{state.get('year','')}|{state.get('sp_code','')}|L{level}"
    c=_ws_context_for(state,seed); student=_db_ws_pack_header(state,level); ans=[]
    if subject=='Sains':
        vals=[rng.randint(2,6)]
        for _ in range(3): vals.append(vals[-1]+rng.randint(1,4))
        stim=_ws_fill_template(_ws_stimulus_pick('Sains','investigation',seed),state,seed)
        if recipe=='sci_data':
            student += ['STIMULUS',stim,
                f"Data empat bacaan: A={vals[0]}, B={vals[1]}, C={vals[2]}, D={vals[3]}. [TABLE: 5, 2]"]
        elif recipe=='sci_inquiry':
            student += ['PENYIASATAN',stim,
                f"Bacaan yang direkod secara berturutan ialah {vals[0]}, {vals[1]}, {vals[2]} dan {vals[3]}."]
        elif recipe=='sci_diagram':
            student += ['RAJAH / MODEL',f"Fokus rajah ialah {topic}. Gunakan kotak berlabel untuk menunjukkan bahagian, urutan atau hubungan yang dinyatakan dalam SP berikut: {sp}. [TABLE: 4, 2]"]
        elif recipe=='sci_apply':
            student += ['SITUASI',f"Di {c.get('place') or 'sekolah'}, {c['person']} perlu menggunakan pengetahuan tentang {topic} untuk membuat keputusan yang sesuai. Fokus SP: {sp}."]
        else:
            student += ['STIMULUS',stim,
                f"Fokus pembelajaran: {sp}. Bacaan contoh ialah {vals[0]}, {vals[1]}, {vals[2]} dan {vals[3]}."]
        qs=[
            ("Nyatakan satu pemerhatian yang boleh dibuat.",f"Data berubah daripada {vals[0]} kepada {vals[-1]} / terima pemerhatian tepat."),
            ("Apakah pola data yang ditunjukkan?","Meningkat."),
            ("Hitung beza bacaan tertinggi dengan terendah.",str(max(vals)-min(vals))),
            ("Nyatakan satu pemboleh ubah yang perlu dikekalkan sama.","Terima pemboleh ubah dimalarkan yang sesuai dengan penyiasatan."),
            ("Buat satu inferens yang konsisten dengan data.","Terima inferens yang disokong oleh data dan topik."),
            ("Cadangkan satu cara meningkatkan kebolehpercayaan keputusan.","Ulang penyiasatan dan ambil purata / kawal pemboleh ubah."),
            ("Ramalkan hasil seterusnya dan berikan alasan.","Terima ramalan yang konsisten dengan pola."),
            ("Hubungkan dapatan dengan fokus SP.","Terima penerangan saintifik yang tepat dan menepati SP.")
        ]
    elif subject=='Sejarah':
        stim=_ws_fill_template(_ws_stimulus_pick('Sejarah','source_inquiry',seed),state,seed)
        student += ['KAD SUMBER',stim,f"Fokus pembelajaran: {sp}"]
        if recipe=='hist_timeline':
            student += ['GARIS MASA', 'Susun maklumat yang dikenal pasti daripada fokus pembelajaran mengikut urutan awal → pertengahan → akhir. [TABLE: 4, 2]']
        qs=[
            ("Apakah topik yang sedang dikaji?",topic),
            ("Nyatakan satu kata kunci penting daripada fokus pembelajaran.","Terima kata kunci tepat daripada SP."),
            ("Apakah jenis sumber yang digunakan dalam Kad Sumber?","Terima jenis sumber yang dinyatakan dalam kad."),
            ("Nyatakan satu soalan sejarah yang sesuai ditanya berdasarkan fokus tersebut.","Terima soalan yang relevan."),
            ("Bagaimanakah sumber boleh digunakan untuk menyokong jawapan?","Petik maklumat/bukti yang berkaitan dan hubungkan dengan soalan."),
            ("Jika melibatkan urutan, apakah maklumat yang perlu dikenal pasti dahulu?","Tarikh/peristiwa/tahap yang menunjukkan kronologi; terima jawapan relevan."),
            ("Nyatakan satu sebab atau kesan yang perlu dibuktikan daripada bahan sejarah.","Terima sebab/kesan yang menepati topik dan SP."),
            ("Tulis kesimpulan ringkas yang mesti disokong oleh bukti.","Terima kesimpulan relevan yang disokong maklumat.")
        ]
    else: # Pendidikan Islam
        stim=_ws_fill_template(_ws_stimulus_pick('Pendidikan Islam','daily_scenario',seed),state,seed)
        student += ['SITUASI',stim,f"Fokus pembelajaran: {sp}"]
        if recipe=='pi_quran':
            student += ['ARAHAN KHUSUS','Gunakan bacaan/ayat dan hukum yang telah dipelajari bagi fokus SP untuk menjawab tugasan. Jangan meneka teks ayat yang tidak diberikan.']
        elif recipe=='pi_ibadah':
            student += ['ARAHAN KHUSUS','Susun amalan atau langkah dengan tertib dan jelaskan tujuan setiap langkah berdasarkan pembelajaran.']
        elif recipe=='pi_sirah':
            student += ['ARAHAN KHUSUS','Kenal pasti tokoh/peristiwa/pengajaran yang benar-benar dinyatakan dalam fokus pembelajaran dan susun maklumat dengan teratur.']
        qs=[
            ("Nyatakan tajuk pembelajaran.",topic),
            ("Nyatakan satu istilah penting daripada fokus SP.","Terima istilah tepat daripada SP."),
            ("Berikan satu contoh yang berkaitan dengan fokus pembelajaran.","Terima contoh tepat berdasarkan pembelajaran."),
            ("Apakah tindakan yang wajar dalam situasi yang diberi?","Terima tindakan yang selaras dengan fokus SP."),
            ("Berikan sebab bagi tindakan tersebut.","Terima sebab yang tepat berdasarkan nilai/adab/ibadah yang dipelajari."),
            ("Nyatakan satu pengajaran yang boleh diamalkan.","Terima pengajaran yang selaras dengan SP."),
            ("Bagaimanakah amalan itu boleh dilaksanakan secara konsisten?","Terima cadangan praktikal dan sesuai."),
            ("Hubungkan situasi harian dengan fokus pembelajaran.","Terima huraian relevan yang tidak bercanggah dengan SP.")
        ]
    for i in range(qcount):
        q,a=qs[i%len(qs)]; student.append(f"{i+1}. {q} [ANSWERBOX: {2 if level<3 else 3}]"); ans.append(f"{i+1}. {a}")
    student += ['SKEMA JAWAPAN:']+ans
    return '\n'.join(student)

def _worksheet_quality_layer_audit():
    con=_db()
    out={}
    out['sp_layers']=con.execute("SELECT COUNT(*) FROM worksheet_sp_quality_layer WHERE verified=1").fetchone()[0]
    out['visuals']=dict(con.execute("SELECT visual_family,COUNT(*) FROM worksheet_visual_bank WHERE verified=1 GROUP BY visual_family").fetchall())
    out['stimuli']=dict((str(a)+'|'+str(b),int(c)) for a,b,c in con.execute("SELECT subject,stimulus_family,COUNT(*) FROM worksheet_stimulus_bank WHERE verified=1 GROUP BY subject,stimulus_family").fetchall())
    out['contexts']=dict(con.execute("SELECT category,COUNT(*) FROM worksheet_context_bank WHERE verified=1 GROUP BY category").fetchall())
    con.close()
    return out



# ============================================================
# v22.90 WORKSHEET >9.5 QUALITY PASS
# Action-driven SP tasks, richer context, stronger visual use.
# DATABASE/LOCAL ONLY.
# ============================================================
APP_VERSION = 'v22.90-WORKSHEET-QUALITY-95'

def _ws_action_family(state):
    try:
        con=_db()
        row=con.execute("""SELECT a.action_family FROM worksheet_sp_action_map a
            JOIN curriculum_standards cs ON cs.id=a.curriculum_standard_id
            WHERE a.verified=1 AND cs.verified=1 AND cs.year_label=? AND cs.subject=? AND cs.sp_code=?
            ORDER BY cs.id LIMIT 1""",
            (str(state.get('year') or ''),str(state.get('subject') or ''),str(state.get('sp_code') or ''))).fetchone()
        con.close()
        return str(row[0]) if row else ''
    except Exception:
        return ''

def _ws_action_task(state, level):
    fam=_ws_action_family(state)
    if not fam: return None
    try:
        con=_db()
        row=con.execute("""SELECT task_template,answer_rule FROM worksheet_action_task_bank
            WHERE verified=1 AND subject=? AND action_family=? AND level=? ORDER BY id LIMIT 1""",
            (str(state.get('subject') or ''),fam,int(level))).fetchone()
        con.close()
        if not row: return None
        topic=str(state.get('topic') or 'topik pembelajaran')
        return (str(row[0]).format(topic=topic),str(row[1]).format(topic=topic))
    except Exception:
        return None

def _ws_focus_line(state):
    topic=str(state.get('topic') or '').strip()
    sp=str(state.get('sp_text') or '').strip()
    if topic and sp: return f"Fokus: {topic} — {sp}"
    return f"Fokus: {topic or sp}"

def _ws_known_person_names(limit=1000):
    try:
        con=_db(); rows=con.execute("SELECT value FROM worksheet_context_bank WHERE verified=1 AND category='person_name' ORDER BY id LIMIT ?",(int(limit),)).fetchall(); con.close()
        return [str(r[0]) for r in rows]
    except Exception: return []

# Keep the v22.89 generators as bases.
_db_ws_math_generic_v2289=_db_ws_math_generic
_db_ws_language_generic_v2289=_db_ws_language_generic
_db_ws_other_generic_v2289=_db_ws_other_generic

# Mathematics: preserve deterministic arithmetic, but enforce SP focus + usable representation.
def _db_ws_math_generic(state, level, qcount, rng, recipe):
    text=_db_ws_math_generic_v2289(state,level,qcount,rng,recipe)
    lines=text.splitlines()
    # Put exact SP focus near the top so the worksheet remains explicitly aligned.
    pos=1 if lines else 0
    lines.insert(pos,_ws_focus_line(state))
    # Ensure each math family has at least one meaningful representation.
    body='\n'.join(lines)
    if not re.search(r'\[(?:VISUAL|FRACTION_|TABLE|FORM_LAZIM)',body,re.I):
        if recipe=='math_geometry':
            lines.insert(pos+1,'Rajah rujukan: [VISUAL: segi empat, 1]')
        elif recipe=='math_data':
            lines.insert(pos+1,'Gunakan jadual data berikut untuk menyusun maklumat. [TABLE: 5, 2]')
        elif recipe in ('math_number','math_money'):
            lines.insert(pos+1,'Gunakan model kuantiti berikut sebagai sokongan jika perlu. [VISUAL: syiling, 5]')
        elif recipe in ('math_operation','math_generic'):
            lines.insert(pos+1,'Gunakan ruang bentuk lazim untuk menunjukkan jalan kerja. [FORM_LAZIM: 4, 4]')
        elif recipe=='math_measure':
            lines.insert(pos+1,'Rekod ukuran dan penukaran unit dalam jadual. [TABLE: 3, 3]')
        elif recipe=='math_time':
            lines.insert(pos+1,'Susun masa mula, tempoh dan masa tamat dalam jadual. [TABLE: 3, 3]')
        elif recipe=='math_ratio':
            lines.insert(pos+1,'Bandingkan dua kuantiti menggunakan jadual nisbah. [TABLE: 3, 3]')
        elif recipe=='math_algebra':
            lines.insert(pos+1,'Gunakan jadual nilai diketahui dan nilai tidak diketahui. [TABLE: 3, 2]')
        elif recipe=='math_percent':
            lines.insert(pos+1,'Gunakan jadual nilai asal, peratus dan nilai bahagian. [TABLE: 3, 3]')
    return '\n'.join(lines)

# Languages: use exact SP action + varied Malaysian characters + topic-specific stimuli.
def _db_ws_language_generic(state, level, qcount, rng, recipe):
    subject=str(state.get('subject') or '')
    topic=str(state.get('topic') or 'topik pembelajaran')
    sp=str(state.get('sp_text') or '')
    seed=f"{state.get('variation_seed','')}|{state.get('year','')}|{state.get('sp_code','')}|L{level}|v2290"
    c=_ws_context_for(state,seed); p1,p2=c['person'],c['person2']
    student=_db_ws_pack_header(state,level); ans=[]
    student += [_ws_focus_line(state)]
    action=_ws_action_task(state,level)

    if subject=='Bahasa Inggeris':
        if recipe=='en_listening':
            script=(f"Teacher script: {p1} and {p2} are learning about {topic}. First, they listen for the main idea. "
                    f"Next, they identify details that match this learning focus: {sp}. Then, they check the sequence and meaning before responding.")
            student += ['TEACHER SCRIPT',script]
        elif recipe=='en_speaking':
            student += ['SPEAKING CONTEXT',f"{p1} and {p2} are discussing {topic}. Use the Learning Standard focus when giving and responding to spoken information."]
        elif recipe=='en_writing':
            student += ['WRITING CONTEXT',f"Write for a real classroom purpose related to {topic}. Audience: {p2}. Focus: {sp}"]
        else:
            tpl=_ws_stimulus_pick(subject,'context_passage',seed)
            passage=_ws_fill_template(tpl,state,seed)
            passage += f" The activity focuses specifically on {topic}. The pupils use language needed to meet this Learning Standard: {sp}."
            student += ['TEXT',passage]
        base=[
            (f"What is the main focus of the activity?",topic+'.'),
            (f"State one detail involving {p1} or {p2}.","Accept an accurate detail from the stimulus."),
            ("Which information is most important for completing the task?","Accept a relevant detail linked to the Learning Standard."),
            ("Give one reason why checking meaning or sequence is useful.","It improves accuracy and understanding; accept an equivalent answer."),
        ]
        for i in range(qcount):
            if i>=4 and action:
                q,a=action
                # vary cognitive cue without changing the LS-aligned core
                cue=['Use evidence from the stimulus.','Relate your answer to the Learning Standard.','Give a clear example.','Justify your response.'][i%4]
                q=f"{q} {cue}"
            else: q,a=base[i%len(base)]
            box=2 if level<=2 else 4
            student.append(f"{i+1}. {q} [ANSWERBOX: {box}]"); ans.append(f"{i+1}. {a}")
        student += ['ANSWER SCHEME:']+ans
        return '\n'.join(student)

    # Bahasa Melayu
    if recipe=='bm_literature':
        texts=[
            f"Ilmu dicari setiap hari,\n{topic} dipelajari penuh tekun,\nBahasa santun menghias diri,\nBudi dan usaha hidup tersusun.",
            f"Pagi cerah melangkah maju,\nBelajar {topic} bersama rakan,\nIdea disusun, bahasa dipadu,\nIlmu diamal jadi pedoman."
        ]
        student += ['TEKS',texts[_ws_stable_index(seed,len(texts))]]
    elif recipe=='bm_oral':
        student += ['KONTEKS LISAN',f"{p1} dan {p2} berbincang tentang {topic}. Gunakan tindakan bahasa yang dinyatakan dalam SP: {sp}"]
    elif recipe=='bm_writing':
        student += ['KONTEKS MENULIS',f"Tulis untuk tujuan sebenar berkaitan {topic}. Sasaran pembaca: {p2}. Fokus SP: {sp}"]
    else:
        tpl=_ws_stimulus_pick(subject,'context_passage',seed)
        petikan=_ws_fill_template(tpl,state,seed)
        petikan += f" Aktiviti itu berfokus pada {topic}. Murid perlu menggunakan kemahiran yang dinyatakan dalam SP berikut: {sp}."
        student += ['PETIKAN',petikan]
    base=[
        ("Apakah fokus utama aktiviti atau petikan?",topic+'.'),
        (f"Nyatakan satu maklumat yang berkaitan dengan {p1} atau {p2}.","Terima maklumat tepat daripada stimulus."),
        ("Nyatakan satu isi penting yang membantu murid melaksanakan tugasan.","Terima isi relevan berdasarkan stimulus dan SP."),
        ("Mengapakah semakan atau penyusunan idea penting?","Untuk memastikan maklumat tepat, jelas dan tersusun; terima jawapan setara."),
    ]
    for i in range(qcount):
        if i>=4 and action:
            q,a=action
            cue=['Gunakan bukti daripada bahan.','Kaitkan jawapan dengan SP.','Berikan satu contoh yang jelas.','Berikan alasan yang munasabah.'][i%4]
            q=f"{q} {cue}"
        else: q,a=base[i%len(base)]
        student.append(f"{i+1}. {q} [ANSWERBOX: {2 if level<=2 else 4}]"); ans.append(f"{i+1}. {a}")
    student += ['SKEMA JAWAPAN:']+ans
    return '\n'.join(student)

# Science/History/PI: exact SP action progression and explicit evidence discipline.
def _db_ws_other_generic(state, level, qcount, rng, recipe):
    subject=str(state.get('subject') or '')
    topic=str(state.get('topic') or '')
    sp=str(state.get('sp_text') or '')
    seed=f"{state.get('variation_seed','')}|{state.get('year','')}|{state.get('sp_code','')}|L{level}|v2290"
    c=_ws_context_for(state,seed); student=_db_ws_pack_header(state,level); ans=[]
    student += [_ws_focus_line(state)]
    action=_ws_action_task(state,level)
    if subject=='Sains':
        vals=[rng.randint(2,6)]
        for _ in range(3): vals.append(vals[-1]+rng.randint(1,4))
        stim=_ws_fill_template(_ws_stimulus_pick('Sains','investigation',seed),state,seed)
        student += ['STIMULUS',stim,f"Data: A={vals[0]}, B={vals[1]}, C={vals[2]}, D={vals[3]}. [TABLE: 5, 2]"]
        base=[
            ("Nyatakan satu pemerhatian daripada data.",f"Data meningkat daripada {vals[0]} kepada {vals[-1]} / pemerhatian setara."),
            ("Apakah pola perubahan data?","Meningkat."),
            ("Hitung beza bacaan tertinggi dengan bacaan terendah.",str(max(vals)-min(vals))),
            ("Nyatakan satu perkara yang perlu dikawal supaya perbandingan adil.","Terima pemboleh ubah dimalarkan yang relevan dengan topik."),
        ]
    elif subject=='Sejarah':
        stim=_ws_fill_template(_ws_stimulus_pick('Sejarah','source_inquiry',seed),state,seed)
        student += ['KAD SUMBER',stim,f"Fokus SP: {sp}"]
        if recipe=='hist_timeline': student += ['GARIS MASA','Susun bukti atau maklumat mengikut urutan. [TABLE: 4, 2]']
        else: student += ['CATATAN BUKTI','Rekod fakta, bukti dan kesimpulan secara berasingan. [TABLE: 4, 3]']
        base=[
            ("Apakah topik yang dikaji?",topic+'.'),
            ("Nyatakan satu kata kunci daripada fokus SP.","Terima kata kunci tepat daripada SP."),
            ("Apakah jenis bukti yang perlu dirujuk sebelum membuat kesimpulan?","Sumber/fakta yang relevan dan boleh disokong."),
            ("Mengapakah bukti perlu dipisahkan daripada pendapat?","Supaya kesimpulan sejarah berasaskan sumber dan tidak sekadar andaian."),
        ]
    else:
        stim=_ws_fill_template(_ws_stimulus_pick('Pendidikan Islam','daily_scenario',seed),state,seed)
        student += ['SITUASI',stim,f"Fokus SP: {sp}"]
        if recipe=='pi_quran': student += ['NOTA TUGASAN','Gunakan teks/contoh yang telah diajar oleh guru; jangan meneka ayat atau hukum yang tidak diberikan.']
        student += ['PETA AMALAN','Rekod konsep, contoh dan tindakan yang sesuai. [TABLE: 4, 3]']
        base=[
            ("Apakah tajuk pembelajaran?",topic+'.'),
            ("Nyatakan satu istilah penting daripada fokus SP.","Terima istilah tepat daripada SP."),
            ("Berikan satu contoh situasi yang benar-benar berkaitan dengan fokus tersebut.","Terima contoh yang tepat dan sesuai."),
            ("Apakah tindakan yang wajar dalam situasi itu?","Terima tindakan yang selaras dengan pembelajaran."),
        ]
    for i in range(qcount):
        if i>=4 and action:
            q,a=action
            q += ' Gunakan maklumat daripada stimulus/fokus SP sebagai asas jawapan.'
        else: q,a=base[i%len(base)]
        student.append(f"{i+1}. {q} [ANSWERBOX: {2 if level<=2 else 4}]"); ans.append(f"{i+1}. {a}")
    student += ['SKEMA JAWAPAN:']+ans
    return '\n'.join(student)



