# ============================================================
# v22.90 WORKSHEET >9.5 QUALITY REPAIR
# Action-driven, SP-explicit, deterministic, database-only.
# ============================================================
APP_VERSION = 'v22.90-WORKSHEET-QUALITY-95'

def _ws_action_family(state):
    try:
        con=_db()
        row=con.execute("""SELECT a.action_family
            FROM worksheet_sp_action_map a
            JOIN curriculum_standards cs ON cs.id=a.curriculum_standard_id
            WHERE a.verified=1 AND cs.verified=1
              AND cs.year_label=? AND cs.subject=? AND cs.sp_code=?
            ORDER BY cs.id LIMIT 1""",
            (str(state.get('year') or ''),str(state.get('subject') or ''),str(state.get('sp_code') or ''))).fetchone()
        con.close()
        return str(row[0]) if row else ''
    except Exception:
        return ''

def _ws_action_task(state, level, seed=''):
    fam=_ws_action_family(state)
    subj=str(state.get('subject') or '')
    try:
        con=_db()
        rows=con.execute("""SELECT task_template,answer_rule
            FROM worksheet_action_task_bank
            WHERE verified=1 AND subject=? AND action_family=? AND level=?
            ORDER BY id""",(subj,fam,int(level))).fetchall()
        con.close()
        if not rows: return ('','',fam)
        row=rows[_ws_stable_index(str(seed)+'|action-task',len(rows))]
        topic=str(state.get('topic') or 'topik pembelajaran')
        task=str(row[0]).format(topic=topic)
        ans=str(row[1]).format(topic=topic)
        return task,ans,fam
    except Exception:
        return ('','',fam)

def _ws_sp_focus_line(state):
    spc=str(state.get('sp_code') or '').strip()
    spt=str(state.get('sp_text') or '').strip()
    return f"Fokus SP {spc}: {spt}" if spc else f"Fokus pembelajaran: {spt}"

def _ws_year_band(state):
    y=str(state.get('year') or '').lower()
    m=re.search(r'(\d+)',y)
    n=int(m.group(1)) if m else 1
    if 'tingkatan' in y: return 'secondary',n
    return ('lower_primary' if n<=3 else 'upper_primary'),n

def _ws_level_instruction(level, subject):
    if level==1:
        return "Aras 1 — Kenal pasti / faham konsep asas dengan bukti terus daripada stimulus."
    if level==2:
        return "Aras 2 — Aplikasi terus dalam konteks baharu yang hampir dengan pembelajaran."
    if level==3:
        return "Aras 3 — Analisis, banding, hubung kait atau terangkan alasan."
    return "Aras 4 — Penaakulan/KBAT: nilai, justifikasi, cipta atau selesaikan situasi baharu."

# ---------- MATEMATIK: recipe-specific, contextual, visual where useful ----------
_db_ws_math_generic_v2289=_db_ws_math_generic
def _db_ws_math_generic(state, level, qcount, rng, recipe):
    student=_db_ws_pack_header(state,level); ans=[]
    topic=str(state.get('topic') or 'Matematik')
    sp=str(state.get('sp_text') or '')
    seed=f"{state.get('variation_seed','')}|{state.get('year','')}|{state.get('sp_code','')}|L{level}"
    ctx=_ws_context_for(state,seed)
    name=ctx.get('person') or 'Aiman'; name2=ctx.get('person2') or 'Mei Ling'
    obj=ctx.get('object') or 'buku'; place=ctx.get('place') or 'sekolah'
    unit=ctx.get('unit') or 'buah'; food=ctx.get('food') or 'roti'
    student += ['FOKUS PEMBELAJARAN',_ws_sp_focus_line(state),_ws_level_instruction(level,'Matematik')]
    for i in range(1,qcount+1):
        qseed=f"{seed}|Q{i}"
        if recipe=='math_fraction':
            den=rng.choice([4,5,6,8,10,12])
            n1=rng.randint(1,den-1); n2=rng.randint(1,den-1)
            if level==1:
                student.append(f"{i}. Perhatikan rajah pecahan bagi topik {topic}: [FRACTION_BAR: {n1}, {den}] Nyatakan pecahan berlorek. [ANSWERSPACE: 2]")
                ans.append(f"{i}. {n1}/{den}.")
            elif level==2:
                student.append(f"{i}. Bandingkan [FRACTION_BAR: {n1}, {den}] dengan {n2}/{den}. Gunakan >, < atau = dan beri satu sebab ringkas. [ANSWERSPACE: 3]")
                sym='>' if n1>n2 else '<' if n1<n2 else '='
                ans.append(f"{i}. {n1}/{den} {sym} {n2}/{den}; penyebut sama, bandingkan pengangka.")
            elif level==3:
                total=n1+n2; g=math.gcd(total,den)
                student.append(f"{i}. {name} menggunakan {n1}/{den} m reben dan {name2} menggunakan {n2}/{den} m. Hitung jumlah dan ringkaskan pecahan. [ANSWERSPACE: 4]")
                ans.append(f"{i}. {total}/{den} = {total//g}/{den//g} m.")
            else:
                a=max(n1,n2); b=min(n1,n2)
                student.append(f"{i}. Dua murid memberi jawapan {a}/{den} dan {b}/{den} bagi situasi {topic}. Tentukan jawapan yang lebih besar dan buktikan menggunakan perbandingan pecahan. [ANSWERSPACE: 5]")
                ans.append(f"{i}. {a}/{den} lebih besar kerana penyebut sama dan {a}>{b}.")
        elif recipe=='math_percent':
            base=rng.choice([40,50,80,100,120,200]); pct=rng.choice([10,20,25,50,75]); val=base*pct//100
            if level<=2:
                student.append(f"{i}. Dalam konteks {topic}, {pct}% daripada {base} {unit} {obj} dipilih. Hitung bilangannya. [ANSWERSPACE: 3]")
                ans.append(f"{i}. {pct}/100 × {base} = {val}.")
            else:
                student.append(f"{i}. {name} berkata {val} daripada {base} bersamaan {pct}%. Semak dakwaan itu dengan pengiraan dan jelaskan. [ANSWERSPACE: 4]")
                ans.append(f"{i}. Betul; {val}/{base}×100% = {pct}%.")
        elif recipe=='math_ratio':
            a=rng.randint(2,9); b=rng.randint(2,9); k=rng.randint(2,5)
            if level<=2:
                student.append(f"{i}. Dalam aktiviti {topic}, nisbah {obj} {name}:{name2} ialah {a}:{b}. Jika kedua-dua kuantiti didarab {k}, tulis nisbah baharu. [ANSWERSPACE: 3]")
                ans.append(f"{i}. {a*k}:{b*k}.")
            else:
                student.append(f"{i}. {name} mendakwa {a*k}:{b*k} tidak setara dengan {a}:{b}. Nilai dakwaan itu dan buktikan dengan pemudahan nisbah. [ANSWERSPACE: 4]")
                ans.append(f"{i}. Dakwaan salah; {a*k}:{b*k} ÷{k} = {a}:{b}.")
        elif recipe=='math_time':
            h=rng.randint(7,17); m=rng.choice([0,15,30,45]); dur=rng.choice([30,45,60,75,90])
            total=h*60+m+dur; hh=(total//60)%24; mm=total%60
            if level<=2:
                student.append(f"{i}. Aktiviti berkaitan {topic} bermula {h:02d}:{m:02d} dan berlangsung {dur} minit. [CLOCK: {h}, {m}] Tentukan waktu tamat. [TABLE: 3, 2] [ANSWERSPACE: 3]")
                ans.append(f"{i}. {hh:02d}:{mm:02d}.")
            else:
                student.append(f"{i}. Jadual menunjukkan mula {h:02d}:{m:02d} dan tempoh {dur} minit. [CLOCK: {h}, {m}] Buktikan sama ada waktu tamat {hh:02d}:{mm:02d} adalah betul. [TABLE: 3, 2] [ANSWERSPACE: 4]")
                ans.append(f"{i}. Betul; {h:02d}:{m:02d}+{dur} minit = {hh:02d}:{mm:02d}.")
        elif recipe=='math_money':
            p=rng.randint(4,80); qty=rng.randint(2,5); total=p*qty; pay=((total+9)//10)*10
            if level==1:
                student.append(f"{i}. {name} membeli {obj} berharga RM{p}.00 dan membayar RM{pay}.00. [PRICE_TAG: {p}] Hitung baki. [ANSWERSPACE: 3]")
                ans.append(f"{i}. RM{pay-p}.00.")
            elif level==2:
                student.append(f"{i}. {name} membeli {qty} {obj} pada RM{p}.00 setiap satu. [PRICE_TAG: {p}] Hitung jumlah harga. [ANSWERSPACE: 3]")
                ans.append(f"{i}. {qty}×RM{p}.00 = RM{total}.00.")
            else:
                student.append(f"{i}. {name} mempunyai RM{pay}.00 dan mahu membeli {qty} {obj} pada RM{p}.00 setiap satu. [PRICE_TAG: {p}] Tentukan sama ada wang mencukupi dan kira baki/kurangan. [ANSWERSPACE: 4]")
                diff=pay-total
                ans.append(f"{i}. {'Cukup' if diff>=0 else 'Tidak cukup'}; {'baki' if diff>=0 else 'kurangan'} RM{abs(diff)}.00.")
        elif recipe=='math_measure':
            cm=rng.randint(120,950); material=_ws_context_pick('material',qseed) or 'reben'
            if level==1:
                student.append(f"{i}. Panjang {material} ialah {cm} cm. [RULER: 0, 10, 1] Tukarkan kepada m dan cm. [ANSWERSPACE: 3]")
                ans.append(f"{i}. {cm//100} m {cm%100} cm.")
            elif level==2:
                add=rng.randint(20,90)
                student.append(f"{i}. {name} mempunyai {cm} cm {material} dan menambah {add} cm. Berapakah jumlah dalam cm? [ANSWERSPACE: 3]")
                ans.append(f"{i}. {cm+add} cm.")
            else:
                student.append(f"{i}. Dua ukuran bagi {topic} ialah {cm} cm dan {cm//2} cm. Cari beza dan terangkan unit yang sesuai digunakan. [ANSWERSPACE: 4]")
                ans.append(f"{i}. {cm-cm//2} cm; sentimeter sesuai untuk ukuran ini.")
        elif recipe=='math_data':
            vals=[rng.randint(2,15) for _ in range(4)]
            labels=["A","B","C","D"]
            pairs=", ".join(f"{labels[j]}={vals[j]}" for j in range(4))
            student.append(f"{i}. Data bagi {topic}: {pairs}. [BAR_CHART: A={vals[0]}|B={vals[1]}|C={vals[2]}|D={vals[3]}] [TABLE: 5, 2] "
                           + ("Nyatakan nilai tertinggi dan terendah." if level==1 else
                              "Hitung jumlah dan julat data." if level==2 else
                              "Bandingkan data dan terangkan satu pola yang munasabah." if level==3 else
                              "Nilai satu kesimpulan berdasarkan data dan nyatakan bukti.")
                           + " [ANSWERSPACE: 4]")
            if level==1: ans.append(f"{i}. Tertinggi {max(vals)}; terendah {min(vals)}.")
            elif level==2: ans.append(f"{i}. Jumlah {sum(vals)}; julat {max(vals)-min(vals)}.")
            elif level==3: ans.append(f"{i}. Terima pola yang tepat dan disokong data.")
            else: ans.append(f"{i}. Terima penilaian yang menggunakan sekurang-kurangnya satu nilai data sebagai bukti.")
        elif recipe=='math_geometry':
            l=rng.randint(4,15); w=rng.randint(3,12)
            visual=f"[VISUAL: segi empat, {rng.randint(2,6)}]"
            if level==1:
                student.append(f"{i}. Dalam topik {topic}, perhatikan bentuk berikut: [GEOMETRY: rectangle, {l}, {w}] Kenal pasti bentuk utama. [ANSWERSPACE: 2]")
                ans.append(f"{i}. Segi empat.")
            elif level==2:
                student.append(f"{i}. Sebuah segi empat tepat panjang {l} cm dan lebar {w} cm. [GEOMETRY: rectangle, {l}, {w}] Hitung perimeter. [ANSWERSPACE: 3]")
                ans.append(f"{i}. 2({l}+{w}) = {2*(l+w)} cm.")
            elif level==3:
                student.append(f"{i}. Sebuah segi empat tepat panjang {l} cm dan lebar {w} cm. [GEOMETRY: rectangle, {l}, {w}] Bandingkan perimeter dengan luasnya dan nyatakan kedua-dua nilai. [ANSWERSPACE: 4]")
                ans.append(f"{i}. Perimeter={2*(l+w)} cm; luas={l*w} cm².")
            else:
                student.append(f"{i}. {name} mendakwa semua segi empat tepat dengan perimeter {2*(l+w)} cm mempunyai luas {l*w} cm². Nilai dakwaan itu dengan satu contoh balas. [ANSWERSPACE: 5]")
                ans.append(f"{i}. Salah; perimeter sama boleh datang daripada pasangan panjang/lebar berbeza dan luas berbeza.")
        elif recipe=='math_algebra':
            x=rng.randint(2,20); a=rng.randint(2,9); total=x+a
            if level<=2:
                student.append(f"{i}. Dalam konteks {topic}, selesaikan x + {a} = {total}. [ANSWERSPACE: 3]")
                ans.append(f"{i}. x={x}.")
            else:
                student.append(f"{i}. {name} berkata x={x+1} bagi x+{a}={total}. Semak jawapan dengan penggantian dan betulkan jika perlu. [ANSWERSPACE: 4]")
                ans.append(f"{i}. Salah; {x+1}+{a}={x+1+a}≠{total}; x={x}.")
        elif recipe=='math_number':
            n=rng.randint(100,9999); digit=str(n)[0]; val=int(digit)*(10**(len(str(n))-1))
            if level<=2:
                student.append(f"{i}. Bagi nombor {n} dalam topik {topic}, nyatakan nilai digit {digit}. [ANSWERSPACE: 2]")
                ans.append(f"{i}. {val}.")
            else:
                student.append(f"{i}. Jelaskan perbezaan antara digit {digit} dan nilai digitnya dalam nombor {n}. [ANSWERSPACE: 4]")
                ans.append(f"{i}. Digit ialah {digit}; nilai digit ialah {val}.")
        elif recipe=='math_operation':
            a=rng.randint(20,180); b=rng.randint(2,40)
            if level==1:
                groups=rng.randint(2,5); each=rng.randint(2,5)
                vis=f"[VISUAL_GROUPS: {rng.choice(['epal','bola','bintang','bunga','pensel','buku'])}, {groups}, {each}]"
                student.append(f"{i}. Berdasarkan visual {topic}, kira jumlah objek dalam kumpulan sama banyak. {vis} [ANSWERSPACE: 2]")
                ans.append(f"{i}. {groups}×{each}={groups*each}.")
            elif level==2:
                student.append(f"{i}. Hitung {a}+{b} dalam bentuk lazim. [FORM_LAZIM: 3, 4]")
                ans.append(f"{i}. {a+b}.")
            elif level==3:
                c2=rng.randint(5,30)
                student.append(f"{i}. {name} mempunyai {a} {unit} {obj}, menerima {b} lagi dan menggunakan {c2}. Hitung baki. [ANSWERSPACE: 4]")
                ans.append(f"{i}. {a}+{b}−{c2}={a+b-c2}.")
            else:
                wrong=a+b+1
                student.append(f"{i}. {name2} menyatakan {a}+{b}={wrong}. Kenal pasti kesalahan dan berikan jawapan betul dengan jalan kerja. [FORM_LAZIM: 3, 4] [ANSWERSPACE: 4]")
                ans.append(f"{i}. Salah; jawapan betul {a+b}.")
        else:
            a=rng.randint(20,300); b=rng.randint(2,40)
            if level<=2:
                student.append(f"{i}. Dalam topik {topic}, hitung {a}+{b}. [FORM_LAZIM: 3, 4]")
                ans.append(f"{i}. {a+b}.")
            else:
                c2=rng.randint(5,40)
                student.append(f"{i}. {name} mempunyai {a} {unit} {obj}, menambah {b} dan menggunakan {c2}. Selesaikan dan jelaskan operasi yang digunakan. [ANSWERSPACE: 4]")
                ans.append(f"{i}. {a}+{b}−{c2}={a+b-c2}; tambah kemudian tolak.")
    student += ['SKEMA JAWAPAN:']+ans
    return '\n'.join(student)

# ---------- LANGUAGE: exact SP + action-driven progression ----------
_db_ws_language_generic_v2289=_db_ws_language_generic
def _db_ws_language_generic(state, level, qcount, rng, recipe):
    subject=str(state.get('subject') or '')
    topic=str(state.get('topic') or 'topik pembelajaran')
    sp=str(state.get('sp_text') or '')
    seed=f"{state.get('variation_seed','')}|{state.get('year','')}|{state.get('sp_code','')}|L{level}"
