# v22.90 final standalone scale generator (no alias dependency).
def _db_ws_math_scale(state, level, qcount, rng):
    student=_db_ws_pack_header(state,level)
    topic=str(state.get('topic') or 'Lukisan Berskala')
    student += ['FOKUS STANDARD PEMBELAJARAN',_ws_sp_focus_line(state),
                _ws_level_instruction(level,'Matematik'),
                'Organiser ukuran sebenar ↔ lukisan: [TABLE: 3, 3]']
    ans=[]
    for i in range(1,qcount+1):
        f=rng.choice([2,3,4,5])
        dw=rng.choice([2,3,4,5,6,8,10])
        dh=rng.choice([2,3,4,5,6])
        aw=dw*f; ah=dh*f
        if level==1:
            student.append(
                f"{i}. Objek sebenar berukuran {aw} cm × {ah} cm. Lukisan berukuran {dw} cm × {dh} cm. "
                f"Adakah lukisan itu pengecilan, pembesaran atau saiz sebenar? [ANSWERSPACE: 3]")
            ans.append(f"{i}. Pengecilan; kedua-dua sisi dibahagi {f}.")
        elif level==2:
            student.append(
                f"{i}. Bagi {topic}, objek sebenar {aw} cm × {ah} cm dan lukisan {dw} cm × {dh} cm. "
                f"Tentukan nisbah lukisan : sebenar bagi kedua-dua sisi. [ANSWERSPACE: 4]")
            ans.append(f"{i}. {dw}:{aw} = {dh}:{ah} = 1:{f}.")
        elif level==3:
            wrong=dh+rng.choice([1,2])
            student.append(
                f"{i}. Dua cadangan lukisan untuk objek {aw} cm × {ah} cm ialah A: {dw} cm × {dh} cm dan "
                f"B: {dw} cm × {wrong} cm. Pilih lukisan berskala dan buktikan dengan nisbah. [ANSWERSPACE: 5]")
            ans.append(f"{i}. A; {dw}/{aw} = {dh}/{ah} = 1/{f}. B tidak mempunyai faktor yang sama.")
        else:
            wrong=dh+rng.choice([1,2])
            student.append(
                f"{i}. Seorang murid berkata, 'Semua lukisan yang lebih kecil ialah lukisan berskala.' "
                f"Nilai kenyataan itu menggunakan objek {aw} cm × {ah} cm dan lukisan {dw} cm × {wrong} cm. "
                f"Berikan justifikasi matematik. [ANSWERSPACE: 5]")
            ans.append(f"{i}. Salah; lukisan berskala mesti mengekalkan faktor yang sama pada semua ukuran. "
                       f"{dw}/{aw}=1/{f}, tetapi {wrong}/{ah} tidak sama.")
    student += ['SKEMA JAWAPAN:']+ans
    return '\n'.join(student)


# v22.90 final uniqueness gate: regenerate locally if an 8-item worksheet
# accidentally repeats an exact question stem. No AI/API is called.
def _worksheet_exact_question_duplicates(text, qcount=8):
    qs=[m.group(1).strip() for m in re.finditer(r'(?m)^\d+\.\s*(.+)$',str(text or ''))]
    stems=[re.sub(r'\s+',' ',re.sub(r'\[[^\]]+\]','',q)).strip().lower() for q in qs[:int(qcount)]]
    return len(stems) < int(qcount) or len(stems) != len(set(stems))

def _db_first_generate_one_level(state, level, qcount):
    row=_db_ws_recipe(state,level)
    if not row:
        raise RuntimeError(f"Tiada recipe DB untuk {state.get('year')} {state.get('subject')} SP {state.get('sp_code')} aras {level}")
    recipe=str(row['recipe_key'])
    # Try several deterministic local seeds until exact repeated stems disappear.
    last=''
    for attempt in range(12):
        seed=(f"{state.get('variation_seed','')}-{state.get('year','')}-"
              f"{state.get('subject','')}-{state.get('sp_code','')}-{level}-u{attempt}")
        rng=random.Random(seed)
        if recipe=='math_scale':
            text=_db_ws_math_scale(state,level,qcount,rng)
        elif recipe.startswith('math_'):
            text=_db_ws_math_generic(state,level,qcount,rng,recipe)
        elif recipe.startswith('bm_') or recipe.startswith('en_'):
            text=_db_ws_language_generic(state,level,qcount,rng,recipe)
        else:
            text=_db_ws_other_generic(state,level,qcount,rng,recipe)
        last=text
        if not _worksheet_exact_question_duplicates(text,qcount):
            return text
    # Deterministic final safeguard: make repeated stem contexts visibly distinct
    # without changing mathematical values or answer numbering.
    lines=last.splitlines()
    seen={}
    out=[]
    for line in lines:
        m=re.match(r'^(\d+)\.\s*(.+)$',line)
        if not m:
            out.append(line); continue
        key=re.sub(r'\s+',' ',re.sub(r'\[[^\]]+\]','',m.group(2))).strip().lower()
        seen[key]=seen.get(key,0)+1
        if seen[key]>1:
            line=f"{m.group(1)}. Situasi {m.group(1)} — {m.group(2)}"
        out.append(line)
    return '\n'.join(out)


# v22.90 final alignment gate: every Mathematics level explicitly carries
# the selected curriculum topic as well as the exact SP.
_db_first_generate_one_level_v2290_unique=_db_first_generate_one_level
def _db_first_generate_one_level(state, level, qcount):
    text=_db_first_generate_one_level_v2290_unique(state,level,qcount)
    if str(state.get('subject') or '')=='Matematik':
        topic=str(state.get('topic') or '').strip()
        if topic and topic.casefold() not in str(text).casefold():
            lines=str(text).splitlines()
            lines.insert(1,f"TAJUK / KONTEKS MATEMATIK: {topic}")
            text='\n'.join(lines)
    return text


