# v23.31 — exact SP skill guard. Runtime remains database/local only.
_db_first_generate_one_level_pre_v2331 = _db_first_generate_one_level

def _db_first_generate_one_level(state, level, qcount):
    year=str(state.get('year') or state.get('year_label') or '').strip()
    subject=str(state.get('subject') or '').strip()
    sp_code=str(state.get('sp_code') or state.get('sp') or '').strip()
    if year=='Tahun 2' and subject=='Matematik' and sp_code=='1.1.2':
        with _db() as con:
            guard=con.execute("""SELECT * FROM worksheet_sp_skill_guard_v2331
                WHERE year_label=? AND subject=? AND sp_code=?""",(year,subject,sp_code)).fetchone()
            cur=con.execute("""SELECT topic,sk_code,sp_code,sp_text FROM curriculum_standards
                WHERE verified=1 AND year_label=? AND subject=? AND sp_code=? LIMIT 1""",
                (year,subject,sp_code)).fetchone()
        if not guard or not cur:
            raise RuntimeError('Worksheet SP skill guard missing for Tahun 2 Matematik 1.1.2')
        lo,hi=int(guard['min_value']),int(guard['max_value'])
        rng=random.Random(f"{state.get('variation_seed','')}|{year}|{subject}|{sp_code}|L{level}")
        student=_db_ws_pack_header(state,level)
        student += ['FOKUS PEMBELAJARAN',
                    f"SP {cur['sp_code']}: {cur['sp_text']}",
                    'Kemahiran: Bandingkan nilai dua nombor hingga 1000 menggunakan >, < atau =.']
        answers=[]
        used=set()
        for i in range(1,int(qcount)+1):
            while True:
                # Keep Year 2 values inside the verified topic ceiling.
                a=rng.randint(max(lo,10),hi)
                b=rng.randint(max(lo,10),hi)
                if level>=3 and rng.random()<0.18: b=a
                pair=(a,b)
                if pair not in used: used.add(pair); break
            sym='>' if a>b else '<' if a<b else '='
            if level==1:
                student.append(f"{i}. Bandingkan {a} dan {b}. Bulatkan nombor yang lebih besar. [ANSWERSPACE: 2]")
                answers.append(f"{i}. {max(a,b)}.")
            elif level==2:
                student.append(f"{i}. Isi simbol yang betul: {a} ____ {b}   (>, < atau =) [ANSWERSPACE: 2]")
                answers.append(f"{i}. {a} {sym} {b}.")
            elif level==3:
                student.append(f"{i}. Bandingkan {a} dengan {b}. Tulis simbol >, < atau = dan terangkan berdasarkan nilai nombor. [ANSWERSPACE: 3]")
                answers.append(f"{i}. {a} {sym} {b}; kerana {a} {'lebih besar daripada' if a>b else 'lebih kecil daripada' if a<b else 'sama dengan'} {b}.")
            else:
                c=min(hi,max(lo,a+rng.choice([-20,-10,10,20])))
                student.append(f"{i}. Susun {a}, {b} dan {c} daripada nilai paling kecil kepada paling besar, kemudian bandingkan dua nombor terbesar dengan simbol yang betul. [ANSWERSPACE: 4]")
                ordered=sorted([a,b,c])
                answers.append(f"{i}. {ordered[0]}, {ordered[1]}, {ordered[2]}; {ordered[2]} > {ordered[1]}.")
        student += ['SKEMA JAWAPAN:']+answers
        return '\n'.join(student)
    return _db_first_generate_one_level_pre_v2331(state,level,qcount)


# v23.36 — worksheet semantic QA. Presentation/design is intentionally untouched.
def _worksheet_semantic_guard_v2336(state, generated_text):
    year=str(state.get("year") or state.get("year_label") or "").strip()
    subject=str(state.get("subject") or "").strip()
    sp=str(state.get("sp_code") or state.get("sp") or "").strip()
    if not year or not subject or not sp:
        raise RuntimeError("Worksheet QA: year/subject/SP is incomplete")
    txt=str(generated_text or "").strip()
    if not txt:
        raise RuntimeError("Worksheet QA: empty worksheet content")
    low=txt.lower()
    # Exact guard for the defect found during beta preparation.
    if year=="Tahun 2" and subject=="Matematik" and sp=="1.1.2":
        forbidden=("nilai digit","nilai tempat")
        if any(x in low for x in forbidden):
            raise RuntimeError("Worksheet QA: unrelated skill detected for SP 1.1.2")
        nums=[int(x) for x in re.findall(r'(?<![\d.])\d{1,5}(?![\d.])',txt)]
        # Ignore numbering/metadata; any actual large value above the topic ceiling is rejected.
        if any(n>1000 for n in nums):
            raise RuntimeError("Worksheet QA: number exceeds 1000 for SP 1.1.2")
    return txt


