def _repair_rph_page_text(text, s):
    """Repair accidental concatenated textbook page strings in final RPH text."""
    selected=str(s.get('textbook_page') or s.get('page') or '').strip()
    if not selected: return text
    try:
        p=int(re.findall(r'\\d+',selected)[0])
    except: return text
    # Common adjacent-page concatenations e.g. 76+77 -> 7677, 77+78 -> 7778.
    for a,b in ((p-1,p),(p,p+1)):
        text=re.sub(rf'(?i)\\bpage\\s+{a}{b}\\b',f'pages {a}–{b}',text)
        text=re.sub(rf'(?i)\\bmuka surat\\s+{a}{b}\\b',f'muka surat {a}–{b}',text)
    return text

