# v23.02 WORKSHEET STRUCTURAL QA
# Whole worksheet pages must NOT be AI-generated images.
# AI/HQ imagery is stimulus-only; answer structure is code/DB controlled.
# ============================================================

def _worksheet_layout_rule_v2302(key, default=''):
    try:
        with _db() as con:
            row=con.execute("SELECT rule_value FROM worksheet_layout_rules WHERE rule_key=? AND verified=1",(key,)).fetchone()
        return str(row[0]) if row else default
    except Exception:
        return default

def _worksheet_validate_response_slots_v2302(items):
    """Reject a visual item group if any item lacks a response target."""
    missing=[]
    for idx,item in enumerate(items or []):
        if not isinstance(item,dict):
            missing.append(idx); continue
        has_response=bool(
            item.get('answer_lines') or item.get('answer_box') or
            item.get('workspace') or item.get('choices') or
            item.get('response_type') or item.get('answer_slot')
        )
        if not has_response:
            missing.append(idx)
    if missing:
        raise ValueError('Worksheet QA failed: response space missing for visual item(s): '+','.join(str(i+1) for i in missing))
    return True

def _worksheet_footer_brand_v2302(canvas, doc):
    """Consistent brand footer on every generated PDF page."""
    brand=_worksheet_layout_rule_v2302('footer_brand_text','CikguLaju') or 'CikguLaju'
    try:
        canvas.saveState()
        canvas.setFont('Helvetica-Bold',8)
        canvas.drawCentredString(doc.pagesize[0]/2, 7*mm, brand)
        canvas.restoreState()
    except Exception:
        pass

# ============================================================
# v23.03 SUBJECT-SPECIFIC CURRICULUM HEADER QA
# Prevent generic "Tema" headers from being forced across subjects.
# ============================================================

def _worksheet_subject_header_rule_v2303(subject):
    try:
        with _db() as con:
            row=con.execute("""SELECT * FROM worksheet_subject_header_rules
                               WHERE subject=? AND verified=1""",(subject,)).fetchone()
        return dict(row) if row else {}
    except Exception:
        return {}

def _worksheet_curriculum_header_v2303(state):
    subject=str(state.get('subject') or '')
    rule=_worksheet_subject_header_rule_v2303(subject)
    out=[]
    # Use only values actually present in state/DB; do not invent curriculum labels.
    if subject=='Matematik':
        bidang=str(state.get('bidang') or state.get('domain') or '').strip()
        topic=str(state.get('topic') or '').strip()
        if bidang: out.append(('Bidang',bidang))
        if topic: out.append(('Tajuk',topic))
    else:
        theme=str(state.get('theme') or '').strip()
        topic=str(state.get('topic') or '').strip()
        if rule.get('show_theme') and theme:
            out.append((str(rule.get('primary_field') or 'Tema'),theme))
        if rule.get('show_topic') and topic:
            label='Tajuk' if subject!='Bahasa Inggeris' else 'Topic'
            out.append((label,topic))
    sk=str(state.get('sk_code') or '').strip()
    sp=str(state.get('sp_code') or '').strip()
    if sk: out.append(('SK',sk))
    if sp: out.append(('SP',sp))
    return out

def _worksheet_validate_curriculum_header_v2303(subject, header_rows):
    labels=[str(x[0]).strip().lower() for x in (header_rows or []) if isinstance(x,(tuple,list)) and x]
    if subject=='Matematik' and 'tema' in labels:
        raise ValueError('Worksheet QA failed: Matematik tidak boleh menggunakan Tema sebagai header generik.')
    return True

# ============================================================
# v23.04 TAHAP 1 VISUAL OBJECT CURRICULUM GUARD
# Runtime may use only approved DB objects with curriculum/textbook evidence.
# ============================================================
def _worksheet_visual_object_allowed_v2304(year_label, subject, object_key):
    try:
        with _db() as con:
            row=con.execute("""SELECT approved,runtime_enabled,curriculum_evidence,textbook_evidence
                               FROM worksheet_object_vocabulary_bank
                               WHERE year_label=? AND subject=? AND object_key=?""",
                            (year_label,subject,object_key)).fetchone()
        if not row:
            return False
        approved,enabled,curr_ev,text_ev=row
        return bool(approved and enabled and str(curr_ev or '').strip() and str(text_ev or '').strip())
    except Exception:
        return False

def _worksheet_stage_v2304(year_label):
    return 'Tahap 1' if year_label in ('Tahun 1','Tahun 2','Tahun 3') else 'Tahap 2'

# v23.11: strict Year 1 HQ visual gate. Runtime AI remains disabled.
def _year1_hq_visual_ready_v2311(subject, sp_code):
    try:
        with _db() as con:
            row=con.execute("""SELECT q.asset_blob_id
              FROM year1_hq_visual_production_queue q
              JOIN year1_hq_visual_asset_qa a ON a.asset_blob_id=q.asset_blob_id
              WHERE q.subject=? AND q.sp_code=? AND q.runtime_enabled=1
                AND q.qa_status='approved' AND a.approved=1
                AND a.is_black_white=1 AND a.is_high_resolution=1
                AND a.curriculum_match=1 AND a.textbook_match=1
                AND a.question_functional=1
              LIMIT 1""",(subject,sp_code)).fetchone()
        return row[0] if row else None
    except Exception:
        return None

def _year1_visual_fallback_allowed_v2311(year_label):
    # Never insert an unrelated generic visual into a Year 1 assessment item.
    return str(year_label) != 'Tahun 1'

# v23.14 — DB-backed Tahap 1 commercial worksheet component policy.
def _tahap1_component_rule_v2314(rule_key, default=None):
    try:
        with _db() as con:
            row=con.execute("""SELECT rule_value FROM worksheet_tahap1_component_rules
                               WHERE rule_key=? AND runtime_enabled=1 LIMIT 1""",(rule_key,)).fetchone()
        return row[0] if row else default
    except Exception:
        return default

def _tahap1_section_patterns_v2314(subject, year_label):
    group='language' if str(subject) in ('Bahasa Melayu','Bahasa Inggeris') else ('math' if str(subject)=='Matematik' else ('science' if str(subject)=='Sains' else 'other'))
    try:
        y=int(re.search(r'(\d+)',str(year_label)).group(1))
    except Exception:
        y=1
    try:
        with _db() as con:
            rows=con.execute("""SELECT pattern_key,section_type,visual_required,response_required
                                FROM worksheet_tahap1_section_patterns
                                WHERE subject_group=? AND min_year<=? AND max_year>=?
                                  AND runtime_enabled=1 ORDER BY pattern_key""",(group,y,y)).fetchall()
        return [dict(r) for r in rows]
    except Exception:
        return []

def _tahap1_design_guard_v2314(state):
    year=str(state.get('year') or '')
    if year not in ('Tahun 1','Tahun 2','Tahun 3'):
        return True
    required=('commercial_workbook_layout','footer_every_page','runtime_page_is_programmatic',
              'visuals_must_be_question_functional','no_unrelated_generic_visual')
    missing=[k for k in required if str(_tahap1_component_rule_v2314(k,'0'))!='1']
    if missing:
        raise RuntimeError('Tahap 1 worksheet design configuration incomplete: '+', '.join(missing))
    return True

# v23.15 — deterministic Tahap 1 renderer contracts, DB only.
def _tahap1_renderer_contract_v2315(subject, year_label):
    if str(year_label) not in ('Tahun 1','Tahun 2','Tahun 3'):
        return []
    group='language' if str(subject) in ('Bahasa Melayu','Bahasa Inggeris') else ('math' if str(subject)=='Matematik' else ('science' if str(subject)=='Sains' else 'other'))
    try:
        with _db() as con:
            rows=con.execute("""SELECT section_order,section_badge,section_type,min_items,max_items,
                                visual_mode,response_mode,mandatory
                                FROM worksheet_tahap1_renderer_contract
                                WHERE subject_group=? AND runtime_enabled=1 ORDER BY section_order""",(group,)).fetchall()
        return [dict(r) for r in rows]
    except Exception:
        return []

def _tahap1_contract_validate_v2315(subject, year_label, sections):
    contracts=_tahap1_renderer_contract_v2315(subject,year_label)
    if not contracts:
        return True
    by_type={str(s.get('section_type')):s for s in (sections or [])}
    errors=[]
    for c in contracts:
        if int(c.get('mandatory') or 0)!=1: continue
        s=by_type.get(str(c['section_type']))
        if not s:
            errors.append('missing '+str(c['section_type'])); continue
        n=int(s.get('item_count') or 0)
        if n<int(c['min_items']) or n>int(c['max_items']):
            errors.append('%s item_count=%s'%(c['section_type'],n))
        if str(c['visual_mode'])!='none' and int(s.get('visual_count') or 0)<n:
            errors.append('%s visual_count incomplete'%c['section_type'])
        if int(s.get('response_count') or 0)<n:
            errors.append('%s response_count incomplete'%c['section_type'])
    if errors:
        raise RuntimeError('Tahap 1 worksheet QA failed: '+'; '.join(errors))
    return True

