def _complete_word_pattern_v2318(answer, revealed_positions=()):
    word=str(answer or '').strip()
    if not word: raise RuntimeError('complete_word requires an answer')
    revealed=set(int(x) for x in revealed_positions)
    return ' '.join(ch if i in revealed or not ch.isalpha() else '_' for i,ch in enumerate(word))

