        ready=con.execute("""SELECT b.beta_ready,b.reason
          FROM worksheet_beta_eligibility_v2340 b
          JOIN curriculum_standards s ON s.id=b.curriculum_standard_id
          WHERE s.year_label=? AND s.subject=? AND s.sp_code=? LIMIT 1""",
          (year,subject,sp)).fetchone()
