# === v23.61 RPH SEMANTIC + LANGUAGE + PAGINATION REPAIR ===
def _rph_attendance_value(total):
    """Print the teacher-entered class size directly."""
    total=str(total or '').strip()
    return total if total else '________________'

def _rph_selected_sp_pairs(s):
    """Return only Learning Standards actually selected/confirmed in the flow."""
    if _is_english_subject(s) and s.get('bi_main_row'):
        out=[]
        for row in (s.get('bi_main_row'), s.get('bi_comp_row')):
            if row and str(row.get('sp_code') or '').strip():
                out.append((str(row.get('sp_code') or '').strip(),str(row.get('sp_text') or '').strip()))
        return out
    chosen=[str(x).strip() for x in (s.get('selected_sp_codes') or []) if str(x).strip()]
    opts=s.get('multi_sp_options') or s.get('rph_sp_options') or []
    if chosen:
        by={str(o.get('sp_code') or '').strip():str(o.get('sp_text') or '').strip() for o in opts}
        return [(c,by.get(c,'')) for c in chosen]
    c=str(s.get('sp_code') or '').strip(); x=str(s.get('sp_text') or '').strip()
    return [(c,x)] if c or x else []

def _rph_english_materials_v2361(s, focus, pairs):
    page=str(s.get('textbook_page') or s.get('page') or '').strip()
    book=str(s.get('textbook_book_title') or s.get('textbook_title') or '').strip()
    skills={c.split('.')[0] for c,_ in pairs if c}
    mats=[]
    if page:
        mats.append(((book+', ') if book else 'Textbook ')+f'page {_clean_page_range_text(page)}')
    mats.append(f'{focus} picture/visual cards')
    if '1' in skills: mats += ['teacher-read listening script','picture/word response cards']
    if '2' in skills: mats += ['speaking prompt cards','simple information cards']
    if '3' in skills: mats += ['short reading extract','keyword cards']
    if '4' in skills: mats += ['guided writing frame','word/phrase bank']
    if '5' in skills: mats += ['language arts prompt cards']
    mats += ['pupil response sheet','teacher checklist']
    out=[]
    for m in mats:
        if m and m not in out: out.append(m)
    return '; '.join(out[:7])

def _semantic_full_rph_text(s):
    """Exact selected-SP RPH. English output is fully English and teacher-facing."""
    subject=str(s.get('subject') or '').strip(); year=str(s.get('year') or '').strip()
    topic=str(s.get('topic') or '').strip(); sub=str(s.get('subtopic') or '').strip()
    focus=sub if sub and sub not in ('Semua Subtopik','All Subtopics') else topic
    pairs=_rph_selected_sp_pairs(s)
    if not subject or not pairs: return None
    sp_display='; '.join((c+' '+x).strip() for c,x in pairs)
    sk_display=_rph_sk_display(s)
    dur=max(20,min(180,int(s.get('rph_duration_minutes') or 60)))
    if _is_english_subject(s):
        year_out=re.sub(r'^Tahun\s+','Year ',year,flags=re.I)
        materials=_rph_english_materials_v2361(s,focus,pairs)
        skills={c.split('.')[0] for c,_ in pairs if c}
        skill_words=[]
        if '1' in skills: skill_words.append('identify key sounds or information from short teacher-read input')
        if '2' in skills: skill_words.append('give a simple spoken response using the target language')
        if '3' in skills: skill_words.append('locate the required information in a short supported text')
        if '4' in skills: skill_words.append('produce a short supported written response')
        if '5' in skills: skill_words.append('respond to the language-arts task using the given prompt')
        target=' and '.join(skill_words) or 'perform the action stated in the selected Learning Standard'
        induction=5 if dur>=35 else 3; closure=5 if dur>=30 else 3; main=max(14,dur-induction-closure)
        a1=max(6,main//3); a2=max(6,main//3); a3=max(5,main-a1-a2)
        return '\n'.join([
            'SUBJECT: English', f'YEAR / FORM: {year_out}', f'TOPIC: {topic}',
            f'CONTENT STANDARD: {sk_display}', f'LEARNING STANDARD: {sp_display}',
            f'LEARNING OBJECTIVES: By the end of the {dur}-minute lesson, pupils can {target} in the context of {focus}, with appropriate support for their level.',
            f'SUCCESS CRITERIA: Pupils demonstrate the selected Learning Standard accurately during the guided task and the individual or paired check on {focus}.',
            f'PRIOR KNOWLEDGE: Pupils recall familiar words, sounds, ideas or experiences connected to {focus}.',
            f'TEACHING AND LEARNING MATERIALS: {materials}.',
            'CROSS-CURRICULAR ELEMENTS / VALUES: Communication, confidence and cooperation where required by the task.',
            'HOTS / 21ST CENTURY LEARNING: Pupils identify relevant clues, explain a choice and check or improve a response.',
            'ASSESSMENT: Teacher observes responses during the lesson and records evidence against the selected Learning Standard using the teacher checklist.',
            f'SET INDUCTION: {induction} minutes\nTeacher shows two visuals linked to {focus} and gives one short oral example. Pupils respond using a familiar word, sound or idea. Teacher states the lesson focus.',
            f'MAIN ACTIVITIES: Activity 1 ({a1} minutes)\nTeacher models the exact target skill using {focus} material. Pupils identify the relevant clue and respond with support.\nActivity 2 ({a2} minutes)\nPupils complete a guided pair task using the prepared cards or response sheet. Teacher checks responses against the selected Learning Standard.\nActivity 3 ({a3} minutes)\nPupils complete a fresh individual or paired check in the same {focus} context. Teacher records pupils who need further support.',
            f'CLOSURE: {closure} minutes\nOne or two pupils demonstrate the target skill with a fresh prompt. Teacher revisits the success criterion and notes the next learning need.',
            f'REMEDIAL / ENRICHMENT: Remedial: Reduce the language load, provide one clear visual or word cue and model one example before pupils try again. Enrichment: Use a new {focus} prompt and require an additional relevant detail, reason or response while staying within the same Learning Standard.',
            'REFLECTION: ________ pupils achieved the lesson objectives. ________ pupils require further support. Follow-up action: ________________________________.'
        ])
    return None
# === END v23.61 ===

# v23.83 EXPLICIT AI FALLBACK (teacher-triggered only)
def _explicit_ai_bbm_fallback_v2383(cid):
    ss=state.setdefault(cid,{})
    required=('year','subject','topic','sk_code','sp_code')
    missing=[k for k in required if not str(ss.get(k) or '').strip()]
    if missing:
        return send(cid,'⚠️ Pilihan kurikulum belum lengkap. Sila pilih Tahun/Tingkatan, Subjek, Tajuk, SK dan SP dahulu.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    if not GEMINI_API_KEY:
        return send(cid,'⚠️ Gemini belum dikonfigurasi pada server. BBM bank tempatan masih boleh digunakan.',[[{'text':'🎨 Cuba BBM Bank Tempatan','callback_data':'continue_bbm'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    prompt=(
        'Anda membantu guru Malaysia menyediakan CADANGAN BBM sementara. '
        'JANGAN cipta, ubah atau meneka kod/teks SK dan SP. Gunakan tepat konteks yang diberi. '
        'Jika maklumat tidak cukup, nyatakan batasan. Hasilkan cadangan ringkas, praktikal dan boleh disemak guru sebelum digunakan.\n\n'
        f"Tahun/Tingkatan: {ss.get('year','')}\nSubjek: {ss.get('subject','')}\nTema/Tajuk/Topik: {ss.get('topic','')}\n"
        f"SK: {ss.get('sk_code','')} {ss.get('sk_text','')}\nSP: {ss.get('sp_code','')} {ss.get('sp_text','')}\n\n"
        'Berikan: 1) jenis BBM, 2) kandungan/komponen, 3) cara guna dalam kelas, 4) semakan penjajaran kepada SP. '
        'Jangan dakwa bahan ini READY atau diluluskan.'
    )
    try:
        send(cid,'✨ <b>Gemini sedang menyediakan cadangan BBM sementara...</b>')
        text=_gemini_generate_database_builder(prompt,max_output_tokens=2200)
        state[cid]['last_result']=text
        state[cid]['last_result_context']=dict(ss)
        send_long_plain(cid,text)
        return send(cid,'⚠️ <b>Cadangan AI — perlu semakan guru.</b> Bahan ini bukan bahan READY dalam bank CikguLaju.',[[{'text':'🎨 Cuba BBM Bank Tempatan','callback_data':'continue_bbm'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    except Exception as e:
        print('Explicit Gemini BBM fallback error:',repr(e),flush=True)
        return send(cid,'⚠️ Gemini belum berjaya menjana cadangan. Pilihan SK/SP cikgu dikekalkan; cuba lagi atau gunakan bank tempatan.',[[{'text':'✨ Cuba Gemini Lagi','callback_data':'ai_fallback_bbm'}],[{'text':'🎨 BBM Bank Tempatan','callback_data':'continue_bbm'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])

# v23.76 BUTTON / CALLBACK AUDIT HARDENING
# Keep the existing dispatcher intact, but never allow a callback exception to fail silently.
_callback_dispatch_v2372 = callback
def callback(cid, d):
    try:
        if d == 'ai_fallback_bbm':
            return _explicit_ai_bbm_fallback_v2383(cid)
        return _callback_dispatch_v2372(cid, d)
    except Exception as e:
        print('Callback dispatch error:', repr(e), 'callback=', repr(d), 'chat=', cid, flush=True)
        try:
            return send(
                cid,
                '⚠️ <b>Fungsi ini belum berjaya dibuka.</b>\n\nCuba sekali lagi atau kembali ke Menu Utama.',
                [[{'text':'🔄 Cuba Lagi','callback_data':str(d)[:64] if str(d) else 'home'}],
                 [{'text':'🏠 Menu Utama','callback_data':'home'}]]
            )
        except Exception as send_error:
            print('Callback recovery send error:', repr(send_error), flush=True)
            return None

