# ===== v23.86 TEMPLATE-FIRST ENGINE =====
def _template_bank_db_v2386():
    import os
    p=os.path.join(os.path.dirname(__file__),'CikguLaju_Templates_02.db')
    return p if os.path.exists(p) else None

def _select_ready_template_v2386(surface, subject, year_num, skill_text='', activity_type=''):
    """Select a predesigned whole-page template. Runtime AI is never used."""
    p=_template_bank_db_v2386()
    if not p:
        return None
    import sqlite3, json
    con=sqlite3.connect(p); con.row_factory=sqlite3.Row
    try:
        q="""SELECT m.*,f.family_name,f.activity_type,f.answer_policy,f.default_palette,
                    i.preparation,i.teacher_action,i.pupil_action,i.variation,i.success_criteria
             FROM template_master m
             JOIN template_family f ON f.family_key=m.family_key AND f.approved=1
             JOIN template_subject_map sm ON sm.template_key=m.template_key
             LEFT JOIN template_instruction_pack i ON i.template_key=m.template_key
             WHERE f.surface=? AND sm.subject=? AND ? BETWEEN sm.year_min AND sm.year_max
               AND m.approved=1"""
        rows=[dict(r) for r in con.execute(q,(surface,subject,int(year_num or 1))).fetchall()]
        if not rows: return None
        text=(skill_text or '').lower()
        def score(r):
            z=0
            if activity_type and r.get('activity_type')==activity_type: z+=100
            tags=(r.get('quality_tags') or '').lower()
            if 'ready_to_use' in tags: z+=10
            # deterministic keyword affinity
            for w in set(re.findall(r'[a-zA-Z]{4,}',text)):
                if w in (r.get('activity_type') or '').lower(): z+=3
            z+=int(r.get('variant_no') or 1)
            return z
        rows.sort(key=score,reverse=True)
        r=rows[0]
        for k in ('layout_json','content_schema_json','render_rules_json'):
            try: r[k]=json.loads(r[k])
            except Exception: pass
        return r
    finally:
        con.close()

def _template_answer_leakage_ok_v2386(template, item):
    """Hard guard: assessed picture matching/naming cannot contain the answer label."""
    if not template: return False
    pol=(template.get('answer_policy') or '').lower()
    if 'picture_has_no_answer_label' in pol or 'no_target_labels' in pol:
        shown=str(item.get('display_label') or '').strip().lower()
        ans=str(item.get('answer') or '').strip().lower()
        return not (shown and ans and shown==ans)
    return True
# ===== END v23.86 TEMPLATE-FIRST ENGINE =====


