# ===== v23.94 SPACE-EFFICIENT PICTURE CARD LAYOUT =====
def _bbm_picture_card_layout_v2394(layout_key, item_count):
    """One selected layout per PDF. Minimize wasted A4 space."""
    import math, os, sqlite3
    key=(layout_key or '2x2').lower().replace('×','x').strip()
    if key not in ('3x3','2x2','1x1'): key='2x2'
    p=os.path.join(os.path.dirname(__file__),'CikguLaju_Templates_02.db')
    con=sqlite3.connect(p); con.row_factory=sqlite3.Row
    try:
        r=con.execute("SELECT * FROM bbm_picture_card_layout_v2394 WHERE layout_key=? AND status='READY'",(key,)).fetchone()
        if not r: return None
        d=dict(r); n=max(1,int(item_count or 1))
        d['pages']=int(math.ceil(n/float(d['cards_per_page'])))
        d['item_count']=n
        d['last_page_cards']=n-(d['pages']-1)*d['cards_per_page']
        return d
    finally: con.close()
# ===== END v23.94 SPACE-EFFICIENT PICTURE CARD LAYOUT =====


