def _class_level_guess_v2393(name):
    m=re.match(r'^\s*([1-6])\b',str(name or ''))
    return m.group(1) if m else ''


def _year_number_v2393(year_label):
    m=re.search(r'([1-6])',str(year_label or ''))
    return m.group(1) if m else ''


def _profile_class_records_for_year_v2393(cid, year_label):
    want=_year_number_v2393(year_label)
    rows=[]
    for i,r in enumerate(_profile_class_records(cid)):
        explicit=str(r.get('year_label') or '').strip()
        got=_year_number_v2393(explicit) or _class_level_guess_v2393(r.get('name'))
        if want and got==want:
            x=dict(r); x['_profile_idx']=i; rows.append(x)
    return rows


def _pdp_pick_class_v2393(cid):
    ss=state.setdefault(cid,{})
    rows=_profile_class_records_for_year_v2393(cid,ss.get('year',''))
    ss['_pdp_classes_v2393']=rows
    if not rows:
        return send(cid,
            f"🏫 <b>Tiada kelas {html.escape(str(ss.get('year') or ''))} dipautkan dalam profil.</b>\n\nTambah/kemas kini kelas dahulu supaya CikguLaju hanya memaparkan kelas bagi tahun/tingkatan yang dipilih.",
            [[{'text':'🏫 Urus Kelas','callback_data':'profclass_manage'}],
             [{'text':'⬅️ Kembali ke kandungan','callback_data':'qsrc91_back'}],
             [{'text':'🏠 Menu Utama','callback_data':'home'}]])
    kb=[]
    for j,r in enumerate(rows[:20]):
        extra=f" • {r.get('students')} murid" if r.get('students') else ''
        kb.append([{'text':('🏫 '+str(r.get('name') or '')+extra)[:60],'callback_data':f'pdpclass93_{j}'}])
    kb.append([{'text':'🏫 Urus Kelas','callback_data':'profclass_manage'}])
    return send(cid,f"🏫 <b>Pilih Kelas • {html.escape(str(ss.get('year') or ''))}</b>\n\nHanya kelas yang sepadan dengan tahun/tingkatan ini disenaraikan.",kb)


def _pdp_pick_date_v2393(cid):
    """Monthly Sunday-first calendar; replaces the historical linear 7/14-day picker."""
    fn=globals().get('_calendar_v2437') or globals().get('_pdp_calendar_month_v2429')
    if callable(fn):
        return fn(cid)
    raise RuntimeError('Monthly calendar handler is unavailable')

def _norm_subject_v2393(x):
    return re.sub(r'[^a-z0-9]+','',str(x or '').casefold())


def _pdp_time_options_v2393(cid):
    ss=state.setdefault(cid,{})
    cname=str(ss.get('rph_class') or '')
    subject=str(ss.get('subject') or '')
    day=str(ss.get('rph_day') or '')
    rec=_profile_class_record(cid,cname) or {}
    slots=[]
    for e in rec.get('timetable') or []:
        if str(e.get('day') or '')!=day: continue
        a=_norm_subject_v2393(e.get('subject')); b=_norm_subject_v2393(subject)
        if a and b and (a==b or a in b or b in a): slots.append(e)
    ss['_pdp_slots_v2393']=slots
    kb=[]
    for i,e in enumerate(slots[:10]):
        kb.append([{'text':f"🕐 {e['start']}–{e['end']} ⭐ Ikut Jadual",'callback_data':f'pdptime93_{i}'}])
    kb.append([{'text':'✏️ Pilih Masa Manual','callback_data':'pdptime93_manual'}])
    kb.append([{'text':'⬅️ Tukar Tarikh','callback_data':'pdpdate93_back'}])
    msg=f"🕐 <b>Masa PdP • {html.escape(day)}</b>\n\n"
    msg += ('Pilih waktu daripada jadual profil atau gunakan masa manual.' if slots else 'Tiada waktu yang sepadan dalam jadual profil untuk hari/subjek ini. Pilih masa manual.')
    return send(cid,msg,kb)


def _pdp_manual_start_v2393(cid):
    starts=['07:30','08:00','08:30','09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30','13:00','13:30','14:00','14:30','15:00']
    state.setdefault(cid,{})['_pdp_manual_starts_v2393']=starts
    kb=[]
    for i in range(0,len(starts),2):
        kb.append([{'text':starts[j],'callback_data':f'pdpstart93_{j}'} for j in range(i,min(i+2,len(starts)))])
    kb.append([{'text':'⬅️ Kembali','callback_data':'pdptime93_back'}])
    return send(cid,'✏️ <b>Pilih Masa Manual</b>\n\nPilih masa mula.',kb)


def _pdp_manual_duration_v2393(cid):
    kb=[[{'text':'30 min','callback_data':'pdpdur93_30'},{'text':'40 min','callback_data':'pdpdur93_40'}],
        [{'text':'60 min','callback_data':'pdpdur93_60'},{'text':'80 min','callback_data':'pdpdur93_80'}],
        [{'text':'90 min','callback_data':'pdpdur93_90'}],
        [{'text':'⬅️ Tukar Masa Mula','callback_data':'pdptime93_manual'}]]
    return send(cid,f"✏️ Masa mula: <b>{html.escape(str(state.setdefault(cid,{}).get('_pdp_manual_start_v2393') or ''))}</b>\n\nPilih tempoh PdP.",kb)


def _pdp_finish_context_v2393(cid,start,end):
    ss=state.setdefault(cid,{})
    ss['rph_time']=f'{start} - {end}'
    ss['rph_start_time']=start; ss['rph_end_time']=end
    try:
        h1,m1=map(int,start.split(':')); h2,m2=map(int,end.split(':'))
        ss['duration_minutes']=(h2*60+m2)-(h1*60+m1)
    except Exception: pass
    ss['_pdp_context_ready_v2393']=True
    return _auto_pack_v2393_base(cid)


def _temporary_auto_pack_v2386(cid):
    ss=state.setdefault(cid,{})
    if (ss.get('quick_material_flow') or ss.get('task')=='quick_material') and not ss.get('_pdp_context_ready_v2393'):
        return _pdp_pick_class_v2393(cid)
    return _auto_pack_v2393_base(cid)

# Preserve class year/form linkage inside class_profiles JSON without requiring a new DB column.
_clean_profile_class_records_v2393_base=_clean_profile_class_records
def _clean_profile_class_records(records):
    base=_clean_profile_class_records_v2393_base(records)
    src=[]
    for x in records or []:
        src.append(x if isinstance(x,dict) else {'name':x})
    byname={str(x.get('name') or x.get('class_name') or '').strip().casefold():x for x in src if isinstance(x,dict)}
    for r in base:
        old=byname.get(str(r.get('name') or '').casefold()) or {}
        yl=str(old.get('year_label') or '').strip()[:30]
        if yl: r['year_label']=yl
    return base

