_callback_dispatch_v2393_base=callback
def callback(cid,d):
    ss=state.setdefault(cid,{})
    if d=='profclass_level93':
        kb=[]
        vals=[f'Tahun {i}' for i in range(1,7)]+[f'Tingkatan {i}' for i in range(1,6)]
        ss['_profile_levels_v2393']=vals
        for i in range(0,len(vals),2):
            kb.append([{'text':vals[j],'callback_data':f'proflevel93_{j}'} for j in range(i,min(i+2,len(vals)))])
        kb.append([{'text':'⬅️ Kembali','callback_data':'profclass_manage'}])
        return send(cid,'🎓 <b>Tetapkan Tahun/Tingkatan Kelas</b>',kb)
    if d.startswith('proflevel93_'):
        try: j=int(d.rsplit('_',1)[1]); val=(ss.get('_profile_levels_v2393') or [])[j]; idx=int(ss.get('profile_class_idx'))
        except Exception: return _profile_class_manage_menu(cid)
        rows=_profile_class_records(cid)
        if 0<=idx<len(rows):
            old_name=str(rows[idx].get('name') or '').strip()
            suffix=re.sub(r'^\s*(?:tahun|tingkatan)?\s*[1-6]\s*[-–:]?\s*','',old_name,flags=re.I).strip() or old_name
            num=_year_number_v2393(val) or ''
            rows[idx]['year_label']=val
            rows[idx]['name']=(f'{num} {suffix}'.strip())[:60]
            _save_profile_class_records(cid,rows)
            return _profile_class_item_menu(cid,idx)
        return _profile_class_manage_menu(cid)
    if d.startswith('pdpclass93_') and d!='pdpclass93_back':
        try: j=int(d.rsplit('_',1)[1]); r=(ss.get('_pdp_classes_v2393') or [])[j]
        except Exception: return _pdp_pick_class_v2393(cid)
        ss['rph_class']=r.get('name'); ss['student_count']=r.get('students'); ss['rph_students']=r.get('students')
        return _pdp_pick_date_v2393(cid)
    if d=='pdpclass93_back': return _pdp_pick_class_v2393(cid)
    if d.startswith('pdpdate93_') and d!='pdpdate93_back':
        try: j=int(d.rsplit('_',1)[1]); iso=(ss.get('_pdp_dates_v2393') or [])[j]; dt=date.fromisoformat(iso)
        except Exception: return _pdp_pick_date_v2393(cid)
        days=['Isnin','Selasa','Rabu','Khamis','Jumaat','Sabtu','Ahad']
        ss['rph_date']=iso; ss['rph_day']=days[dt.weekday()]
        return _pdp_time_options_v2393(cid)
    if d=='pdpdate93_back': return _pdp_pick_date_v2393(cid)
    if d.startswith('pdptime93_') and d not in ('pdptime93_manual','pdptime93_back'):
        try: j=int(d.rsplit('_',1)[1]); e=(ss.get('_pdp_slots_v2393') or [])[j]
        except Exception: return _pdp_time_options_v2393(cid)
        return _pdp_finish_context_v2393(cid,e['start'],e['end'])
    if d=='pdptime93_manual': return _pdp_manual_start_v2393(cid)
    if d=='pdptime93_back': return _pdp_time_options_v2393(cid)
    if d.startswith('pdpstart93_'):
        try: j=int(d.rsplit('_',1)[1]); ss['_pdp_manual_start_v2393']=(ss.get('_pdp_manual_starts_v2393') or [])[j]
        except Exception: return _pdp_manual_start_v2393(cid)
        return _pdp_manual_duration_v2393(cid)
    if d.startswith('pdpdur93_'):
        try: dur=int(d.rsplit('_',1)[1]); start=ss.get('_pdp_manual_start_v2393'); h,m=map(int,start.split(':')); total=h*60+m+dur; end=f'{total//60:02d}:{total%60:02d}'
        except Exception: return _pdp_manual_start_v2393(cid)
        return _pdp_finish_context_v2393(cid,start,end)
    return _callback_dispatch_v2393_base(cid,d)

