# Keep class names canonical: the selected level supplies the numeric prefix;
# teachers only need to type the class suffix (e.g. Amanah -> 6 Amanah).
def _canonical_class_display_v2403(year_label, raw_name):
    num=_year_number_v2393(year_label) or ''
    suffix=' '.join(str(raw_name or '').strip().split())
    suffix=re.sub(r'^\s*(?:tahun|tingkatan)?\s*[1-6]\s*[-–:]?\s*','',suffix,flags=re.I).strip()
    return (f'{num} {suffix}'.strip() if suffix else num)[:60]

# Stable context classes: exact year/form first, then subject links. Legacy classes
# without subject links remain eligible so existing beta profiles do not dead-end.
def _profile_class_records_for_context_v2394(cid, year_label, subject):
    rows=_profile_class_records_for_year_v2393(cid,year_label)
    want=_norm_subject_v2393(subject)
    linked=[]; legacy=[]
    for r in rows:
        subs=[str(x) for x in (r.get('subjects') or []) if str(x).strip()]
        if not subs:
            legacy.append(r); continue
        norms=[_norm_subject_v2393(x) for x in subs]
        if want and any(want==x or want in x or x in want for x in norms if x): linked.append(r)
    return linked if linked else legacy

# Timetable matches are deterministic and sorted by time; exact class + day + subject only.
def _pdp_matching_slots_v2403(cid):
    ss=state.setdefault(cid,{})
    rec=_profile_class_record(cid,str(ss.get('rph_class') or '')) or {}
    want=_norm_subject_v2393(ss.get('subject')); day=str(ss.get('rph_day') or '')
    slots=[]
    for e in rec.get('timetable') or []:
        if str(e.get('day') or '')!=day: continue
        got=_norm_subject_v2393(e.get('subject'))
        if want and got and (want==got or want in got or got in want): slots.append(dict(e))
    def key(e):
        try: return tuple(map(int,str(e.get('start') or '99:99').split(':')))
        except Exception: return (99,99)
    slots.sort(key=key)
    return slots

def _pdp_time_options_v2393(cid):
    ss=state.setdefault(cid,{})
    slots=_pdp_matching_slots_v2403(cid); ss['_pdp_slots_v2393']=slots
    kb=[]
    for i,e in enumerate(slots[:10]):
        kb.append([{'text':f"🕐 {e.get('start','')}–{e.get('end','')} ⭐ Ikut Jadual",'callback_data':f'pdptime93_{i}'}])
    kb.append([{'text':'✏️ Pilih Masa Manual','callback_data':'pdptime93_manual'}])
    kb.append([{'text':'⬅️ Tukar Tarikh','callback_data':'pdpdate93_back'}])
    if len(slots)==1:
        note='Satu waktu sepadan ditemui dalam jadual profil. Cikgu masih boleh pilih masa manual jika jadual berubah.'
    elif len(slots)>1:
        note=f'{len(slots)} waktu sepadan ditemui. Pilih waktu yang digunakan atau pilih masa manual.'
    else:
        note='Tiada waktu sepadan dalam jadual profil untuk kelas + subjek + hari ini. Gunakan masa manual.'
    return send(cid,f"🕐 <b>Masa PdP • {html.escape(str(ss.get('rph_day') or ''))}</b>\n\n{note}",kb)

# Human-readable source identity for the final package/context. SK/SP stay internal.
