def _norm_content_v2405(v):
    import re as _re
    s=str(v or '').strip().casefold()
    s=_re.sub(r'^(unit|tema|theme|topic|tajuk)\s*\d*\s*[:\-–—.]?\s*','',s)
    s=_re.sub(r'\s+',' ',s)
    return s.strip(' -–—:')

def _content_match_v2405(row, selected):
    sel=_norm_content_v2405(selected)
    if not sel: return True
    vals=[row.get('unit_title'),row.get('content_topic'),row.get('focus')]
    for v in vals:
        n=_norm_content_v2405(v)
        if n and (n==sel or n in sel or sel in n): return True
    return False

def _verified_lesson_rows_v2404(year_label, subject, selected_content=''):
    con=_db()
    try:
        _ensure_textbook_page_lesson_map_schema(con)
        rows=[dict(r) for r in con.execute("""SELECT * FROM textbook_page_lesson_map
            WHERE year_label=? AND subject=? AND verified=1
            ORDER BY unit_title, CAST(COALESCE(NULLIF(lesson_no,''),'999999') AS INTEGER), page_start, id""",(year_label,subject)).fetchall()]
    finally: con.close()
    if selected_content: rows=[r for r in rows if _content_match_v2405(r,selected_content)]
    # De-duplicate exact lesson/page mappings without fabricating sequence.
    out=[]; seen=set()
    for r in rows:
        k=(str(r.get('unit_title') or '').casefold(),str(r.get('lesson_no') or '').casefold(),r.get('page_start'),r.get('page_end'),str(r.get('focus') or '').casefold())
        if k in seen: continue
        seen.add(k); out.append(r)
    return out

def _lesson_context_trace_v2405(ss):
    r=ss.get('_verified_lesson_row_v2404') or {}
    return {
        'year':ss.get('year',''),'subject':ss.get('subject',''),
        'content':ss.get('quick_content_v2391',''),'source':'RPT/SOW',
        'lesson_no':r.get('lesson_no') or ss.get('textbook_lesson_no',''),
        'focus':r.get('focus') or ss.get('textbook_page_focus',''),
        'page_start':r.get('page_start') if r else ss.get('textbook_page_start'),
        'page_end':r.get('page_end') if r else ss.get('textbook_page_end'),
        'content_topic':r.get('content_topic') or ss.get('textbook_content_topic',''),
        'language_focus':r.get('language_focus') or ss.get('textbook_language_focus',''),
        'activity_ref':r.get('activity_ref') or ss.get('textbook_activity_ref',''),
        'verified':bool(r and r.get('verified')),
    }

