def _lesson_mapping_key_v2409(ss):
    r=ss.get('_verified_lesson_row_v2404') or {}
    return {
        'year_label': str(ss.get('year') or r.get('year_label') or '').strip(),
        'subject': str(ss.get('subject') or r.get('subject') or '').strip(),
        'unit_title': str(r.get('unit_title') or ss.get('quick_content_v2391') or '').strip(),
        'lesson_no': str(r.get('lesson_no') or ss.get('textbook_lesson_no') or '').strip(),
        'focus': str(r.get('focus') or ss.get('textbook_page_focus') or '').strip(),
        'page_start': r.get('page_start') if r else ss.get('textbook_page_start'),
        'page_end': r.get('page_end') if r else ss.get('textbook_page_end'),
    }

def _lesson_package_readiness_v2409(ss):
    """Return factual readiness only. Unknown source coverage never becomes 'not related'."""
    diag=_lesson_package_diagnostic_v2408(ss)
    cov=diag.get('coverage') or {}
    manifest=diag.get('manifest') or {}
    mandatory=('RPH','Worksheet','BBM')
    blockers=[]
    if not cov.get('lesson'): blockers.append('Lesson RPT/SOW belum verified')
    if not cov.get('standards'): blockers.append('SK/SP Lesson belum verified')
    if not cov.get('textbook_page'): blockers.append('halaman Buku Teks belum dipetakan')
    # Activity book and media are component-level gaps, not blockers for sending other available materials.
    return {
        'can_process_core': bool(cov.get('lesson') and cov.get('standards')),
        'mandatory_components': mandatory,
        'blockers': blockers,
        'manifest': manifest,
        'coverage': cov,
        'mapping_key': _lesson_mapping_key_v2409(ss),
    }

def _lesson_package_status_text_v2408(ss):
    """Final beta wording: worksheet is always required; media may be Tidak berkaitan only when verified false."""
    m=_lesson_package_manifest_v2407(ss)
    label={'mapped':'Tersedia','ready_to_build':'Sedia diproses','under_construction':'🚧 Dalam pembinaan','not_related':'Tidak berkaitan'}
    icons={'RPH':'📘','Worksheet':'📝','BBM':'🎨','Buku Teks':'📖','Buku Aktiviti':'📚','Audio/Media':'🔊'}
    lines=[]
    for k,v in m.items():
        status=v.get('status')
        if k=='Worksheet' and status=='not_related': status='under_construction'
        lines.append(f"{icons.get(k,'•')} {k} — {label.get(status,status or '')}")
    return '\n'.join(lines)

def _lesson_partial_delivery_policy_v2409(ss):
    """Central partial-success policy used by future delivery hooks."""
    r=_lesson_package_readiness_v2409(ss)
    m=r['manifest']
    return {
        'continue_when_optional_missing': True,
        'continue_when_activity_book_missing': True,
        'continue_when_media_missing': True,
        'worksheet_required': True,
        'core_context_verified': r['can_process_core'],
        'blockers': list(r['blockers']),
        'statuses': {k:v.get('status') for k,v in m.items()},
    }

