# ===== v24.10 LARGE BATCH: SOURCE-EXPLICIT STANDARD REQUIREMENTS =====
APP_VERSION = 'v24.10-SOURCE-EXPLICIT-STANDARD-REQUIREMENTS'

def _lesson_standard_requirement_v2410(ss):
    """Read explicit verified source evidence about whether SK/SP is applicable to this lesson."""
    r=ss.get('_verified_lesson_row_v2404') or {}
    lesson_map_id=r.get('id')
    if not lesson_map_id: return None
    con=_db()
    try:
        try:
            row=con.execute("SELECT * FROM lesson_standard_requirements WHERE lesson_map_id=? AND verified=1 LIMIT 1",(lesson_map_id,)).fetchone()
            return dict(row) if row else None
        except Exception:
            return None
    finally:
        con.close()

def _lesson_context_trace_v2405(ss):
    r=ss.get('_verified_lesson_row_v2404') or {}; standards=ss.get('_verified_standard_rows_v2406') or []
    req=_lesson_standard_requirement_v2410(ss)
    sk=[]; sp=[]
    for x in standards:
        a=str(x.get('sk_code') or '').strip(); b=str(x.get('sp_code') or '').strip()
        if a and a not in sk: sk.append(a)
        if b and b not in sp: sp.append(b)
    not_applicable=bool(req and req.get('standards_required')==0 and req.get('requirement_status')=='not_applicable_explicit_source')
    return {'year':ss.get('year',''),'subject':ss.get('subject',''),'content':ss.get('quick_content_v2391',''),'source':'RPT/SOW',
      'lesson_no':r.get('lesson_no') or ss.get('textbook_lesson_no',''),'focus':r.get('focus') or ss.get('textbook_page_focus',''),
      'page_start':r.get('page_start') if r else ss.get('textbook_page_start'),'page_end':r.get('page_end') if r else ss.get('textbook_page_end'),
      'content_topic':r.get('content_topic') or ss.get('textbook_content_topic',''),'language_focus':r.get('language_focus') or ss.get('textbook_language_focus',''),
      'activity_ref':r.get('activity_ref') or ss.get('textbook_activity_ref',''),'sk_codes':sk,'sp_codes':sp,
      'lesson_verified':bool(r and r.get('verified')),'standards_verified':bool(standards),
      'standards_not_applicable':not_applicable,'standard_requirement':req,
      'verified':bool(r and r.get('verified') and (standards or not_applicable))}

def _lesson_material_gate_v2406(ss):
    trace=ss.get('_pdp_source_trace_v2405') or _lesson_context_trace_v2405(ss)
    req=_lesson_material_requirement_v2407(ss); activity=_lesson_activity_book_rows_v2407(ss); media=_lesson_media_rows_v2407(ss)
    media_required=(None if req is None or req.get('media_required') is None else bool(req.get('media_required')))
    if media: media_required=True
    standards_ok=bool(trace.get('standards_verified') or trace.get('standards_not_applicable'))
    return {
        'lesson_verified':bool(trace.get('lesson_verified')),
        'standards_verified':bool(trace.get('standards_verified')),
        'standards_not_applicable':bool(trace.get('standards_not_applicable')),
        'standard_requirement':trace.get('standard_requirement'),
        'page_verified':bool(trace.get('page_start') or ss.get('textbook_page') or ss.get('page')),
        'worksheet_required':True,'bbm_required':True if req is None else bool(req.get('bbm_required',1)),
        'activity_book':True if activity else None,'activity_book_rows':activity,
        'media_required':media_required,'media_rows':media,'requirements_verified':bool(req),
        'ready_for_generation':bool(trace.get('lesson_verified') and standards_ok),
    }

def _lesson_source_coverage_v2408(ss):
    trace=ss.get('_pdp_source_trace_v2405') or _lesson_context_trace_v2405(ss)
    gate=ss.get('_lesson_material_gate_v2406') or _lesson_material_gate_v2406(ss)
    return {'lesson':bool(trace.get('lesson_verified')),'standards':bool(trace.get('standards_verified')),
      'standards_not_applicable':bool(trace.get('standards_not_applicable')),
      'standards_resolved':bool(trace.get('standards_verified') or trace.get('standards_not_applicable')),
      'textbook_page':bool(gate.get('page_verified')),'activity_book':bool(gate.get('activity_book_rows')),
      'media_requirement_known':gate.get('media_required') is not None,'media_mapped':bool(gate.get('media_rows')),
      'generation_gate':bool(gate.get('ready_for_generation'))}

def _lesson_package_readiness_v2409(ss):
    diag=_lesson_package_diagnostic_v2408(ss); cov=diag.get('coverage') or {}; manifest=diag.get('manifest') or {}; blockers=[]
    if not cov.get('lesson'): blockers.append('Lesson RPT/SOW belum verified')
    if not cov.get('standards_resolved'): blockers.append('status SK/SP Lesson belum disahkan')
    if not cov.get('textbook_page'): blockers.append('halaman Buku Teks belum dipetakan')
    return {'can_process_core':bool(cov.get('lesson') and cov.get('standards_resolved')),
      'mandatory_components':('RPH','Worksheet','BBM'),'blockers':blockers,'manifest':manifest,'coverage':cov,
      'mapping_key':_lesson_mapping_key_v2409(ss)}

def _commit_verified_lesson_v2404(cid,idx):
    ss=state.setdefault(cid,{})
    rows=ss.get('_quick_verified_lesson_rows_v2404') or []
    if idx<0 or idx>=len(rows): return _quick_rpt_for_content_v2391(cid)
    r=rows[idx]
    ss['rph_mode']='fast_rpt'; ss['textbook_lesson_no']=str(r.get('lesson_no') or ''); ss['textbook_page_focus']=str(r.get('focus') or '')
    ss['textbook_content_topic']=str(r.get('content_topic') or ''); ss['textbook_language_focus']=str(r.get('language_focus') or '')
    ss['textbook_activity_ref']=str(r.get('activity_ref') or ''); ss['textbook_book_title']=str(r.get('book_title') or '')
    ss['textbook_page_start']=r.get('page_start'); ss['textbook_page_end']=r.get('page_end'); ss['textbook_page']=r.get('page_start'); ss['book_page']=r.get('page_start'); ss['page']=r.get('page_start')
    ss['_verified_lesson_row_v2404']=dict(r)
    try: _apply_textbook_page_lesson_context(ss,r.get('page_start'),r.get('lesson_no'),r.get('focus'))
    except Exception: pass
    try: _apply_textbook_page_sp_context(ss,r.get('page_start'),r.get('lesson_no'),r.get('focus'))
    except Exception as e: print('v24.10 standard hydration:',repr(e),flush=True)
    ss['_pdp_source_trace_v2405']=_lesson_context_trace_v2405(ss); ss['_lesson_material_gate_v2406']=_lesson_material_gate_v2406(ss)
    gate=ss['_lesson_material_gate_v2406']
    if not (gate.get('standards_verified') or gate.get('standards_not_applicable')):
        return send(cid,'🚧 <b>Status SK/SP untuk Lesson ini masih dalam pembinaan.</b>\n\nCikguLaju tidak akan mereka SK/SP. Pilih Lesson lain sementara mapping sumber disahkan.',[[{'text':'⬅️ Pilih Lesson Lain','callback_data':'qsrc91_rpt'}],[{'text':'📖 Ikut Buku Teks','callback_data':'qsrc91_textbook'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    if '_pdp_choose_class_v2393' in globals(): return _pdp_choose_class_v2393(cid)
    if '_pdp_pick_class_v2393' in globals(): return _pdp_pick_class_v2393(cid)
    return send(cid,'✅ Lesson telah disahkan daripada sumber.',[[{'text':'🏠 Menu Utama','callback_data':'home'}]])

APP_VERSION = 'v24.10-SOURCE-EXPLICIT-STANDARD-REQUIREMENTS'
# ===== END v24.10 =====

# ===== v24.11 LESSON RESOLUTION DIAGNOSTICS =====
def _lesson_resolution_status_v2411(ss):
    trace=ss.get('_pdp_source_trace_v2405') or _lesson_context_trace_v2405(ss)
    if trace.get('standards_verified'):
        return 'verified_standards'
    if trace.get('standards_not_applicable'):
        return 'not_applicable_explicit_source'
    return 'open_gap'

def _lesson_resolution_label_v2411(ss):
    st=_lesson_resolution_status_v2411(ss)
    if st=='verified_standards': return '✅ SK/SP disahkan'
    if st=='not_applicable_explicit_source': return 'ℹ️ SK/SP khusus tidak berkaitan untuk Lesson ini berdasarkan sumber'
    return '🚧 Status SK/SP masih dalam pembinaan'

def _lesson_package_readiness_v2409(ss):
    diag=_lesson_package_diagnostic_v2408(ss); cov=diag.get('coverage') or {}; manifest=diag.get('manifest') or {}; blockers=[]
    resolution=_lesson_resolution_status_v2411(ss)
    if not cov.get('lesson'): blockers.append('Lesson RPT/SOW belum verified')
    if resolution=='open_gap': blockers.append('status SK/SP Lesson belum disahkan')
    # Missing textbook page is reported as a coverage gap but does not destroy partial-success core if lesson+standards are resolved.
    coverage_notes=[]
    if not cov.get('textbook_page'): coverage_notes.append('🚧 Halaman Buku Teks masih dalam pembinaan')
    if not cov.get('activity_book'): coverage_notes.append('🚧 Pemetaan Buku Aktiviti masih dalam pembinaan')
    if not cov.get('media_requirement_known'): coverage_notes.append('🚧 Keperluan Audio/Media masih dalam pembinaan')
    return {'can_process_core':bool(cov.get('lesson') and resolution!='open_gap'),
      'mandatory_components':('RPH','Worksheet','BBM'),'blockers':blockers,'coverage_notes':coverage_notes,
      'standard_resolution':resolution,'standard_resolution_label':_lesson_resolution_label_v2411(ss),
      'manifest':manifest,'coverage':cov,'mapping_key':_lesson_mapping_key_v2409(ss)}

APP_VERSION = 'v24.11-LESSON-RESOLUTION-DIAGNOSTICS'
