# ===== v24.13 LARGE BATCH: LESSON MATERIAL POLICY + COVERAGE VIEW =====
# Every verified Lesson requires a Worksheet and BBM by CikguLaju project policy.
# Audio/Media remains tri-state: required / not related / unknown; unknown is never inferred.
def _lesson_material_gate_v2406(ss):
    trace=ss.get('_pdp_source_trace_v2405') or _lesson_context_trace_v2405(ss)
    req=_lesson_material_requirement_v2407(ss); activity=_lesson_activity_book_rows_v2407(ss); media=_lesson_media_rows_v2407(ss)
    media_required=(None if req is None or req.get('media_required') is None else bool(req.get('media_required')))
    if media: media_required=True
    standards_ok=bool(trace.get('standards_verified') or trace.get('standards_not_applicable'))
    return {
        'lesson_verified':bool(trace.get('lesson_verified')),
        'standards_verified':bool(trace.get('standards_verified')),
        'standards_not_applicable':bool(trace.get('standards_not_applicable')),
        'standard_requirement':trace.get('standard_requirement'),
        'page_verified':bool(trace.get('page_start') or ss.get('textbook_page') or ss.get('page')),
        'worksheet_required':True,
        'bbm_required':True,
        'activity_book':True if activity else None,
        'activity_book_rows':activity,
        'media_required':media_required,
        'media_rows':media,
        'requirements_verified':bool(req),
        'ready_for_generation':bool(trace.get('lesson_verified') and standards_ok),
    }

def _lesson_package_manifest_v2407(ss):
    g=_lesson_material_gate_v2406(ss)
    buildable=bool(g.get('ready_for_generation'))
    media_required=g.get('media_required')
    return {
      'RPH': {'required':True,'status':'ready_to_build' if buildable else 'under_construction'},
      'Worksheet': {'required':True,'status':'ready_to_build' if buildable else 'under_construction'},
      'BBM': {'required':True,'status':'ready_to_build' if buildable else 'under_construction'},
      'Buku Teks': {'required':True,'status':'mapped' if g.get('page_verified') else 'under_construction'},
      'Buku Aktiviti': {'required':None,'status':'mapped' if g.get('activity_book_rows') else 'under_construction'},
      'Audio/Media': {'required':media_required,'status':('mapped' if g.get('media_rows') else ('not_related' if media_required is False else 'under_construction'))},
    }

def _lesson_package_status_text_v2408(ss):
    m=_lesson_package_manifest_v2407(ss)
    label={'mapped':'Tersedia','ready_to_build':'Sedia diproses','under_construction':'🚧 Dalam pembinaan','not_related':'Tidak berkaitan'}
    icons={'RPH':'📘','Worksheet':'📝','BBM':'🎨','Buku Teks':'📖','Buku Aktiviti':'📚','Audio/Media':'🔊'}
    return '\n'.join(f"{icons.get(k,'•')} {k} — {label.get(v.get('status'),v.get('status',''))}" for k,v in m.items())

