# ===== v24.14 PRIMARY VERIFIED LESSON RESOLUTION =====
# Primary BI SOW lesson menus can be resolved from verified textbook_page_sp_map evidence
# when a dedicated textbook_page_lesson_map row is not yet present. No Lesson/SK/SP is invented.
def _verified_lesson_rows_v2404(year_label, subject, selected_content=''):
    con=_db()
    try:
        _ensure_textbook_page_lesson_map_schema(con)
        rows=[dict(r) for r in con.execute("""SELECT * FROM textbook_page_lesson_map
            WHERE year_label=? AND subject=? AND verified=1
            ORDER BY unit_title, page_start, id""",(year_label,subject)).fetchall()]
        # Primary verified fallback: group existing page/SP evidence into real SOW lesson choices.
        if not rows and str(year_label or '').startswith('Tahun '):
            src=con.execute("""SELECT year_label,subject,book_title,unit_title,page_start,page_end,lesson_no,focus,
                       MIN(source_url) source_url,1 verified
                FROM textbook_page_sp_map
                WHERE year_label=? AND subject=? AND verified=1
                GROUP BY year_label,subject,book_title,unit_title,page_start,page_end,lesson_no,focus
                ORDER BY unit_title,page_start,lesson_no,focus""",(year_label,subject)).fetchall()
            rows=[]
            for x in src:
                d=dict(x); d.setdefault('content_topic',''); d.setdefault('language_focus',''); d.setdefault('activity_ref','')
                d['notes']='Resolved from verified textbook_page_sp_map/SOW evidence; no lesson sequence fabricated.'
                rows.append(d)
    finally:
        con.close()
    if selected_content:
        rows=[r for r in rows if _content_match_v2405(r,selected_content)]
    out=[]; seen=set()
    for r in rows:
        k=(str(r.get('unit_title') or '').casefold(),str(r.get('lesson_no') or '').casefold(),r.get('page_start'),r.get('page_end'),str(r.get('focus') or '').casefold())
        if k in seen: continue
        seen.add(k); out.append(r)
    return out

def _primary_verified_lesson_coverage_v2414():
    con=_db()
    try:
        rows=con.execute("""SELECT year_label,COUNT(*) n FROM (
          SELECT year_label,subject,book_title,unit_title,page_start,page_end,lesson_no,focus
          FROM textbook_page_sp_map WHERE verified=1 AND year_label LIKE 'Tahun %'
          GROUP BY year_label,subject,book_title,unit_title,page_start,page_end,lesson_no,focus
        ) GROUP BY year_label ORDER BY year_label""").fetchall()
        return {str(r[0]):int(r[1]) for r in rows}
    finally: con.close()

