# Upload app.py together with migration_bm1_v24_24.sql. The runtime DB is upgraded
# in place; the large curriculum DB file does not need to be replaced.
def _apply_bm1_small_migration_v2425():
    import os as _os
    sql_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), 'migration_bm1_v24_24.sql')
    if not _os.path.exists(sql_path):
        return False
    con = _db()
    try:
        # Fast idempotency check.
        r = con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='bm1_dbfirst_package_v2424'").fetchone()
        if r:
            n = con.execute("SELECT COUNT(*) FROM bm1_dbfirst_package_v2424").fetchone()[0]
            if int(n or 0) >= 29:
                return True
        with open(sql_path, 'r', encoding='utf-8') as f:
            con.executescript(f.read())
        return True
    except Exception as e:
        print('v24.25 BM1 migration:', repr(e), flush=True)
        return False
    finally:
        con.close()

