def callback(cid, d):
    ss = state.setdefault(cid, {})
    ds = str(d or '')

    # Subject selection in the main PdP flow always opens verified content-first menu.
    if ds.startswith('sub_') and _is_quick_pdp_v2428(ss):
        ss['task'] = 'quick_material'
        ss['quick_material_flow'] = True
        ss['subject'] = ds[4:]
