    # Defensive compatibility for already-open legacy Telegram messages: if a teacher
    # taps an old topic button while in Sediakan Bahan PdP, redirect to source-first
    # content selection instead of opening SK/SP.
    if ds.startswith('topic_') and _is_quick_pdp_v2428(ss) and ss.get('rph_mode') != 'fast_custom':
        ss['task'] = 'quick_material'
