    # Date/time from a previous class must never leak into this session.
    for k in ('rph_date','rph_day','rph_time','rph_start_time','rph_end_time','duration_minutes','_pdp_calendar_v2429'):
        ss.pop(k,None)
    _pdp_calendar_month_v2429(cid)
