def _lesson_only_rows_v2436(items):
    """Build lesson buttons. page_start/page_end are display metadata, never a selection step."""
    rows=[]
    for i,item in enumerate(items or []):
        if isinstance(item,dict):
            lesson=str(item.get('lesson_no') or item.get('lesson') or item.get('lesson_label') or '').strip()
            ps=item.get('page_start'); pe=item.get('page_end')
        else:
            lesson=str(item).strip(); ps=pe=None
        if not lesson: continue
        label=f'📚 Lesson {lesson}' if not lesson.lower().startswith('lesson') else f'📚 {lesson}'
        if ps not in (None,''):
            page=str(ps) if pe in (None,'',ps) else f'{ps}–{pe}'
            label += f' · m/s {page}'
        rows.append([{'text':label[:60],'callback_data':f'lesson36_{i}'}])
    return rows

def _show_lesson_only_v2436(cid, items=None):
    ss=state.setdefault(cid,{})
    if items is not None: ss['_lesson_items_v2436']=list(items)
    items=ss.get('_lesson_items_v2436') or ss.get('_lesson_items') or ss.get('lesson_items') or []
    rows=_lesson_only_rows_v2436(items)
    if not rows:
        return send(cid,'🚧 Senarai Lesson untuk pilihan ini belum tersedia.')
    send(cid,'📚 <b>Pilih Lesson</b>\n\nMuka surat dipaparkan sebagai rujukan sahaja. Tidak perlu pilih muka surat.',rows)

def _apply_lesson_v2436(cid, idx):
    ss=state.setdefault(cid,{})
    items=ss.get('_lesson_items_v2436') or ss.get('_lesson_items') or ss.get('lesson_items') or []
    try: item=items[int(idx)]
    except Exception: return _show_lesson_only_v2436(cid)
    if isinstance(item,dict):
        lesson=str(item.get('lesson_no') or item.get('lesson') or item.get('lesson_label') or '').strip()
        ss['lesson_no']=lesson; ss['lesson']=lesson
        for k in ('page_start','page_end','sk_code','sp_code','sk','sp'):
            if item.get(k) not in (None,''): ss[k]=item.get(k)
    else:
        ss['lesson_no']=str(item); ss['lesson']=str(item)
    # Lesson already determines page/SK/SP. Continue to class selection.
    nxt=globals().get('_pdp_class_options_v2393') or globals().get('_quick_class_options_v2393') or globals().get('show_classes')
    if callable(nxt): return nxt(cid)
    return None

def callback(cid,d):
    ds=str(d or '')
    if ds.startswith('lesson36_'):
        return _apply_lesson_v2436(cid,ds.split('_',1)[1])
    # Any explicit textbook page-selection entry is redirected to Lesson selection.
    low=ds.lower()
    if low in ('quick_page','choose_page','select_page','pick_page','textbook_page','qsrc92_textbook') or low.endswith(('_choose_page','_select_page','_pick_page')):
        return _show_lesson_only_v2436(cid)
    return _callback_dispatch_v2436_base(cid,d)

APP_VERSION='v24.36-LESSON-ONLY-FLOW'
# ===== END v24.36 =====


# ===== v24.37 FORCE MONTHLY CALENDAR =====
_callback_dispatch_v2437_base = callback

def _calendar_v2437(cid, year=None, month=None):
    ss=state.setdefault(cid,{})
    tz=timezone(timedelta(hours=8)); today=datetime.now(tz).date()
    year=int(year or today.year); month=int(month or today.month)
    first=date(year,month,1)
    nxt=date(year+1,1,1) if month==12 else date(year,month+1,1)
    ndays=(nxt-first).days
    names=['Januari','Februari','Mac','April','Mei','Jun','Julai','Ogos','September','Oktober','November','Disember']
    # Python Monday=0; calendar required Sunday first.
    offset=(first.weekday()+1)%7
    cells=[None]*offset+list(range(1,ndays+1))
    while len(cells)%7: cells.append(None)
    rows=[[{'text':x,'callback_data':'cal37_noop'} for x in ['Ah','Is','Se','Ra','Kh','Ju','Sa']]]
    for i in range(0,len(cells),7):
        rows.append([{'text':(' ' if d is None else str(d)),'callback_data':('cal37_noop' if d is None else f'cal37_pick_{year}_{month}_{d}')} for d in cells[i:i+7]])
    py,pm=(year-1,12) if month==1 else (year,month-1)
    ny,nm=(year+1,1) if month==12 else (year,month+1)
    rows.append([
        {'text':'◀️','callback_data':f'cal37_month_{py}_{pm}'},
        {'text':f'{names[month-1]} {year}','callback_data':'cal37_noop'},
        {'text':'▶️','callback_data':f'cal37_month_{ny}_{nm}'},
    ])
    ss['_calendar_v2437']=(year,month)
    send(cid,f'📅 <b>Pilih Tarikh — {names[month-1]} {year}</b>',rows)

def _calendar_pick_v2437(cid,y,m,d):
    ss=state.setdefault(cid,{})
    dt=date(int(y),int(m),int(d))
    days=['Isnin','Selasa','Rabu','Khamis','Jumaat','Sabtu','Ahad']
    ss['rph_date']=dt.isoformat(); ss['rph_day']=days[dt.weekday()]
    ss.pop('_pdp_dates_v2393',None)
    # Exactly one date selection, then time range.
    fn=globals().get('_time_hour_menu_v2435')
    if callable(fn): return fn(cid,'start')
    fn=globals().get('_pdp_time_options_v2393')
    if callable(fn): return fn(cid)

def callback(cid,d):
    ds=str(d or ''); low=ds.lower()
    if ds=='cal37_noop': return None
    if ds.startswith('cal37_month_'):
        _,_,y,m=ds.split('_',3); return _calendar_v2437(cid,y,m)
    if ds.startswith('cal37_pick_'):
        _,_,y,m,n=ds.split('_',4); return _calendar_pick_v2437(cid,y,m,n)
    # Intercept known/legacy date entry callbacks before older linear picker.
    date_entries=('pdpdate93_back','pdpdate93_change','pdpdate93_pick','quick_date','rph_date','worksheet_date','bbm_date','choose_date','select_date','pick_date')
    if low in date_entries or low.endswith(('_choose_date','_select_date','_pick_date')):
        return _calendar_v2437(cid)
    return _callback_dispatch_v2437_base(cid,d)

APP_VERSION='v24.37-FORCE-MONTHLY-CALENDAR'
# ===== END v24.37 =====


