def _bm96_commit_pdp(cid,pdp_idx):
    ss=state.setdefault(cid,{})
    pdps=ss.get('_bm96_pdps') or []
    if pdp_idx<0 or pdp_idx>=len(pdps): return _bm96_theme_menu(cid)
    pdp=pdps[pdp_idx]
    rows=[r for r in (ss.get('_bm96_pdp_rows') or []) if str(r.get('pdp_title') or '').strip()==pdp]
    if not rows: return _bm96_theme_menu(cid)
    code,unit=ss.get('_bm96_unit') or ('','')
    r0=rows[0]
    mapped=[]
    seen=set()
    for r in rows:
        sk=str(r.get('sk_code') or '').strip(); sp=str(r.get('sp_code') or '').strip()
        key=(sk,sp)
        if sp and key not in seen:
            seen.add(key); mapped.append({'sk_code':sk,'sk_text':'','sp_code':sp,'sp_text':''})
    if not mapped:
        return send(cid,'🚧 <b>SK/SP yang disahkan untuk PdP ini belum lengkap.</b>',
                    [[{'text':'⬅️ Pilih PdP Lain','callback_data':'bm96_unit_0'}],[{'text':'🏠 Menu Utama','callback_data':'home'}]])
    ss.update({
        'task':'quick_material','quick_material_flow':True,'assessment_mode':'formative',
        'topic':unit,'subtopic':pdp,'pdp_title':pdp,'rpt_theme':str(r0.get('theme') or ''),
        'rpt_unit_title':unit,'rpt_topic':pdp,'skill_metadata':str(r0.get('skill_metadata') or ''),
        'textbook_ref':str(r0.get('textbook_ref') or ''),'activitybook_ref':str(r0.get('activitybook_ref') or '')
    })
    _commit_multi_sp(ss,mapped[:8])
    # After PdP, continue to class -> calendar -> time -> material package.
    fn=globals().get('_lesson_to_class_v2439') or globals().get('_pdp_pick_class_v2393')
    if callable(fn): return fn(cid)
    return _temporary_auto_pack_v2386(cid)

def callback(cid,d):
    ss=state.setdefault(cid,{})
